2. 입력값에 공백이 들어갈 수 있으므로 `trim()`을 적용하면 더 안전합니다.
3. 출금 시 “잘못된 금액”과 “잔액 부족” 메시지를 나누면 더 명확합니다.

아래는 해당 내용을 반영한 전체 예제 코드입니다.

```java
package practice;

import java.util.Scanner;
import java.math.BigInteger;

public class ThisIsJava4_7 {

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        BigInteger balance = BigInteger.ZERO;
        boolean run = true;

        while (run) {
            System.out.println("---------------------------------");
            System.out.println("1.예금 | 2.출금 | 3.잔고 | 4.종료");
            System.out.println("---------------------------------");
            System.out.print("선택> ");

            String menuChoice = scan.nextLine().trim();

            switch (menuChoice) {
                case "1":
                    System.out.print("예금액>");

                    try {
                        BigInteger deposit = new BigInteger(scan.nextLine().trim());

                        if (deposit.compareTo(BigInteger.ZERO) > 0) {
                            balance = balance.add(deposit);
                        } else {
                            System.out.println("올바른 값을 입력하시오");
                        }
                    } catch (NumberFormatException e) {
                        System.out.println("숫자로 입력하시오");
                    }

                    break;

                case "2":
                    System.out.print("출금액>");

                    try {
                        BigInteger withdraw = new BigInteger(scan.nextLine().trim());

                        if (withdraw.compareTo(BigInteger.ZERO) <= 0) {
                            System.out.println("올바른 값을 입력하시오");
                        } else if (withdraw.compareTo(balance) > 0) {
                            System.out.println("잔액이 부족합니다");
                        } else {
                            balance = balance.subtract(withdraw);
                        }
                    } catch (NumberFormatException e) {
                        System.out.println("숫자로 입력하시오");
                    }

                    break;

                case "3":
                    System.out.println("잔고>" + balance);
                    break;

                case "4":
                    run = false;
                    break;

                default:
                    System.out.println("1, 2, 3, 4 중 하나로 입력하시오");
                    break;
            }
        }

        System.out.println("프로그램 종료");
        scan.close();
    }
}
```

