use std::{
    collections::VecDeque,
    path::PathBuf,
    sync::mpsc::{self, Receiver},
    time::{Duration, SystemTime, UNIX_EPOCH},
};

use eframe::egui;
use notify::{
    event::{ModifyKind, RenameMode},
    Event, EventKind, RecommendedWatcher, RecursiveMode, Watcher,
};

const MAX_LOG_LINES: usize = 1000;

#[derive(Default)]
struct FolderMonitorApp {
    input_folder: Option<PathBuf>,
    output_folder: Option<PathBuf>,
    done_folder: Option<PathBuf>,

    watcher: Option<RecommendedWatcher>,
    events: Option<Receiver<notify::Result<Event>>>,

    log: VecDeque<String>,
}

impl FolderMonitorApp {
    fn add_log(&mut self, message: impl Into<String>) {
        let secs = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);
        self.log.push_back(format!("[{secs}] {}", message.into()));
        while self.log.len() > MAX_LOG_LINES {
            self.log.pop_front();
        }
    }

    fn folder_row(ui: &mut egui::Ui, title: &str, button_text: &str, folder: &mut Option<PathBuf>) {
        ui.horizontal(|ui| {
            if ui.button(button_text).clicked() {
                let mut dialog = rfd::FileDialog::new().set_title(title);
                if let Some(current) = folder.as_ref() {
                    dialog = dialog.set_directory(current.clone());
                }
                if let Some(selected) = dialog.pick_folder() {
                    *folder = Some(selected);
                }
            }

            match folder {
                Some(path) => ui.label(path.display().to_string()),
                None => ui.weak("No folder selected"),
            };
        });
    }

    fn start_monitoring(&mut self, ctx: &egui::Context) {
        if self.watcher.is_some() {
            self.add_log("Already monitoring.");
            return;
        }

        let Some(input_folder) = self.input_folder.clone() else {
            self.add_log("Please select the input folder before starting.");
            return;
        };

        if !input_folder.is_dir() {
            self.add_log(format!(
                "Input folder does not exist or is not a directory: {}",
                input_folder.display()
            ));
            return;
        }

        let (tx, rx) = mpsc::channel::<notify::Result<Event>>();
        let repaint_ctx = ctx.clone();

        let watcher_result = notify::recommended_watcher(move |event: notify::Result<Event>| {
            if tx.send(event).is_ok() {
                repaint_ctx.request_repaint();
            }
        });

        let mut watcher = match watcher_result {
            Ok(watcher) => watcher,
            Err(err) => {
                self.add_log(format!("Failed to create watcher: {err}"));
                return;
            }
        };

        if let Err(err) = watcher.watch(&input_folder, RecursiveMode::NonRecursive) {
            self.add_log(format!(
                "Failed to start watching {}: {err}",
                input_folder.display()
            ));
            return;
        }

        self.watcher = Some(watcher);
        self.events = Some(rx);
        self.add_log(format!("Started monitoring {}", input_folder.display()));
    }

    fn stop_monitoring(&mut self) {
        if self.watcher.is_some() {
            self.watcher = None;
            self.events = None;
            self.add_log("Stopped monitoring.");
        }
    }

    fn receive_events(&mut self) {
        for _ in 0..256 {
            let received = self
                .events
                .as_ref()
                .and_then(|rx| rx.try_recv().ok());

            match received {
                Some(Ok(event)) => self.handle_event(event),
                Some(Err(err)) => self.add_log(format!("Watcher error: {err}")),
                None => break,
            }
        }
    }

    fn handle_event(&mut self, event: Event) {
        let is_arrival = matches!(
            event.kind,
            EventKind::Create(_)
                | EventKind::Modify(ModifyKind::Name(
                    RenameMode::To | RenameMode::Both | RenameMode::Any
                ))
        );

        if !is_arrival {
            return;
        }

        let kind_text = format!("{:?}", event.kind);

        let paths: Vec<PathBuf> = if matches!(
            event.kind,
            EventKind::Modify(ModifyKind::Name(RenameMode::Both))
        ) {
            event.paths.into_iter().last().into_iter().collect()
        } else {
            event.paths
        };

        for path in paths {
            match std::fs::metadata(&path) {
                Ok(metadata) if metadata.is_file() => {
                    self.add_log(format!(
                        "New file | Event: {kind_text} | Path: {} | Size: {} bytes",
                        path.display(),
                        metadata.len()
                    ));
                }
                Ok(_) => {
                    // A directory arrived; the prompt asked for files, so ignore it.
                }
                Err(err) => {
                    self.add_log(format!(
                        "New file event, but metadata could not be read | Event: {kind_text} | Path: {} | Error: {err}",
                        path.display()
                    ));
                }
            }
        }
    }
}

impl eframe::App for FolderMonitorApp {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        self.receive_events();

        let monitoring = self.watcher.is_some();
        if monitoring {
            ctx.request_repaint_after(Duration::from_millis(100));
        }

        egui::CentralPanel::default().show(ctx, |ui| {
            ui.heading("Folder Monitor");
            ui.add_space(8.0);

            ui.add_enabled_ui(!monitoring, |ui| {
                Self::folder_row(ui, "Select input folder", "Select input folder", &mut self.input_folder);
                Self::folder_row(ui, "Select output folder", "Select output folder", &mut self.output_folder);
                Self::folder_row(ui, "Select done folder", "Select done folder", &mut self.done_folder);
            });

            ui.add_space(8.0);

            ui.horizontal(|ui| {
                if ui
                    .add_enabled(!monitoring, egui::Button::new("Start"))
                    .clicked()
                {
                    self.start_monitoring(ctx);
                }

                if ui
                    .add_enabled(monitoring, egui::Button::new("Stop"))
                    .clicked()
                {
                    self.stop_monitoring();
                }

                if ui.button("Clear log").clicked() {
                    self.log.clear();
                }
            });

            ui.label(if monitoring {
                "Status: monitoring input folder"
            } else {
                "Status: stopped"
            });

            ui.separator();

            egui::ScrollArea::vertical()
                .stick_to_bottom(true)
                .auto_shrink([false, false])
                .show(ui, |ui| {
                    for line in &self.log {
                        ui.monospace(line);
                    }
                });
        });
    }
}

fn main() -> eframe::Result<()> {
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_inner_size(egui::vec2(900.0, 560.0))
            .with_min_inner_size(egui::vec2(620.0, 360.0)),
        ..Default::default()
    };

    eframe::run_native(
        "Folder Monitor",
        options,
        Box::new(|_cc| Ok(Box::new(FolderMonitorApp::default()))),
    )
}
```

