#include <stdio.h>

/*
  Returns the largest index i such that arr[i] < target.
  Returns -1 if no such element exists.

  arr: monotonically increasing array
  n: number of elements in arr
  target: value to compare against
*/
int find_last_less(const int arr[], int n, int target)
{
    int low = 0;
    int high = n;

    /*
      Find the first index where arr[index] >= target.
      The answer is then index - 1.
    */
    while (low < high) {
        int mid = low + (high - low) / 2;

        if (arr[mid] < target) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }

    return low - 1;
}

int main(void)
{
