    if (joy2_y < 400 && player_y > 1) {
      player_y--;
    }
    if (joy2_y > 600 && player_y < 31 - PADDLE_HEIGHT) {
      player_y++;
    }
    display.drawFastVLine(PLAYER_X, player_y, PADDLE_HEIGHT, WHITE);

    update = true;
  }

  if (update) {
    display.display();
  }
}

void drawCourt() {
  display.drawRect(0, 0, SCREEN_WIDTH, SCREEN_HEIGHT, WHITE);
}

void restartGame() {
  ball_x = 64;
  ball_y = 16;
  ball_dir_x = 1;
  ball_dir_y = 1;

  cpu_y = 8;
  player_y = 8;

  display.clearDisplay();
  drawCourt();

  display.drawFastVLine(CPU_X, cpu_y, PADDLE_HEIGHT, WHITE);
  display.drawFastVLine(PLAYER_X, player_y, PADDLE_HEIGHT, WHITE);
  display.fillRect(ball_x, ball_y, BALL_SIZE, BALL_SIZE, WHITE);

  display.display();

  unsigned long now = millis();
  ball_update = now + BALL_RATE;
  paddle_update = now + PADDLE_RATE;
}

bool restartPressed() {
  bool reading = digitalRead(RESTART_BUTTON);
  unsigned long now = millis();

  if (reading != lastReading) {
    lastChange = now;
    lastReading = reading;
  }

  if (now - lastChange >= DEBOUNCE_DELAY) {
    if (reading != buttonState) {
      buttonState = reading;

      // При INPUT_PULLUP нажатие кнопки дает LOW
      if (buttonState == LOW) {
        return true;
      }
    }
  }

  return false;
}
