// Возвращает true один раз в момент нажатия кнопки
bool restartPressed() {
  static bool lastReading = HIGH;
  static bool stableState = HIGH;
  static unsigned long lastChange = 0;

  const unsigned long debounce = 30;

  bool reading = digitalRead(RESTART_PIN);
  unsigned long now = millis();

  if (reading != lastReading) {
    lastChange = now;
  }

  lastReading = reading;

  if (now - lastChange >= debounce) {
    if (reading != stableState) {
      stableState = reading;

      // При INPUT_PULLUP нажатие кнопки дает LOW
      if (stableState == LOW) {
        return true;
      }
    }
  }

  return false;
