```js
const position = world.getPosition(bot);

const centerX = Math.floor(position.x);
const centerZ = Math.floor(position.z);
const baseY = Math.floor(position.y) - 1;

// Use an odd width so the pyramid has a centered single-block peak.
const width = 61;
const height = (width + 1) / 2;
const halfWidth = Math.floor(width / 2);

for (let layer = 0; layer < height; layer++) {
    const y = baseY + layer;

    const minX = centerX - halfWidth + layer;
    const maxX = centerX + halfWidth - layer;
    const minZ = centerZ - halfWidth + layer;
    const maxZ = centerZ + halfWidth - layer;

    for (let x = minX; x <= maxX; x++) {
        for (let z = minZ; z <= maxZ; z++) {
            const isEdge =
                x === minX ||
                x === maxX ||
                z === minZ ||
                z === maxZ;

            // Build the base solid, then only build the outer edge of each higher layer.
            if (layer === 0 || isEdge) {
                await skills.placeBlock(bot, 'sandstone', x, y, z);
            }
        }
    }
}
```

