Here is a complete HTML/CSS example that creates glowing text with an animated rainbow gradient border around it. No JavaScript is required.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Glowing Rainbow Text</title>

  <style>
    @property --angle {
      syntax: "<angle>";
      initial-value: 0deg;
      inherits: false;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 1rem;
      background: #050508;
      font-family: system-ui, -apple-system, sans-serif;
    }

    .rainbow-glow {
      --border: 4px;
      --radius: 22px;
      --angle: 0deg;

      position: relative;
      isolation: isolate;
      padding: var(--border);
      border-radius: var(--radius);

      background: conic-gradient(
        from var(--angle),
        #ff005e,
        #ff7a00,
        #ffe600,
        #00ff85,
        #00cfff,
        #7a5cff,
        #ff00d4,
        #ff005e
      );

      animation: rotate-rainbow 4s linear infinite;
    }

    /* Blurred copy of the gradient to create the outer glow */
    .rainbow-glow::before {
      content: "";
      position: absolute;
      inset: -10px;
      z-index: -1;
      border-radius: inherit;

      background: conic-gradient(
        from var(--angle),
        #ff005e,
        #ff7a00,
        #ffe600,
        #00ff85,
        #00cfff,
        #7a5cff,
        #ff00d4,
        #ff005e
      );

      filter: blur(24px);
      opacity: 0.75;
      pointer-events: none;

      animation: rotate-rainbow 4s linear infinite;
    }

    .content {
      border-radius: calc(var(--radius) - var(--border));
      background: #0b0b16;
      padding: clamp(1.5rem, 5vw, 3rem) clamp(2rem, 7vw, 4.5rem);
    }

    .glowing-text {
      margin: 0;
      color: #fff;
      font-size: clamp(2rem, 8vw, 4.5rem);
      font-weight: 900;
      letter-spacing: 0.07em;
      text-align: center;
      text-transform: uppercase;
      overflow-wrap: anywhere;

      text-shadow:
        0 0 6px rgba(255, 255, 255, 0.9),
        0 0 18px rgba(0, 207, 255, 0.8),
        0 0 38px rgba(122, 92, 255, 0.7),
        0 0 65px rgba(255, 0, 212, 0.55);

      animation: pulse-glow 2.4s ease-in-out infinite alternate;
    }

    @keyframes rotate-rainbow {
      to {
        --angle: 360deg;
      }
    }

    @keyframes pulse-glow {
      to {
        text-shadow:
          0 0 10px rgba(255, 255, 255, 1),
          0 0 28px rgba(0, 207, 255, 0.95),
          0 0 55px rgba(122, 92, 255, 0.85),
          0 0 90px rgba(255, 0, 212, 0.7);
      }
    }

    @media (prefers-reduced-motion: reduce) {
      .rainbow-glow,
      .rainbow-glow::before,
      .glowing-text {
        animation: none;
      }
    }
  </style>
</head>
<body>
  <div class="rainbow-glow">
    <div class="content">
      <h1 class="glowing-text">Rainbow Glow</h1>
    </div>
  </div>
</body>
</html>
```

