<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Glowing Rainbow Text</title>
<style>
@property --angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: true;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #050508;
  font-family: system-ui, sans-serif;
}

.rainbow-wrap {
  --border: 4px;
  --radius: 22px;
  position: relative;
  isolation: isolate;
  padding: var(--border);
  border-radius: var(--radius);
  background: conic-gradient(from var(--angle), #ff005e, #ff7a00, #ffe600, #00ff85, #00cfff, #7a5cff, #ff00d4, #ff005e);
  animation: spin 4s linear infinite;
}

.rainbow-wrap::before {
  content: "";
  position: absolute;
  inset: -10px;
  z-index: -1;
  border-radius: inherit;
  background: inherit;
  filter: blur(24px);
  opacity: 0.75;
  pointer-events: none;
}

.panel {
  border-radius: calc(var(--radius) - var(--border));
  background: #0b0b14;
  padding: clamp(1.25rem, 4vw, 2.5rem) clamp(1.75rem, 6vw, 4rem);
}

.text {
  margin: 0;
  color: #fff;
  font-size: clamp(2rem, 7vw, 4.5rem);
  font-weight: 900;
  text-align: center;
  letter-spacing: 0.06em;
  text-shadow:
    0 0 6px rgba(255,255,255,.9),
    0 0 18px rgba(0,207,255,.8),
    0 0 36px rgba(122,92,255,.7),
    0 0 60px rgba(255,0,212,.5);
  animation: pulse 2.4s ease-in-out infinite alternate;
}

@keyframes spin {
  to { --angle: 360deg; }
}

@keyframes pulse {
  to {
    text-shadow:
      0 0 10px rgba(255,255,255,1),
      0 0 28px rgba(0,207,255,.95),
      0 0 52px rgba(122,92,255,.85),
      0 0 85px rgba(255,0,212,.65);
  }
}

@media (prefers-reduced-motion: reduce) {
  .rainbow-wrap, .text { animation: none; }
}
</style>
</head>
<body>
<div class="rainbow-wrap">
  <div class="panel">
    <h1 class="text">Glowing Rainbow</h1>
  </div>
</div>
</body>
</html>

