using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

namespace StudentMaintenance
{
    public static class StudentDB
    {
        // Same style as CustomerDB. If your instructor requires C:\C#\files\, replace Dir with that.
        private static readonly string Dir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "StudentMaintenance");
        private static readonly string Path = Path.Combine(Dir, "Students.dat");

        public static void SaveStudents(List<Student> students)
        {
            Directory.CreateDirectory(Dir);
            using BinaryWriter binaryOut = new BinaryWriter(new FileStream(Path, FileMode.Create, FileAccess.Write), Encoding.UTF8);
            foreach (Student s in students)
            {
                binaryOut.Write(s.StudentID);
                binaryOut.Write(s.Name);
                binaryOut.Write(s.GPA);
            }
        }

        public static List<Student> GetStudents()
        {
            List<Student> students = new();
            if (!File.Exists(Path)) return students;
            using BinaryReader binaryIn = new BinaryReader(new FileStream(Path, FileMode.Open, FileAccess.Read), Encoding.UTF8);
            while (binaryIn.BaseStream.Position < binaryIn.BaseStream.Length)
            {
                Student s = new()
                {
                    StudentID = binaryIn.ReadInt32(),
                    Name = binaryIn.ReadString(),
                    GPA = binaryIn.ReadDecimal()
                };
                students.Add(s);
            }
            return students;
        }
    }
}
