using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

namespace StudentMaintenance
{
    /// <summary>
    /// Handles saving and loading Student objects with BinaryWriter and BinaryReader.
    /// </summary>
    public static class StudentDB
    {
        // Safer location than C:\C#\files because it does not require elevated permission.
        private static readonly string Dir =
            System.IO.Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "StudentMaintenance");

        private static readonly string FilePath =
            System.IO.Path.Combine(Dir, "Students.dat");

        /// <summary>
        /// Saves all students to the binary file.
        /// FileMode.Create replaces the existing file.
        /// </summary>
        public static void SaveStudents(List<Student> students)
        {
            if (students == null)
                throw new ArgumentNullException(nameof(students));

            // Make sure the folder exists before writing.
            Directory.CreateDirectory(Dir);

            // The using statement disposes the BinaryWriter and closes the FileStream.
            using BinaryWriter binaryOut = new BinaryWriter(
                new FileStream(FilePath, FileMode.Create, FileAccess.Write),
                Encoding.UTF8);

            foreach (Student student in students)
            {
                // The read method must read these fields in the same order.
                binaryOut.Write(student.StudentID);
                binaryOut.Write(student.Name ?? string.Empty);
                binaryOut.Write(student.GPA);
            }
        }

        /// <summary>
        /// Reads all students from the binary file.
        /// </summary>
        public static List<Student> GetStudents()
        {
            List<Student> students = new List<Student>();

            // Make sure the folder exists before trying to open the file.
            Directory.CreateDirectory(Dir);

            // The using statement disposes the BinaryReader and closes the FileStream.
            using BinaryReader binaryIn = new BinaryReader(
                new FileStream(FilePath, FileMode.OpenOrCreate, FileAccess.Read),
                Encoding.UTF8);

            // Read until the end of the binary file.
            while (binaryIn.BaseStream.Position < binaryIn.BaseStream.Length)
            {
                Student student = new Student
                {
                    StudentID = binaryIn.ReadInt32(),
                    Name = binaryIn.ReadString(),
                    GPA = binaryIn.ReadDecimal()
                };

                students.Add(student);
            }

            return students;
        }
    }
}
```

