        private readonly TextBox txtGPA = new TextBox();

        private readonly Button btnWrite = new Button();
        private readonly Button btnRead = new Button();

        private readonly ListBox lstStudents = new ListBox();

        public StudentForm()
        {
            Text = "Student Data Application";
            StartPosition = FormStartPosition.CenterScreen;
            ClientSize = new Size(650, 420);
            MinimumSize = new Size(550, 380);
            Font = new Font("Segoe UI", 9.75F);
            AutoScaleMode = AutoScaleMode.Font;

            BuildInterface();

            btnWrite.Click += BtnWrite_Click;
            btnRead.Click += BtnRead_Click;

            AcceptButton = btnWrite;
        }

        /// <summary>
        /// Creates the form layout using a TableLayoutPanel so the form remains resizable.
        /// </summary>
        private void BuildInterface()
        {
            TableLayoutPanel layout = new TableLayoutPanel
            {
                Dock = DockStyle.Fill,
                Padding = new Padding(12),
                ColumnCount = 2,
                RowCount = 5
            };

            layout.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 110));
            layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));

            for (int i = 0; i < 3; i++)
            {
                layout.RowStyles.Add(new RowStyle(SizeType.Absolute, 38));
            }

            layout.RowStyles.Add(new RowStyle(SizeType.Absolute, 48));
            layout.RowStyles.Add(new RowStyle(SizeType.Percent, 100));

            AddInputRow(layout, 0, "Student ID:", txtStudentID);
            AddInputRow(layout, 1, "Name:", txtName);
            AddInputRow(layout, 2, "GPA (0-4):", txtGPA);

            FlowLayoutPanel buttonPanel = new FlowLayoutPanel
            {
                FlowDirection = FlowDirection.LeftToRight,
                Dock = DockStyle.Fill,
                AutoSize = true,
                WrapContents = false
            };

            btnWrite.Text = "Write Data";
            btnWrite.AutoSize = true;

            btnRead.Text = "Read Data";
            btnRead.AutoSize = true;

            buttonPanel.Controls.Add(btnWrite);
            buttonPanel.Controls.Add(btnRead);

            layout.Controls.Add(buttonPanel, 1, 3);

            lstStudents.Dock = DockStyle.Fill;
            lstStudents.HorizontalScrollbar = true;
            lstStudents.IntegralHeight = false;

            layout.Controls.Add(lstStudents, 0, 4);
            layout.SetColumnSpan(lstStudents, 2);

            Controls.Add(layout);
        }

        /// <summary>
        /// Adds one label/textbox row to the layout.
        /// </summary>
        private static void AddInputRow(TableLayoutPanel layout, int row, string caption, TextBox textBox)
        {
            Label label = new Label
            {
                Text = caption,
                AutoSize = true,
                Anchor = AnchorStyles.Left,
                Margin = new Padding(3, 10, 3, 3)
            };

            textBox.Dock = DockStyle.Fill;

            layout.Controls.Add(label, 0, row);
            layout.Controls.Add(textBox, 1, row);
        }

        /// <summary>
        /// Validates all user input before writing a student record.
        /// </summary>
        private bool IsValidData(out string message)
        {
            message = string.Empty;

            string id = txtStudentID.Text.Trim();
            string name = txtName.Text.Trim();
            string gpa = txtGPA.Text.Trim();

            message += Validator.IsPresent(id, "Student ID");

            if (!string.IsNullOrWhiteSpace(id))
            {
                message += Validator.IsInt32(id, "Student ID");
                message += Validator.IsWithinRange(id, "Student ID", 1, int.MaxValue);
            }

            message += Validator.IsPresent(name, "Name");

            message += Validator.IsPresent(gpa, "GPA");

            if (!string.IsNullOrWhiteSpace(gpa))
            {
                message += Validator.IsDecimal(gpa, "GPA");
                message += Validator.IsWithinRange(gpa, "GPA", 0m, 4m);
            }

            return string.IsNullOrEmpty(message);
        }

        /// <summary>
        /// Writes the new student to the binary file while preserving existing students.
        /// </summary>
        private void BtnWrite_Click(object sender, EventArgs e)
        {
            if (!IsValidData(out string validationMessage))
            {
                MessageBox.Show(
                    this,
                    validationMessage,
                    "Input Error",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Warning);

                return;
            }

            try
            {
                // Load existing students first so previous records are not lost.
                List<Student> students = StudentDB.GetStudents();

                Student student = new Student
                {
                    StudentID = int.Parse(txtStudentID.Text.Trim()),
                    Name = txtName.Text.Trim(),
                    GPA = decimal.Parse(txtGPA.Text.Trim())
                };

                students.Add(student);

                StudentDB.SaveStudents(students);

                DisplayStudents(students);
                ClearInputs();

                MessageBox.Show(
                    this,
                    "Student data written successfully.",
                    "Success",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Information);
            }
            catch (EndOfStreamException)
            {
                ShowFileError("The student binary file is incomplete or corrupted.");
            }
            catch (UnauthorizedAccessException)
            {
                ShowFileError("Access denied. The application does not have permission to access the file.");
            }
            catch (IOException ex)
            {
                ShowFileError($"File error: {ex.Message}");
            }
            catch (Exception ex)
            {
                ShowFileError($"Unexpected error: {ex.Message}");
            }
        }

        /// <summary>
        /// Reads all students from the binary file and displays them in the ListBox.
        /// </summary>
        private void BtnRead_Click(object sender, EventArgs e)
        {
            try
            {
                List<Student> students = StudentDB.GetStudents();
                DisplayStudents(students);
            }
            catch (EndOfStreamException)
            {
                ShowFileError("The student binary file is incomplete or corrupted.");
            }
            catch (UnauthorizedAccessException)
            {
                ShowFileError("Access denied. The application does not have permission to access the file.");
            }
            catch (IOException ex)
            {
                ShowFileError($"File error: {ex.Message}");
            }
            catch (Exception ex)
            {
                ShowFileError($"Unexpected error: {ex.Message}");
            }
        }

        /// <summary>
        /// Displays student objects in the ListBox.
        /// </summary>
        private void DisplayStudents(List<Student> students)
        {
            lstStudents.Items.Clear();

            if (students.Count == 0)
            {
                lstStudents.Items.Add("No student data found.");
                return;
            }

            foreach (Student student in students)
            {
                lstStudents.Items.Add(student);
            }
        }

        /// <summary>
        /// Clears input controls and returns focus to the Student ID textbox.
        /// </summary>
        private void ClearInputs()
        {
            txtStudentID.Clear();
            txtName.Clear();
            txtGPA.Clear();
            txtStudentID.Focus();
        }

        /// <summary>
        /// Shows file-related errors in a consistent message box.
        /// </summary>
        private void ShowFileError(string message)
        {
            MessageBox.Show(
                this,
                message,
                "File Error",
                MessageBoxButtons.OK,
                MessageBoxIcon.Error);
        }
    }
}
