    {
        // If your instructor requires the exact template folder, replace Dir/FilePath with:
        // private const string Dir = @"C:\C#\files\";
        // private const string FilePath = Dir + "Students.dat";
        private static readonly string Dir =
            System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                                   "StudentMaintenance");
        private static readonly string FilePath = System.IO.Path.Combine(Dir, "Students.dat");

        public static void SaveStudents(List<Student> students)
        {
            if (students == null) throw new ArgumentNullException(nameof(students));
            Directory.CreateDirectory(Dir);
            using BinaryWriter binaryOut = new BinaryWriter(
                new FileStream(FilePath, FileMode.Create, FileAccess.Write),
                Encoding.UTF8);
            foreach (Student student in students)
            {
                binaryOut.Write(student.StudentID);
                binaryOut.Write(student.Name ?? string.Empty);
                binaryOut.Write(student.GPA);
            }
        }

        public static List<Student> GetStudents()
        {
            List<Student> students = new List<Student>();
            Directory.CreateDirectory(Dir);
            using BinaryReader binaryIn = new BinaryReader(
                new FileStream(FilePath, FileMode.OpenOrCreate, FileAccess.Read),
                Encoding.UTF8);
            while (binaryIn.BaseStream.Position < binaryIn.BaseStream.Length)
            {
                Student student = new Student
                {
                    StudentID = binaryIn.ReadInt32(),
                    Name = binaryIn.ReadString(),
                    GPA = binaryIn.ReadDecimal()
                };
                students.Add(student);
            }
            return students;
        }
    }
}
