    public static class Validator
    {
        public static string LineEnd { get; set; } = Environment.NewLine;
        public static string IsPresent(string value, string name)
        {
            return string.IsNullOrWhiteSpace(value) ? $"{name} is a required field.{LineEnd}" : string.Empty;
        }
        public static string IsInt32(string value, string name)
        {
            return int.TryParse(value, out _) ? string.Empty : $"{name} must be a valid integer value.{LineEnd}";
        }
        public static string IsDecimal(string value, string name)
        {
            return decimal.TryParse(value, out _) ? string.Empty : $"{name} must be a valid decimal value.{LineEnd}";
        }
        public static string IsWithinRange(string value, string name, decimal min, decimal max)
        {
            if (decimal.TryParse(value, out decimal number) && (number < min || number > max))
                return $"{name} must be between {min} and {max}.{LineEnd}";
            return string.Empty;
        }
    }
}
