My answer to the user prompt:

C++ does not normally use a tracing garbage collector. The idiomatic way to get automatic cleanup for a linked list is to use RAII with smart pointers. For a singly linked list, each node can own its next node using `std::unique_ptr`. When the list is destroyed, nodes are freed automatically.

A robust version should destroy nodes iteratively to avoid deep recursive destruction for very long lists.

```cpp
#include <iostream>
#include <memory>
#include <utility>

template <typename T>
class LinkedList {
private:
    struct Node {
        T value;
        std::unique_ptr<Node> next;

        explicit Node(T v) : value(std::move(v)) {}
    };

    std::unique_ptr<Node> head;

public:
    LinkedList() = default;

    // The list owns its nodes uniquely, so disable copying.
    LinkedList(const LinkedList&) = delete;
    LinkedList& operator=(const LinkedList&) = delete;

    ~LinkedList() {
        clear();
    }

    void push_front(T value) {
        auto node = std::make_unique<Node>(std::move(value));
        node->next = std::move(head);
        head = std::move(node);
    }

    void pop_front() {
        if (!head) return;

        auto old = std::move(head);
        head = std::move(old->next);

        // old is destroyed here automatically.
    }

    void clear() {
        // Iterative cleanup avoids recursive destruction of a long list.
        while (head) {
            auto old = std::move(head);
            head = std::move(old->next);
        }
    }

    bool empty() const {
        return !head;
    }

    void print() const {
        for (const Node* p = head.get(); p != nullptr; p = p->next.get()) {
            std::cout << p->value << " -> ";
        }
        std::cout << "nullptr\n";
    }
};

int main() {
    LinkedList<int> list;

    list.push_front(3);
    list.push_front(2);
    list.push_front(1);

    list.print(); // 1 -> 2 -> 3 -> nullptr

    list.pop_front();
    list.print(); // 2 -> 3 -> nullptr

    list.clear();
    list.print(); // nullptr

    return 0;
} // Any remaining nodes would be freed automatically.
```

For a doubly linked list, use an owning `std::unique_ptr` for `next` and a non-owning raw pointer or `std::weak_ptr` for `prev` to avoid ownership cycles.

