    };

    double y_interpolated[newCount];

    for (int i = 0; i < newCount; ++i) {
        // Equivalent to np.linspace(0, originalCount - 1, newCount)
        double x = static_cast<double>(i) * (originalCount - 1) / (newCount - 1);

        // Since the original x-values are 0, 1, 2, ..., originalCount - 1,
        // the integer part gives the left interpolation index.
        int left = static_cast<int>(x);

        if (left >= originalCount - 1) {
            y_interpolated[i] = y[originalCount - 1];
        } else {
            double fraction = x - left;
            y_interpolated[i] = y[left] + fraction * (y[left + 1] - y[left]);
        }
    }

    std::cout << "Interpolated values:\n[";
    for (int i = 0; i < newCount; ++i) {
        if (i != 0) std::cout << ' ';
        std::cout << y_interpolated[i];
    }
    std::cout << "]\n";

    return 0;
}
