My answer to the user prompt:

A safer alternative is to track the latest request instead of comparing the value of `x`, because value comparison can fail if `x` changes from `A -> B -> A`.

For Svelte 3/4:

```svelte
<script>
  let finalResult;
  let error;
  let requestId = 0;

  $: load(x);

  async function load(value) {
    const id = ++requestId;

    try {
      const result = await f(value);
      if (id === requestId) {
        finalResult = result;
      }
    } catch (err) {
      if (id === requestId) {
        error = err;
      }
    }
  }
</script>
```

For Svelte 5 using runes:

```svelte
<script>
  let finalResult = $state();
  let error = $state();

  $effect(() => {
    const value = x;
    let cancelled = false;

    f(value).then(
      result => {
        if (!cancelled) finalResult = result;
      },
      err => {
        if (!cancelled) error = err;
      }
    );

    return () => {
      cancelled = true;
    };
  });
</script>
```

If `f` supports cancellation, `AbortController` is even better:

```svelte
<script>
  let finalResult = $state();
  let error = $state();

  $effect(() => {
    const controller = new AbortController();

    f(x, { signal: controller.signal }).then(
      result => {
        if (!controller.signal.aborted) finalResult = result;
      },
      err => {
        if (!controller.signal.aborted) error = err;
      }
    );

    return () => controller.abort();
  });
</script>
```

If `x` is a store, another alternative is an async derived store:

```js
import { derived } from 'svelte/store';

const finalResult = derived(xStore, ($x, set) => {
  let active = true;

  f($x).then(result => {
    if (active) set(result);
  });

  return () => {
    active = false;
  };
}, undefined);
```

