```java
import java.net.URI;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.annotation.Order;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
import org.springframework.security.web.util.matcher.RequestMatcher;

@Configuration
public class SecurityConfig {

    @Bean
    @Order(1)
    SecurityFilterChain appAFilterChain(HttpSecurity http) throws Exception {
        http
            .securityMatcher(refererHostMatches("app-a.example.com"))
            .addFilterBefore(
                new AppAFilter(),
                UsernamePasswordAuthenticationFilter.class
            )
            .authorizeHttpRequests(auth -> auth
                .anyRequest().authenticated()
            )
            .httpBasic(Customizer.withDefaults());

        return http.build();
    }

    @Bean
    @Order(2)
    SecurityFilterChain appBFilterChain(HttpSecurity http) throws Exception {
        http
            .securityMatcher(refererHostMatches("app-b.example.com"))
            .addFilterBefore(
                new AppBFilter(),
                UsernamePasswordAuthenticationFilter.class
            )
            .authorizeHttpRequests(auth -> auth
                .anyRequest().authenticated()
            )
            .httpBasic(Customizer.withDefaults());

        return http.build();
    }

    @Bean
    @Order(3)
    SecurityFilterChain defaultFilterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth
                .anyRequest().authenticated()
            )
            .httpBasic(Customizer.withDefaults());

        return http.build();
    }

    private static RequestMatcher refererHostMatches(String expectedHost) {
        return request -> {
            String referer = request.getHeader("Referer");

            if (referer == null) {
                return false;
            }

            try {
                URI uri = URI.create(referer);

                return "https".equalsIgnoreCase(uri.getScheme())
                    && expectedHost.equalsIgnoreCase(uri.getHost());
            } catch (IllegalArgumentException ex) {
                return false;
            }
        };
    }
}
```

Key points:

- Spring Security chooses the **first matching** `SecurityFilterChain`.
- Use `@Order` to control which chain is evaluated first.
- The final chain without a `securityMatcher` acts as the fallback.
- The chains do **not** combine. If a request matches the first chain, only that chain is used.
