```zig
const std = @import("std");

const modulus: u64 = 33554393;
const multiplier: u64 = 252533;
const initial_code: u64 = 20151125;

fn modPow(base: u64, exp: u64) u64 {
    var b = base % modulus;
    var e = exp;
    var result: u64 = 1;

    while (e > 0) {
        if ((e & 1) != 0) {
            result = (result * b) % modulus;
        }
        b = (b * b) % modulus;
        e >>= 1;
    }

    return result;
}

fn nextNumber(text: []const u8, index: *usize) !u64 {
    while (index.* < text.len and (text[index.*] < '0' or text[index.*] > '9')) {
        index.* += 1;
    }

    const start = index.*;
    while (index.* < text.len and (text[index.*] >= '0' and text[index.*] <= '9')) {
        index.* += 1;
    }

    if (start == index.*) return error.NoNumber;
    return try std.fmt.parseInt(u64, text[start..index.*], 10);
}

pub fn main() !void {
    const allocator = std.heap.page_allocator;

    const input = try std.fs.cwd().readFileAlloc(
        allocator,
        "input.txt",
        1024 * 1024,
    );
    defer allocator.free(input);

    var index: usize = 0;
    const row = try nextNumber(input, &index);
    const column = try nextNumber(input, &index);

    if (row == 0 or column == 0) return error.InvalidCoordinate;

    // Zero-based diagonal index.
    const diagonal = row + column - 2;

    // Number of codes in all earlier diagonals:
