```zig
const std = @import("std");

const modulus: u64 = 33554393;
const multiplier: u64 = 252533;
const initial_code: u64 = 20151125;

fn modPow(base: u64, exp: u64) u64 {
    var b = base % modulus;
    var e = exp;
    var acc: u64 = 1;
    while (e > 0) {
        if ((e & 1) != 0) acc = (acc * b) % modulus;
        b = (b * b) % modulus;
        e >>= 1;
    }
    return acc;
}

fn nextNumber(text: []const u8, pos: *usize) !u64 {
    while (pos.* < text.len and (text[pos.*] < '0' or text[pos.*] > '9')) {
        pos.* += 1;
    }
    const start = pos.*;
    while (pos.* < text.len and text[pos.*] >= '0' and text[pos.*] <= '9') {
        pos.* += 1;
    }
    if (start == pos.*) return error.NoNumber;
    return try std.fmt.parseInt(u64, text[start..pos.*], 10);
}

pub fn main() !void {
    const allocator = std.heap.page_allocator;
    const input = try std.fs.cwd().readFileAlloc(allocator, "input.txt", 1024 * 1024);
    defer allocator.free(input);

    var pos: usize = 0;
    const row = try nextNumber(input, &pos);
    const column = try nextNumber(input, &pos);
    if (row == 0 or column == 0) return error.BadCoordinate;

    const diagonal = row + column - 2;
    const before = if (diagonal % 2 == 0)
        (diagonal / 2) * (diagonal + 1)
    else
        diagonal * ((diagonal + 1) / 2);

    const steps = before + column - 1;
    const answer = (initial_code * modPow(multiplier, steps)) % modulus;

    try std.io.getStdOut().writer().print("{d}\n", .{answer});
}
```

