```java
import org.springframework.stereotype.Service;

import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service
public class AccountService {

    private final Map<AccountType, AccountRetrievalStrategy> strategies;

    public AccountService(List<AccountRetrievalStrategy> strategyList) {
        this.strategies = strategyList.stream()
                .collect(Collectors.toUnmodifiableMap(
                        AccountRetrievalStrategy::supportedType,
                        Function.identity()
                ));
    }

    public AccountDto getById(AccountType accountType, Integer id) {
        AccountRetrievalStrategy strategy = strategies.get(accountType);

        if (strategy == null) {
            throw new IllegalArgumentException(
                    "Unsupported account type: " + accountType
            );
        }

        return strategy.findById(id)
                .orElseThrow(() -> new EntityNotFoundException(
                        "Account not found for type " + accountType + " and id " + id
                ));
    }
}
```

This is easier to scale than checking every repository, but it requires the caller to know the account type.

