import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Objects;
import java.util.Optional;

@Service
@Transactional(readOnly = true)
public class AccountService {

    private final List<AccountLookup> accountLookups;

    public AccountService(List<AccountLookup> accountLookups) {
        this.accountLookups = List.copyOf(accountLookups);
    }

    public AccountDto getById(Integer id) {
        Objects.requireNonNull(id, "Account id must not be null");

        for (AccountLookup lookup : accountLookups) {
            Optional<AccountDto> account = lookup.findById(id);

            if (account.isPresent()) {
                return account.get();
