class Solution {
    struct Node {
        int firstChild = -1;
        int nextSibling = -1;
        int cnt = 0;
        char ch = 0;
    };

    vector<Node> nodes;

    int findChild(int u, char ch) const {
        for (int v = nodes[u].firstChild; v != -1; v = nodes[v].nextSibling) {
            if (nodes[v].ch == ch) return v;
        }
        return -1;
    }

public:
    vector<int> sumPrefixScores(vector<string>& words) {
        size_t maxNodes = 1;
        for (const string& w : words) maxNodes += w.size();
        nodes.clear();
        nodes.reserve(maxNodes);
        nodes.push_back(Node{}); // root

        for (const string& w : words) {
            int u = 0;
            for (char ch : w) {
                int v = findChild(u, ch);
                if (v == -1) {
                    v = (int)nodes.size();
                    Node n;
                    n.ch = ch;
                    n.nextSibling = nodes[u].firstChild;
                    nodes.push_back(n);
                    nodes[u].firstChild = v;
                }
                u = v;
                ++nodes[u].cnt;
            }
        }

        vector<int> ans;
        ans.reserve(words.size());
        for (const string& w : words) {
            int u = 0;
            int score = 0;
            for (char ch : w) {
                u = findChild(u, ch);
                if (u == -1) break; // safety for arbitrary queries
                score += nodes[u].cnt;
            }
            ans.push_back(score);
        }
        return ans;
    }
};

