class Solution {
    struct Node {
        int firstChild = -1;
        int nextSibling = -1;
        int cnt = 0;
        char ch = '\0';
    };

    static int findChild(const std::vector<Node>& nodes, int u, char ch) {
        for (int v = nodes[u].firstChild; v != -1; v = nodes[v].nextSibling) {
            if (nodes[v].ch == ch) return v;
        }
        return -1;
    }

public:
    std::vector<int> sumPrefixScores(std::vector<std::string>& words) {
        std::vector<Node> nodes;
        size_t maxNodes = 1;
        for (const auto& w : words) maxNodes += w.size();
        nodes.reserve(maxNodes);
        nodes.push_back(Node{});

        for (const std::string& w : words) {
            int u = 0;
            for (char ch : w) {
                int v = findChild(nodes, u, ch);
                if (v == -1) {
                    v = static_cast<int>(nodes.size());
                    Node n;
                    n.ch = ch;
                    n.nextSibling = nodes[u].firstChild;
                    nodes.push_back(n);
                    nodes[u].firstChild = v;
                }
                u = v;
                ++nodes[u].cnt;
            }
        }

        std::vector<int> ans;
        ans.reserve(words.size());
        for (const std::string& w : words) {
            int u = 0;
            int score = 0;
            for (char ch : w) {
                u = findChild(nodes, u, ch);
                if (u == -1) break;
                score += nodes[u].cnt;
            }
            ans.push_back(score);
        }
        return ans;
    }
};
