```python
from textual import events, on
from textual.app import App, ComposeResult
from textual.containers import Horizontal, VerticalScroll
from textual.message import Message
from textual.widgets import Button, Footer, Header, Label, Static


class FileRow(Horizontal, can_focus=True):
    """A button-like row containing a filename and an inner Delete button."""

    class Selected(Message):
        def __init__(self, filename: str) -> None:
            super().__init__()
            self.filename = filename

    class Deleted(Message):
        def __init__(self, filename: str) -> None:
            super().__init__()
            self.filename = filename

    def __init__(self, filename: str) -> None:
        super().__init__()
        self.filename = filename

    def compose(self) -> ComposeResult:
        yield Label(self.filename, classes="filename")
        yield Button("Delete", variant="error", classes="delete")

    def on_click(self, event: events.Click) -> None:
        # If the click happened on the Delete button, do not select the row.
        if isinstance(event.widget, Button):
            return

        event.stop()
        self.post_message(self.Selected(self.filename))

    def on_key(self, event: events.Key) -> None:
        # Make the row behave button-like when focused.
        if event.key in ("enter", "space", " "):
            event.stop()
            self.post_message(self.Selected(self.filename))

    @on(Button.Pressed, ".delete")
    async def delete_pressed(self, event: Button.Pressed) -> None:
        event.stop()
        self.post_message(self.Deleted(self.filename))
        await self.remove()


class FileBrowser(App):
    CSS = """
    Screen {
        layout: vertical;
    }

    #files {
        height: 1fr;
        padding: 1 2;
    }

    FileRow {
        height: 5;
        margin-bottom: 1;
        padding: 0 1;
        border: round $primary;
