    }

    FileRow Button {
        width: 12;
        min-width: 12;
    }

    #status {
        height: 3;
        padding: 1 2;
    }
    """

    BINDINGS = [
        ("q", "quit", "Quit"),
    ]

    def __init__(self, filenames: list[str]) -> None:
        super().__init__()
        self.filenames = list(filenames)

    def compose(self) -> ComposeResult:
        yield Header()

        with VerticalScroll(id="files"):
            for filename in self.filenames:
                yield FileRow(filename)

        yield Static(
            "Click a row or press Enter/Space to select it. "
            "Click Delete to remove it.",
            id="status",
        )
        yield Footer()

    @on(FileRow.Selected)
    def file_selected(self, message: FileRow.Selected) -> None:
        self.query_one("#status", Static).update(
            f"Selected: {message.filename}"
        )

    @on(FileRow.Deleted)
    def file_deleted(self, message: FileRow.Deleted) -> None:
        if message.filename in self.filenames:
            self.filenames.remove(message.filename)

        self.query_one("#status", Static).update(
            f"Removed from list: {message.filename}"
