```php
use Carbon\Carbon;

function calculateProcessDates(string $orderCreatedDate, array $processes): array
{
    // Sort processes by sequence
    usort($processes, function ($a, $b) {
        return $a['sequence'] <=> $b['sequence'];
    });

    // Parse order created date
    // "!" resets seconds/microseconds to 00
    $currentDate = Carbon::createFromFormat('!d/m/Y h:i A', $orderCreatedDate);

    foreach ($processes as &$process) {
        $completedDays = (int) $process['completed_days'];

        // Start date is previous process end date, or order created date for first process
        $process['start_date'] = $currentDate->format('d/m/Y h:i A');

        // End date = start date + completed working days
        $endDate = $currentDate->copy()->addWeekdays($completedDays);

        $process['end_date'] = $endDate->format('d/m/Y h:i A');

        // Next process starts from this process end date
        $currentDate = $endDate->copy();
    }

    unset($process);

    return $processes;
}
```

Usage:

```php
