            root = parent[root];
        }

        while (v != root) {
            int nxt = parent[v];
            parent[v] = root;
            v = nxt;
        }

        return root;
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);

        if (a == b) return;

        if (sz[a] < sz[b]) swap(a, b);

        parent[b] = a;
        sz[a] += sz[b];
    }
