// fetch_svg.js

async function loadAndInsertSVG() {
    const container = document.getElementById('svgContainer');

    if (!container) {
        console.error('svgContainer element not found.');
        return;
    }

    try {
        const response = await fetch('../images/wtrtrmt42_01_esmx.svg');

        if (!response.ok) {
            throw new Error(`Network response was not ok: ${response.status}`);
        }

        const svgText = await response.text();

        // Parse the SVG as XML so we can safely modify the root element.
        const svgDocument = new DOMParser().parseFromString(
            svgText,
            'image/svg+xml'
        );

        if (svgDocument.querySelector('parsererror')) {
            throw new Error('The SVG file could not be parsed as valid XML.');
        }

        const svg = document.importNode(svgDocument.documentElement, true);

        if (svg.localName !== 'svg') {
            throw new Error('The downloaded file is not an SVG document.');
        }

        // Match your requested changes.
        svg.setAttribute('version', '1.1');
        svg.removeAttribute('width');
        svg.removeAttribute('height');

        // Help the SVG scale visibly inside its container.
        svg.style.display = 'block';
        svg.style.width = '100%';
        svg.style.height = 'auto';

        // Insert the SVG.
        container.replaceChildren(svg);

        // Calling the function directly is usually more reliable than relying
        // on an inline onload attribute inserted into the SVG markup.
        if (typeof createAlarmSVGLinks === 'function') {
            createAlarmSVGLinks('../wtrtrmt_alarms.htm');
        } else {
            console.warn('createAlarmSVGLinks is not defined yet.');
        }
    } catch (error) {
        console.error('Error loading SVG:', error);
    }
}

// Run safely whether the script is loaded before or after DOMContentLoaded.
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', loadAndInsertSVG, { once: true });
} else {
    loadAndInsertSVG();
}
```

