function markQuotedText(root) {
  const skipTags = new Set(["CODE", "PRE", "SCRIPT", "STYLE", "TEXTAREA", "TEMPLATE"]);
  const blockTags = new Set([
    "ADDRESS","ARTICLE","ASIDE","BLOCKQUOTE","DETAILS","DD","DIV","DL","DT",
    "FIELDSET","FIGCAPTION","FIGURE","FOOTER","FORM","H1","H2","H3","H4","H5","H6",
    "HEADER","HR","LI","MAIN","NAV","OL","P","PRE","SECTION","TABLE","TBODY",
    "TD","TFOOT","TH","THEAD","TR","UL"
  ]);

  const textNodes = [];
  let buffer = "";

  function walk(node) {
    if (node.nodeType === Node.TEXT_NODE) {
      const start = buffer.length;
      buffer += node.nodeValue;
      textNodes.push({ node, start, end: buffer.length });
      return;
    }

    if (node.nodeType === Node.ELEMENT_NODE) {
      const tag = node.tagName;
      if (skipTags.has(tag) || tag === "BR") {
        buffer += "\0";
        return;
      }

      const isBlock = blockTags.has(tag);
      if (isBlock) buffer += "\0";
      for (const child of node.childNodes) walk(child);
      if (isBlock) buffer += "\0";
      return;
    }

    // Document fragments, etc.
    for (const child of node.childNodes) walk(child);
  }

  walk(root);

  const quotePattern = /"[^"\0]+"|“[^”\0]+”/g;
  const matches = Array.from(buffer.matchAll(quotePattern), (m) => ({
    start: m.index,
    end: m.index + m[0].length,
  }));

  if (!matches.length) return;

  for (const { node, start, end } of textNodes) {
    const overlapping = matches.filter((m) => m.start < end && m.end > start);
    if (!overlapping.length) continue;

    const value = node.nodeValue;
    const fragment = document.createDocumentFragment();
    let last = 0;

    for (const m of overlapping) {
      const from = Math.max(m.start, start) - start;
      const to = Math.min(m.end, end) - start;

      if (from > last) {
        fragment.appendChild(document.createTextNode(value.slice(last, from)));
      }

      const span = document.createElement("span");
      span.className = "md-quoted";
      span.textContent = value.slice(from, to);
      fragment.appendChild(span);

      last = to;
    }

    if (last < value.length) {
      fragment.appendChild(document.createTextNode(value.slice(last)));
    }

    node.replaceWith(fragment);
  }
}
```

