import pygame
import math
import sys
from collections import deque

WIDTH, HEIGHT = 900, 620
FPS = 60

HEX_SIZE = 30
SQRT3 = math.sqrt(3)
ORIGIN = (70, 70)

COLS, ROWS = 12, 10
MOVE_RANGE = 3
ATTACK_RANGE = 1
DAMAGE = 4

DIRS = ((1, 0), (1, -1), (0, -1), (-1, 0), (-1, 1), (0, 1))


def round_half(value):
    return int(math.floor(value + 0.5))


def hex2pixel(q, r):
    """Pointy-top axial hex coordinates to pixel center."""
    x = HEX_SIZE * SQRT3 * (q + r / 2.0)
    y = HEX_SIZE * 1.5 * r
    return ORIGIN[0] + x, ORIGIN[1] + y


def cube_round(q, r):
    """Round fractional axial coordinates using cube-coordinate constraint."""
    x = q
    z = r
    y = -x - z

    rx = round_half(x)
    ry = round_half(y)
    rz = round_half(z)

    dx = abs(rx - x)
    dy = abs(ry - y)
    dz = abs(rz - z)

    if dx > dy and dx > dz:
        rx = -ry - rz
    elif dy > dz:
        ry = -rx - rz
    else:
        rz = -rx - ry

    return int(rx), int(rz)


def pixel2hex(x, y):
    """Pixel coordinate to nearest pointy-top axial hex coordinate."""
    x -= ORIGIN[0]
    y -= ORIGIN[1]

    q = (SQRT3 / 3.0 * x - y / 3.0) / HEX_SIZE
    r = (2.0 / 3.0 * y) / HEX_SIZE

    return cube_round(q, r)


def hex_corners(q, r):
    """Return the six corners of a pointy-top hexagon."""
    cx, cy = hex2pixel(q, r)
    corners = []

    for i in range(6):
        angle = math.radians(60 * i - 30)
        x = cx + HEX_SIZE * math.cos(angle)
        y = cy + HEX_SIZE * math.sin(angle)
        corners.append((round_half(x), round_half(y)))

    return corners


def offset_to_axial(col, row):
    """Odd-row offset layout to axial coordinates for a rectangular map."""
    return col - row // 2, row


BOARD = {
    offset_to_axial(c, r): "plain"
    for r in range(ROWS)
    for c in range(COLS)
}


def neighbors(pos):
    q, r = pos
    for dq, dr in DIRS:
        n = (q + dq, r + dr)
        if n in BOARD:
            yield n


def hex_distance(a, b):
    dq = a[0] - b[0]
    dr = a[1] - b[1]
    return max(abs(dq), abs(dr), abs(dq + dr))


class Unit:
    def __init__(self, team, pos):
        self.team = team
        self.pos = pos
        self.hp = 12
        self.moved = False
        self.attacked = False

    @property
    def alive(self):
        return self.hp > 0


UNITS = [
    Unit(0, offset_to_axial(1, 2)),
    Unit(0, offset_to_axial(1, 7)),
    Unit(1, offset_to_axial(10, 2)),
    Unit(1, offset_to_axial(10, 7)),
]


def unit_at(pos):
    for u in UNITS:
        if u.alive and u.pos == pos:
            return u
    return None


def reachable_tiles(unit):
    if unit is None or not unit.alive or unit.moved:
        return {}

    occupied = {u.pos for u in UNITS if u.alive and u is not unit}
    distances = {unit.pos: 0}
    queue = deque([(unit.pos, 0)])

    while queue:
        pos, cost = queue.popleft()

        if cost >= MOVE_RANGE:
            continue

        for n in neighbors(pos):
            if n not in occupied and n not in distances:
                distances[n] = cost + 1
                queue.append((n, cost + 1))

    return distances


def can_attack(attacker, defender):
    return (
        attacker is not None
        and defender is not None
        and attacker.alive
        and defender.alive
        and attacker.team != defender.team
        and not attacker.attacked
        and hex_distance(attacker.pos, defender.pos) <= ATTACK_RANGE
    )


def draw_text(screen, font, text, x, y, color=(230, 235, 240)):
    screen.blit(font.render(text, True, color), (x, y))


def main():
    pygame.init()
    screen = pygame.display.set_mode((WIDTH, HEIGHT))
    pygame.display.set_caption("Hex Wargame")
    font = pygame.font.Font(None, 26)
    clock = pygame.time.Clock()

    selected = None
    turn = 0
    winner = None
    running = True

    while running:
        reachable = (
            reachable_tiles(selected)
            if selected and selected.team == turn and winner is None
            else {}
        )

        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                running = False

            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_ESCAPE:
                    running = False

                elif event.key in (pygame.K_RETURN, pygame.K_SPACE) and winner is None:
                    turn = 1 - turn
                    selected = None

                    for u in UNITS:
                        if u.team == turn:
                            u.moved = False
                            u.attacked = False

            elif event.type == pygame.MOUSEBUTTONDOWN:
                if event.button == 3:
                    selected = None

                elif event.button == 1 and winner is None:
                    pos = pixel2hex(*event.pos)

                    if pos not in BOARD:
                        continue

                    target = unit_at(pos)

                    if target and target.team == turn:
                        selected = target

                    elif selected is not None and target is not None:
                        if can_attack(selected, target):
                            target.hp = max(0, target.hp - DAMAGE)
                            selected.attacked = True
                            selected.moved = True

                            if not any(u.alive for u in UNITS if u.team == 0):
                                winner = 1
                            if not any(u.alive for u in UNITS if u.team == 1):
                                winner = 0

                    elif selected is not None and target is None and pos in reachable:
                        selected.pos = pos
                        selected.moved = True

        reachable = (
            reachable_tiles(selected)
            if selected and selected.team == turn and winner is None
            else {}
        )

        screen.fill((18, 22, 28))

        # Fill hexes.
        for pos in BOARD:
            pygame.draw.polygon(screen, (64, 86, 64), hex_corners(*pos))

        # Grid lines.
        for pos in BOARD:
            pygame.draw.polygon(screen, (26, 34, 26), hex_corners(*pos), 1)

        # Highlights.
        if selected is not None and winner is None:
            for pos in reachable:
                if pos != selected.pos:
                    pygame.draw.polygon(screen, (0, 190, 120), hex_corners(*pos), 3)

            for u in UNITS:
                if u.alive and u.team != selected.team and can_attack(selected, u):
                    pygame.draw.polygon(screen, (230, 70, 70), hex_corners(*u.pos), 3)

            pygame.draw.polygon(screen, (240, 220, 80), hex_corners(*selected.pos), 3)

        # Units.
        for u in UNITS:
            if not u.alive:
                continue

            cx, cy = hex2pixel(*u.pos)
            center = (round_half(cx), round_half(cy))

            color = (80, 140, 255) if u.team == 0 else (235, 90, 90)

            if u.attacked:
                color = tuple(max(0, int(c * 0.55)) for c in color)

            pygame.draw.circle(screen, (10, 12, 16), center, 18)
            pygame.draw.circle(screen, color, center, 15)

            hp_text = font.render(str(u.hp), True, (255, 255, 255))
            screen.blit(hp_text, hp_text.get_rect(center=center))

        if winner is not None:
            msg = f"Winner: {'Blue' if winner == 0 else 'Red'}"
        else:
            msg = (
                f"Turn: {'Blue' if turn == 0 else 'Red'}  |  "
                "Left-click select/move/attack, right-click deselect, Enter end turn"
            )

        draw_text(screen, font, msg, 12, HEIGHT - 32)

        pygame.display.flip()
        clock.tick(FPS)

    pygame.quit()
    sys.exit()


if __name__ == "__main__":
    main()
```

This uses pointy-top axial coordinates. The important hex math is:

```python
x = size * sqrt(3) * (q + r / 2)
y = size * 1.5 * r
```

and the inverse:

```python
q = (sqrt(3) / 3 * x - 1/3 * y) / size
r = (2/3 * y) / size
```

The fractional hex result is rounded using cube-coordinate rounding, which is the standard robust way to avoid incorrect hex selection near corners and edges.

Evaluation:

Assistant A provides a correct basic hex-grid renderer with axial coordinates, pointy-top hexes, correct `hex_to_pixel`/`pixel_to_hex` formulas, and cube rounding. However, it is more of a hex-grid demo than a wargame. There are no units, movement, combat, turns, or victory conditions. It also names the functions `hex_to_pixel` and `pixel_to_hex` rather than the requested `hex2pixel` and `pixel2hex`, which is a minor mismatch. Its draw order also draws the hex outline before the highlighted fill, causing the highlighted hex’s outline to be covered. It is useful, but it does not fully satisfy the “wargame” part of the request.

Assistant B provides a complete playable wargame. It includes terrain, movement costs, ranged attacks, AI, health, selection, turn management, victory conditions, and a UI panel. Most importantly, it implements `hex2pixel` and `pixel2hex` correctly for pointy-top axial coordinates and uses cube rounding for picking. The hex spacing is correct: horizontal spacing is `sqrt(3) * size`, vertical row spacing is `1.5 * size`, and corners are generated with the proper 60-degree angles. The map construction using offset-to-axial conversion is also valid for producing a rectangular staggered hex map.

Assistant B’s answer is much closer to what the user asked for. It is not just a grid demo; it is an actual hex-based wargame. The grid math is correct, and the inclusion of sanity checks shows care about the hex geometry. There are only minor nitpicks: using Python’s built-in `round` can theoretically have tie-breaking edge cases, and individually rounded polygon vertices can sometimes create tiny raster seams unless shared vertices or float rendering are used. But these are small issues compared with the overall correctness and completeness.

My final verdict is Assistant B is significantly better: [[B>>A]]

