    private bool isDead;

    private void Update()
    {
        if (isDead || targetBase == null)
            return;

        transform.position = Vector3.MoveTowards(
            transform.position,
            targetBase.position,
            speed * Time.deltaTime
        );

        if (Vector3.Distance(transform.position, targetBase.position) <= 0.1f)
        {
            AttackBase();
        }
    }

    public void TakeDamage(float damage)
    {
        if (isDead)
            return;

        float actualDamage = Mathf.Max(0f, damage - armor);
        health -= actualDamage;

        if (health <= 0f)
