```cpp
#include "Plot2D.h"

#include <FL/Fl.H>
#include <FL/Fl_Window.H>

#include <cmath>
#include <iostream>

int main(int argc, char** argv)
{
    Fl_Window window(800, 500, "2D Chart Example");

    Plot2D plot(10, 10, 780, 480);

    window.end();
    window.resizable(plot);

    plot.setXAxis({"Time [s]", 0.0f, 10.0f});
    plot.setYAxis({"Value", -1.5f, 1.5f});

    Plot2D::Grid grid;
    grid.xStep = 1.0f;
    grid.yStep = 0.5f;
    plot.setGrid(grid);

    Plot2D::GraphStyle style;
    style.color = FL_RED;
    style.lineWidth = 2;

    Plot2D::GraphId sineId = plot.addGraph("sin(x)", style);

    for (int i = 0; i <= 200; ++i) {
        float x = i * 0.05f;
        plot.addPoint(sineId, {x, std::sin(x)});
    }

    Plot2D::GraphStyle pointStyle;
    pointStyle.color = FL_BLUE;
    pointStyle.style = Plot2D::CurveStyle::LineAndPoints;

    Plot2D::GraphId measId = plot.addGraph("Measurements", pointStyle);

    plot.addPoint(measId, {1.0f,  0.7f});
    plot.addPoint(measId, {3.0f,  0.2f});
    plot.addPoint(measId, {5.0f, -0.8f});
    plot.addPoint(measId, {7.0f,  0.5f});

    plot.renameGraph(measId, "Measured values");

    plot.printInfo(std::cout);

    window.show(argc, argv);
    return Fl::run();
}
```

Important implementation notes:

1. After every change that affects appearance, call `redraw()`. Do not call `draw()` directly.
2. In `draw()`, compute the inner plot rectangle using the margins.
3. Convert data coordinates to pixel coordinates:
   ```cpp
   double px = area.x + (dataX - xmin) / (xmax - xmin) * area.w;
   double py = area.y + area.h - (dataY - ymin) / (ymax - ymin) * area.h;
   ```
   FLTK y-coordinates grow downward, so the y conversion must be inverted.
4. Use `fl_push_clip()` and `fl_pop_clip()` to keep curves inside the plot rectangle.
5. Validate axis ranges: require finite values and `minimum < maximum`.
6. If automatic grid step is used, limit the maximum number of grid lines to avoid extremely dense drawing.
7. For very large data sets, consider point decimation or drawing only visible x-range portions.

