## `main.tf`

```hcl
data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

################################################################################
# ECS cluster
################################################################################

resource "aws_ecs_cluster" "this" {
  count = var.create_cluster ? 1 : 0

  name = var.cluster_name
  tags = var.tags
}

data "aws_ecs_cluster" "existing" {
  count = var.create_cluster ? 0 : 1

  cluster_name = var.cluster_name
}

################################################################################
# ECR repository
################################################################################

resource "aws_ecr_repository" "this" {
  count = var.create_ecr_repository ? 1 : 0

  name                 = var.ecr_repository_name
  image_tag_mutability = "MUTABLE"

  encryption_configuration {
    encryption_type = "AES256"
  }

  tags = var.tags
}

data "aws_ecr_repository" "this" {
  count = var.create_ecr_repository ? 0 : 1

  name = var.ecr_repository_name
}

################################################################################
# Locals
################################################################################

locals {
  cluster_name = var.cluster_name
  cluster_arn  = var.create_cluster ? aws_ecs_cluster.this[0].arn : data.aws_ecs_cluster.existing[0].arn

  ecr_repository_name = var.create_ecr_repository ? aws_ecr_repository.this[0].name : data.aws_ecr_repository.this[0].name
  ecr_repository_arn  = var.create_ecr_repository ? aws_ecr_repository.this[0].arn : data.aws_ecr_repository.this[0].arn
  ecr_repository_url  = var.create_ecr_repository ? aws_ecr_repository.this[0].repository_url : data.aws_ecr_repository.this[0].repository_url

  initial_image = "${local.ecr_repository_url}:${var.image_tag}"

  ecs_service_arn = "arn:${data.aws_partition.current.partition}:ecs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:service/${local.cluster_name}/${var.name}"

  default_ssm_kms_alias_arn = "arn:${data.aws_partition.current.partition}:kms:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:alias/aws/ssm"
}

################################################################################
# Networking / logging
################################################################################

resource "aws_security_group" "ecs" {
  name_prefix = "${var.name}-"
  description = "Security group for Cloudflare tunnel connector"
  vpc_id      = var.vpc_id

  egress {
    description = "Allow outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  lifecycle {
    create_before_destroy = true
  }

  tags = var.tags
}

resource "aws_cloudwatch_log_group" "ecs" {
  name              = "/ecs/${var.name}"
  retention_in_days = 30

  tags = var.tags
}

################################################################################
# IAM for ECS task
################################################################################

resource "aws_iam_role" "execution" {
  name = "${var.name}-ecs-execution"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ecs-tasks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "execution" {
  role       = aws_iam_role.execution.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy" "execution_token" {
  name = "read-cloudflare-token"
  role = aws_iam_role.execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Effect = "Allow"
          Action = [
            "ssm:GetParameters",
            "ssm:GetParameter"
          ]
          Resource = var.cloudflare_token_parameter_arn
        },
        {
          Effect   = "Allow"
          Action   = "kms:Decrypt"
          Resource = local.default_ssm_kms_alias_arn
        }
      ],
      var.ssm_kms_key_arn == null ? [] : [{
        Effect   = "Allow"
        Action   = "kms:Decrypt"
        Resource = var.ssm_kms_key_arn
      }]
    )
  })
}

resource "aws_iam_role" "task" {
  name = "${var.name}-ecs-task"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ecs-tasks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })

  tags = var.tags
}

################################################################################
# ECS task definition
################################################################################

resource "aws_ecs_task_definition" "this" {
  family                   = var.name
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"

  cpu    = var.cpu
  memory = var.memory

  execution_role_arn = aws_iam_role.execution.arn
  task_role_arn      = aws_iam_role.task.arn

  runtime_platform {
    operating_system_family = "LINUX"
    cpu_architecture        = "X86_64"
  }

  container_definitions = jsonencode([{
    name      = var.container_name
    image     = local.initial_image
    essential = true

    # For remotely managed Cloudflare Tunnel connectors.
    # Adjust if your image expects a different entrypoint/command.
    command = [
      "tunnel",
      "--no-autoupdate",
      "run"
    ]

    # ECS injects the SSM parameter value as this environment variable at runtime.
    secrets = [{
      name      = var.token_env_name
      valueFrom = var.cloudflare_token_parameter_arn
    }]

    logConfiguration = {
      logDriver = "awslogs"
      options = {
        awslogs-group         = aws_cloudwatch_log_group.ecs.name
        awslogs-region        = data.aws_region.current.name
        awslogs-stream-prefix = "cloudflared"
      }
    }
  }])

  tags = var.tags
}

################################################################################
# ECS service
################################################################################

resource "aws_ecs_service" "this" {
  name            = var.name
  cluster         = local.cluster_name
  task_definition = aws_ecs_task_definition.this.arn

  desired_count    = var.desired_count
  launch_type      = "FARGATE"
  platform_version = "LATEST"

  deployment_minimum_healthy_percent = 100
  deployment_maximum_percent         = 200

  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }

  network_configuration {
    subnets          = var.subnet_ids
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = var.assign_public_ip
  }

  # CodePipeline will manage future task-definition image revisions.
  lifecycle {
    ignore_changes = [task_definition]
  }

  depends_on = [
    aws_iam_role_policy_attachment.execution,
    aws_iam_role_policy.execution_token
  ]

  tags = var.tags
}
```

