# Example usage

## Create a new ECS cluster

```hcl
provider "aws" {
  region = "us-east-1"
}

module "cloudflare_tunnel" {
  source = "./modules/cloudflare-ecs"

  name = "cloudflared"

  vpc_id = "vpc-0123456789abcdef0"

  subnet_ids = [
    "subnet-0123456789abcdef0",
    "subnet-0fedcba9876543210"
