#include <stddef.h>
#include <stdint.h>
#include <limits.h>
#include <string.h>

size_t fast_strlen(const char *s)
{
    const unsigned char *p = (const unsigned char *)s;
    size_t n = 0;

    /* Advance byte-by-byte until we are word-aligned. */
    while ((uintptr_t)p % sizeof(size_t) != 0) {
        if (*p == 0)
            return n;
        ++p;
        ++n;
    }

    /*
       For 8-bit bytes:
           ones = 0x01010101...
           high = 0x80808080...

       More generally, using CHAR_BIT/UCHAR_MAX makes this less tied
       to 8-bit bytes.
    */
    const size_t ones = SIZE_MAX / UCHAR_MAX;
    const size_t high = ones << (CHAR_BIT - 1);

    for (;;) {
        size_t word;

        /*
           Use memcpy rather than casting to size_t* to avoid
           strict-aliasing violations. Optimizing compilers usually
           turn this into a single word load when appropriate.
        */
        memcpy(&word, p, sizeof(word));

        /*
           This expression is nonzero iff the word contains a zero byte.
        */
        if ((word - ones) & ~word & high) {
            /* Find the exact position of the first zero byte. */
            for (size_t i = 0; i < sizeof(word); ++i) {
                if (p[i] == 0)
                    return n + i;
            }
        }

        p += sizeof(word);
        n += sizeof(word);
    }
}
```

