using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

public static class HashSetStringBinary
{
    // Format (little-endian):
    // int32 count
    // repeat count times:
    //   int32 utf8ByteLength, -1 for null
    //   if length >= 0: UTF-8 bytes
    public static byte[] Serialize(HashSet<string?> set, bool deterministic = false)
    {
        ArgumentNullException.ThrowIfNull(set);
        using var ms = new MemoryStream();
        using var bw = new BinaryWriter(ms, Encoding.UTF8, leaveOpen: true);
        bw.Write(set.Count);

        IEnumerable<string?> items = deterministic
            ? set.OrderBy(s => s, StringComparer.Ordinal)
            : set;

        foreach (var s in items)
        {
            if (s is null)
            {
                bw.Write(-1);
                continue;
            }

            byte[] utf8 = Encoding.UTF8.GetBytes(s);
            bw.Write(utf8.Length);
            bw.Write(utf8);
        }

        bw.Flush();
        return ms.ToArray();
    }

    public static HashSet<string?> Deserialize(
        byte[] data,
        IEqualityComparer<string?>? comparer = null,
        int maxCount = 10_000_000,
        int maxStringBytes = 100_000_000)
    {
        ArgumentNullException.ThrowIfNull(data);
        using var ms = new MemoryStream(data, writable: false);
        using var br = new BinaryReader(ms, Encoding.UTF8, leaveOpen: true);

        int count = br.ReadInt32();
        long remaining = ms.Length - ms.Position;
        if (count < 0 || count > maxCount || count > remaining / sizeof(int))
            throw new InvalidDataException("Invalid count.");

        var result = new HashSet<string?>(count, comparer);

        for (int i = 0; i < count; i++)
        {
            int len = br.ReadInt32();
            string? value;

            if (len == -1)
            {
                value = null;
            }
            else if (len < 0 || len > maxStringBytes || len > ms.Length - ms.Position)
            {
                throw new InvalidDataException($"Invalid string length at item {i}.");
            }
            else
            {
                byte[] utf8 = br.ReadBytes(len);
                if (utf8.Length != len)
                    throw new EndOfStreamException($"Truncated string at item {i}.");
                value = Encoding.UTF8.GetString(utf8);
            }

            if (!result.Add(value))
                throw new InvalidDataException($"Duplicate value for selected comparer at item {i}.");
        }

        if (ms.Position != ms.Length)
            throw new InvalidDataException("Unexpected trailing bytes.");

        return result;
    }
}
