```csharp
using UnityEngine;

[RequireComponent(typeof(Rigidbody), typeof(CapsuleCollider))]
public class SurfaceWalker : MonoBehaviour
{
    [Header("References")]
    [SerializeField] private LayerMask walkableMask;
    [SerializeField] private Transform cameraTransform;

    [Header("Movement")]
    [SerializeField] private float moveSpeed = 5f;
    [SerializeField] private float acceleration = 30f;
    [SerializeField] private float rotationSpeed = 12f;

    [Header("Surface Sticking")]
    [SerializeField] private float gravity = 40f;
    [SerializeField] private float searchDistance = 2f;
    [SerializeField] private float normalSmoothing = 10f;

    private Rigidbody rb;
    private Vector3 surfaceUp;
    private Vector3 targetUp;
    private Vector3 facing;
    private Vector2 input;

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();

        rb.useGravity = false;
        rb.constraints = RigidbodyConstraints.FreezeRotation;
        rb.interpolation = RigidbodyInterpolation.Interpolate;

        surfaceUp = transform.up;
        targetUp = transform.up;
        facing = transform.forward;
    }

    private void Update()
    {
        input = Vector2.ClampMagnitude(
            new Vector2(
                Input.GetAxisRaw("Horizontal"),
                Input.GetAxisRaw("Vertical")
            ),
            1f
        );
    }

    private void FixedUpdate()
    {
        bool hasSurface = TryGetSurface(out RaycastHit hit);

        if (hasSurface)
        {
            targetUp = hit.normal.normalized;
        }

        // Smoothly blend the character's "up" direction.
        surfaceUp = Vector3.Slerp(
            surfaceUp,
            targetUp,
            1f - Mathf.Exp(normalSmoothing * Time.fixedDeltaTime)
        );

        surfaceUp.Normalize();

        Vector3 desiredVelocity = Vector3.zero;

        if (hasSurface)
        {
            Vector3 direction = GetMoveDirection();
            desiredVelocity = direction * moveSpeed;

            if (direction.sqrMagnitude > 0.0001f)
            {
                facing = direction;
            }
        }

        // Keep existing velocity toward/away from the surface,
        // but control tangent movement manually.
        Vector3 tangentVelocity = Vector3.ProjectOnPlane(rb.velocity, surfaceUp);
        Vector3 normalVelocity = Vector3.Project(rb.velocity, surfaceUp);

        tangentVelocity = Vector3.MoveTowards(
            tangentVelocity,
            desiredVelocity,
            acceleration * Time.fixedDeltaTime
        );

        rb.velocity = tangentVelocity + normalVelocity;

        // Custom gravity toward the surface.
        rb.AddForce(-surfaceUp * gravity, ForceMode.Acceleration);

        AlignRotation();
    }

    private Vector3 GetMoveDirection()
    {
        Vector3 forward = cameraTransform != null
            ? cameraTransform.forward
            : facing;

        Vector3 right = cameraTransform != null
            ? cameraTransform.right
            : transform.right;

        forward = Vector3.ProjectOnPlane(forward, surfaceUp);
        right = Vector3.ProjectOnPlane(right, surfaceUp);

        if (forward.sqrMagnitude < 0.0001f)
            forward = Vector3.Cross(surfaceUp, Vector3.right);

        if (forward.sqrMagnitude < 0.0001f)
            forward = Vector3.Cross(surfaceUp, Vector3.forward);

        if (right.sqrMagnitude < 0.0001f)
            right = Vector3.Cross(surfaceUp, forward);

        Vector3 direction =
            forward.normalized * input.y +
            right.normalized * input.x;

        if (direction.sqrMagnitude < 0.0001f)
            return Vector3.zero;

        return direction.normalized;
    }

    private void AlignRotation()
    {
        Vector3 forward = Vector3.ProjectOnPlane(facing, surfaceUp);

        if (forward.sqrMagnitude < 0.0001f)
            forward = Vector3.ProjectOnPlane(transform.forward, surfaceUp);

        if (forward.sqrMagnitude < 0.0001f)
            forward = Vector3.Cross(surfaceUp, Vector3.right);

        if (forward.sqrMagnitude < 0.0001f)
            forward = Vector3.Cross(surfaceUp, Vector3.forward);

        Quaternion targetRotation = Quaternion.LookRotation(
            forward.normalized,
            surfaceUp
        );

        float blend = 1f - Mathf.Exp(rotationSpeed * Time.fixedDeltaTime);

        rb.MoveRotation(
            Quaternion.Slerp(
                rb.rotation,
                targetRotation,
                blend
            )
        );
    }

    private bool TryGetSurface(out RaycastHit bestHit)
    {
        bestHit = default;

        float bestScore = float.MaxValue;
        bool found = false;

        Vector3 origin = transform.position;
        Vector3 down = -surfaceUp;

        // A few probe directions help around edges and curved surfaces.
        Vector3[] directions = new Vector3[]
        {
            down,
            (down + transform.forward * 0.35f).normalized,
            (down - transform.forward * 0.35f).normalized,
            (down + transform.right * 0.35f).normalized,
            (down - transform.right * 0.35f).normalized
        };

        foreach (Vector3 direction in directions)
        {
            if (direction.sqrMagnitude < 0.0001f)
                continue;

            if (!Physics.Raycast(
                    origin,
                    direction,
                    out RaycastHit hit,
                    searchDistance,
                    walkableMask,
                    QueryTriggerInteraction.Ignore))
            {
                continue;
            }

            // Prefer hits that are closer and more aligned with the current down direction.
            float alignment = Mathf.Abs(Vector3.Dot(direction.normalized, down));
            float score = hit.distance + (1f - alignment) * 0.25f;

            if (score < bestScore)
            {
                bestScore = score;
                bestHit = hit;
                found = true;
            }
        }

        return found;
    }
