using UnityEngine;

[RequireComponent(typeof(Rigidbody), typeof(CapsuleCollider))]
public class SurfaceWalker : MonoBehaviour
{
    public LayerMask walkableMask;
    public Transform cameraTransform;
    public float moveSpeed = 5f;
    public float acceleration = 35f;
    public float rotationSpeed = 12f;
    public float stickGravity = 40f;
    public float surfaceSearchDistance = 2.5f;
    public float normalSmoothing = 12f;

    private Rigidbody rb;
    private CapsuleCollider capsule;
    private Vector3 surfaceUp = Vector3.up;
    private Vector3 targetUp = Vector3.up;
    private Vector3 facing = Vector3.forward;
    private Vector2 input;
    private bool hasSurface;

    void Awake()
    {
        rb = GetComponent<Rigidbody>();
        capsule = GetComponent<CapsuleCollider>();
        rb.useGravity = false;
        rb.constraints = RigidbodyConstraints.FreezeRotation;
        rb.interpolation = RigidbodyInterpolation.Interpolate;
        surfaceUp = transform.up;
        targetUp = transform.up;
        facing = transform.forward;
    }

    void Update()
    {
        input = Vector2.ClampMagnitude(new Vector2(Input.GetAxisRaw("Horizontal"), Input.GetAxisRaw("Vertical")), 1f);
    }

    void FixedUpdate()
    {
        hasSurface = FindSurface(out RaycastHit hit);
        if (hasSurface) targetUp = hit.normal.normalized;

        // Smooth the up vector to avoid violent flips at edges.
        surfaceUp = Vector3.Slerp(surfaceUp, targetUp, 1f - Mathf.Exp(normalSmoothing * Time.fixedDeltaTime));
        surfaceUp.Normalize();

        Vector3 desiredVelocity = Vector3.zero;
        if (hasSurface)
        {
            Vector3 dir = GetMoveDirection();
            desiredVelocity = dir * moveSpeed;
            if (dir.sqrMagnitude > 0.0001f) facing = dir;
        }

        Vector3 tangentVelocity = Vector3.ProjectOnPlane(rb.velocity, surfaceUp);
        Vector3 normalVelocity = Vector3.Project(rb.velocity, surfaceUp);

        tangentVelocity = Vector3.MoveTowards(tangentVelocity, desiredVelocity, acceleration * Time.fixedDeltaTime);
        rb.velocity = tangentVelocity + normalVelocity;

        rb.AddForce(-surfaceUp * stickGravity, ForceMode.Acceleration);

        AlignToSurface();
    }

    Vector3 GetMoveDirection()
    {
        Vector3 forward = cameraTransform ? cameraTransform.forward : facing;
        Vector3 right = cameraTransform ? cameraTransform.right : transform.right;

        forward = Vector3.ProjectOnPlane(forward, surfaceUp);
        right = Vector3.ProjectOnPlane(right, surfaceUp);

        if (forward.sqrMagnitude < 0.0001f) forward = Vector3.Cross(surfaceUp, Vector3.right);
        if (forward.sqrMagnitude < 0.0001f) forward = Vector3.Cross(surfaceUp, Vector3.forward);
        if (right.sqrMagnitude < 0.0001f) right = Vector3.Cross(surfaceUp, forward);

        Vector3 dir = forward.normalized * input.y + right.normalized * input.x;
        return dir.sqrMagnitude > 0.0001f ? dir.normalized : Vector3.zero;
    }

    void AlignToSurface()
    {
