## My answer to the prompt

A good way to implement this is to replace the duplicated `Vision1Page` / `Vision2Page` components with a generic page that contains a reusable left-pane POST tester.

The left pane should:

- Provide buttons for API methods such as `FindPosition`, `detectObjects`, `classifyImage`, etc.
- Fill in the POST URL and default JSON request body.
- Allow the user to edit the request JSON and send it again.
- Display the HTTP status and JSON response.
- Allow the user to edit the response JSON.
- Send the edited response JSON to the mock-response endpoint.

The example below assumes the mock endpoint follows the same contract as your existing `SetMockResponsePanel`:

```http
POST /api/{apiPrefix}/setResponse
```

with JSON body:

```json
{
  "api": "FindPosition",
  "response": {
    "found": true,
    "x": 100,
    "y": 200
  }
}
```

If your backend instead uses `/api/setresponse/{apiPrefix}/{apiName}`, you can change only the `setMockResponse` function.

### Drop-in replacement code

Replace your existing `Vision1Page` and `Vision2Page` components with this code. Keep your existing `GetImagePanel`, `SetMockResponsePanel`, and `ApiTester` components.

```javascript
const formatJson = (value) => JSON.stringify(value, null, 2);

const prettyResponse = async (response) => {
  const text = await response.text();

  try {
    return formatJson(JSON.parse(text));
  } catch {
    return text;
  }
};

const DEFAULT_API_METHODS = [
  {
    name: "FindPosition",
    label: "Find Position",
    body: {
      imageUrl: "",
      templateName: "",
      threshold: 0.9,
    },
  },
  {
    name: "detectObjects",
    label: "Detect Objects",
    body: {
      imageUrl: "",
    },
  },
  {
    name: "classifyImage",
    label: "Classify Image",
    body: {
      imageUrl: "",
    },
  },
];

const API_METHODS_BY_PREFIX = {
  // Optionally override methods per tab.
  //
  // vision1: [
  //   {
  //     name: "FindPosition",
  //     label: "Find Position",
  //     body: { imageUrl: "" },
  //   },
  // ],
  //
  // visionSystem: [
  //   {
  //     name: "GetStatus",
  //     label: "Get Status",
  //     body: {},
  //   },
  // ],
};

const PostApiPanel = ({ apiPrefix }) => {
  const methods = API_METHODS_BY_PREFIX[apiPrefix] ?? DEFAULT_API_METHODS;
  const firstMethod = methods[0] ?? { name: "", body: {} };

  const [methodName, setMethodName] = useState(firstMethod.name);
  const [postUri, setPostUri] = useState(
    firstMethod.name ? `/api/${apiPrefix}/${firstMethod.name}` : ""
  );
  const [requestBody, setRequestBody] = useState(
    formatJson(firstMethod.body ?? {})
  );
  const [responseBody, setResponseBody] = useState("");
  const [status, setStatus] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  const [mockRequest, setMockRequest] = useState(null);
  const [mockStatus, setMockStatus] = useState("");
  const [mockResult, setMockResult] = useState("");

  const selectMethod = (method) => {
    setMethodName(method.name);
    setPostUri(`/api/${apiPrefix}/${method.name}`);
    setRequestBody(formatJson(method.body ?? {}));
    setResponseBody("");
    setStatus("");
    setError("");
    setMockRequest(null);
    setMockStatus("");
    setMockResult("");
  };

  const formatText = (text, setter) => {
    try {
      if (!text.trim()) {
        setter("{}");
        setError("");
        return;
      }

      setter(formatJson(JSON.parse(text)));
      setError("");
    } catch (err) {
      setError(`Invalid JSON: ${err.message}`);
    }
  };

  const sendPostRequest = async () => {
    setError("");
    setStatus("");
    setBusy(true);

    try {
      if (!postUri.trim()) {
        throw new Error("Enter a POST URL.");
      }

      let parsedBody;

      try {
        parsedBody = requestBody.trim() ? JSON.parse(requestBody) : {};
      } catch (err) {
        throw new Error(`Invalid request JSON: ${err.message}`);
      }

      const canonicalBody = JSON.stringify(parsedBody);

      setRequestBody(formatJson(parsedBody));
      setResponseBody("");

      const response = await fetch(postUri.trim(), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: canonicalBody,
      });

      setStatus(`${response.status} ${response.statusText}`);
      setResponseBody(await prettyResponse(response));

      if (!response.ok) {
        setError(`Request failed with HTTP ${response.status}.`);
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  };

  const setMockResponse = async () => {
    setError("");
    setMockRequest(null);
    setMockStatus("");
    setMockResult("");
    setBusy(true);

    try {
      if (!methodName.trim()) {
        throw new Error("Enter the API method name for the mock response.");
      }

      let parsedResponse;

      try {
        parsedResponse = JSON.parse(responseBody);
      } catch (err) {
        throw new Error(`Invalid response JSON: ${err.message}`);
      }

      setResponseBody(formatJson(parsedResponse));

      const url = `/api/${apiPrefix}/setResponse`;

      const body = {
        api: methodName.trim(),
        response: parsedResponse,
      };

      setMockRequest({
        url,
        body: formatJson(body),
      });

      const response = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
      });

      setMockStatus(`${response.status} ${response.statusText}`);
      setMockResult(await prettyResponse(response));

      if (!response.ok) {
        setError(`Setting mock response failed with HTTP ${response.status}.`);
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  };

  return html`
    <div class="panel">
      <div class="panel-header">
        <h4 class="panel-title">POST API Tester</h4>
      </div>

      <div class="panel-body">
        <div class="form-group">
          <div class="btn-group btn-group-block">
            ${methods.map(
              (method) => html`
                <button
                  key=${method.name}
                  type="button"
                  class=${"btn " +
                  (methodName === method.name ? "btn-primary" : "")}
                  disabled=${busy}
                  onClick=${() => selectMethod(method)}
                >
                  ${method.label}
                </button>
              `
            )}
          </div>
        </div>

        <div class="form-group">
          <label class="form-label">Request URL</label>
          <input
            class="form-input"
            type="text"
            value=${postUri}
            disabled=${busy}
            onInput=${(e) => setPostUri(e.target.value)}
          />
          <p class="form-input-hint">POST ${postUri}</p>
        </div>

        <div class="form-group">
          <label class="form-label">Request JSON</label>
          <textarea
            class="form-input code-editor"
            rows="8"
            spellcheck=${false}
            value=${requestBody}
            disabled=${busy}
            onInput=${(e) => setRequestBody(e.target.value)}
          ></textarea>
        </div>

        <div class="form-group">
          <button
            type="button"
            class="btn btn-primary"
            disabled=${busy}
            onClick=${sendPostRequest}
          >
            Send POST
          </button>

          <button
            type="button"
            class="btn"
            disabled=${busy}
            onClick=${() => formatText(requestBody, setRequestBody)}
          >
            Format Request
          </button>
        </div>

        ${status &&
        html`
          <p>
            <span class="label label-secondary">${status}</span>
          </p>
        `}

        ${error && html`<div class="toast toast-error">${error}</div>`}

        <div class="divider"></div>

        <div class="form-group">
          <label class="form-label">Response JSON</label>
          <textarea
            class="form-input code-editor"
            rows="10"
            spellcheck=${false}
            placeholder="Send a request, or paste JSON here to configure a mock response."
            value=${responseBody}
            disabled=${busy}
            onInput=${(e) => setResponseBody(e.target.value)}
          ></textarea>
          <p class="form-input-hint">
            Edit this JSON, then click Set Mock Response.
          </p>
        </div>

        <div class="form-group">
          <label class="form-label">Mock API method name</label>
          <input
            class="form-input"
            type="text"
            value=${methodName}
            disabled=${busy}
            onInput=${(e) => setMethodName(e.target.value)}
          />
          <p class="form-input-hint">
            If you manually change the POST URL, make sure this method name
            still matches the API you want to mock.
          </p>
        </div>

        <div class="form-group">
          <button
            type="button"
            class="btn btn-primary"
            disabled=${busy || !responseBody.trim()}
            onClick=${setMockResponse}
          >
            Set Mock Response
          </button>

          <button
            type="button"
            class="btn"
            disabled=${busy || !responseBody.trim()}
            onClick=${() => formatText(responseBody, setResponseBody)}
          >
            Format Response
          </button>
        </div>

        ${busy && html`<div class="loading"></div>`}

        ${mockRequest &&
        html`
          <div class="divider"></div>

          <h6>Mock Configuration Request</h6>
          <pre class="code">POST ${mockRequest.url}</pre>
          <pre class="code" data-lang="JSON">${mockRequest.body}</pre>

          <h6>Mock Configuration Response</h6>

          ${mockStatus &&
          html`
            <p>
              <span class="label label-secondary">${mockStatus}</span>
            </p>
          `}

          <pre class="code">${mockResult}</pre>
        `}
      </div>
    </div>
  `;
};

const VisionPage = ({ apiPrefix }) => {
  return html`
    <div class="container">
      <div class="columns">
        <div class="column col-6 col-md-12">
          <${PostApiPanel} key=${apiPrefix} apiPrefix=${apiPrefix} />
        </div>

        <div class="column col-6 col-md-12">
          <${GetImagePanel} apiPrefix=${apiPrefix} />
          <${SetMockResponsePanel} apiPrefix=${apiPrefix} />
        </div>
      </div>
    </div>
  `;
};

const Vision1Page = VisionPage;
const Vision2Page = VisionPage;
```

Add these styles to your existing `<style>` block:

```css
.code-editor {
  font-family: Consolas, Monaco, "Courier New", monospace;
  font-size: 13px;
  line-height: 1.5;
  tab-size: 2;
  resize: vertical;
}

.column {
  min-width: 0;
}

.panel-body .toast {
  margin: 12px 0;
}
```

This gives each tab a left pane with method buttons, editable request URL/body, editable response JSON, and a button to set the mock response.

---

## Evaluation of Assistant A and Assistant B

### Assistant A

Assistant A provides a complete HTML file and introduces a `PostApiPanel` component. It satisfies the basic request: it adds buttons for POST methods, shows the request URL/body/response, allows editing the request body, and allows setting a mock response.

However, there are several weaknesses:

1. **It uses `alert()` for mock-response results.**  
   This is not ideal for a UI like this. It would be better to display the mock request and mock response inside the page using Spectre panels, labels, or `<pre>` blocks.

2. **It does not display the mock configuration request/response in the UI.**  
   The user asked to display request/response JSON for the API tester. For mock configuration, it is also helpful to show the URL, JSON body, and result. Assistant A only shows an alert.

3. **It assumes the mock endpoint is `/api/setresponse/${apiPrefix}/${selectedMethod}`.**  
   That matches the unused `TabPage` helper in the original code, but it does not match the visible `SetMockResponsePanel`, which uses:

   ```http
   POST /api/{apiPrefix}/setResponse
   ```

   with:

   ```json
   {
     "api": "getImage",
     "response": { ... }
   }
   ```

   A more consistent implementation would either use the existing `setResponse` contract or clearly explain the assumption.

4. **It does not handle non-JSON responses gracefully.**  
   It calls `response.json()` directly. If the server returns plain text, HTML, or an error page, the UI will throw an error. A better implementation reads `response.text()` and attempts to parse JSON.

5. **The selected mock method is not synchronized with manual URL edits.**  
   If the user manually edits the POST URI, `selectedMethod` may no longer match the URL. This can cause the mock response to be set for the wrong method.

6. **There is no HTTP status display or robust validation.**  
   Assistant B handles this better.

Overall, Assistant A is helpful but less polished and less robust.

### Assistant B

Assistant B provides a focused replacement for the Vision page components. It is much closer to an ideal solution.

Strengths:

1. **It adds configurable method buttons.**  
   It includes `FindPosition`, `detectObjects`, and `classifyImage`, and allows per-tab configuration through `methodsByPrefix`.

2. **It uses the current tab’s `apiPrefix`.**  
   This fixes the original issue where some buttons were hard-coded to `/api/vision2/...`.

3. **It displays the request URL, request JSON, response JSON, HTTP status, errors, and mock configuration details.**

4. **It allows the user to edit the request JSON and send it again.**

5. **It allows the user to edit the response JSON and set it as a mock response.**

6. **It validates JSON before sending.**

7. **It handles non-JSON responses by displaying raw text.**

8. **It avoids `alert()` and instead shows results in the UI.**

9. **It preserves the existing `ApiTester`, `GetImagePanel`, and `SetMockResponsePanel` components.**

10. **It explicitly states the mock API assumption.**  
   It uses:

   ```http
   POST /api/{apiPrefix}/setResponse
   ```

   with:

   ```json
   {
     "api": "FindPosition",
     "response": { ... }
   }
   ```

   This is consistent with the existing `SetMockResponsePanel`.

Minor issues:

1. If the request body is empty, Assistant B treats it as invalid JSON. It could instead treat an empty body as `{}`.
2. The method names may need casing adjustments depending on the real backend, but Assistant B notes that these should be matched to the actual API.
3. It provides a code fragment rather than a full HTML file, but given the original file and the nature of the request, that is appropriate.

Overall, Assistant B is significantly more robust, more consistent with the existing code, and more useful for the requested feature.

My final verdict is Assistant B is significantly better: [[B>>A]]

Here is a robust way to modify the page. You can keep your existing `GetImagePanel`, `SetMockResponsePanel`, and `ApiTester`, and replace the current `Vision1Page` / `Vision2Page` implementations with the components below.

This adds, in the left pane of every tab:

- Buttons for POST API methods such as `FindPosition`, `detectObjects`, `classifyImage`, etc.
- Editable POST URL.
- Editable request JSON body.
- Display of the last request URL and JSON body.
- Editable response JSON.
- A button to send the edited response JSON as a mock response.
- Error handling and HTTP status display.

```javascript
// Add/replace this section in your existing <script type="module"> block.
// Keep your existing imports, GetImagePanel, SetMockResponsePanel, and ApiTester.

const DEFAULT_POST_METHODS = [
  {
    name: "FindPosition",
    label: "Find Position",
    body: {},
  },
  {
    name: "detectObjects",
    label: "Detect Objects",
    body: {},
  },
  {
    name: "classifyImage",
    label: "Classify Image",
    body: {},
  },
];

// Optional: customize methods per tab/apiPrefix.
// Example:
// POST_METHODS_BY_PREFIX.visionSystem = [
//   { name: "GetStatus", label: "Get Status", body: {} },
// ];
const POST_METHODS_BY_PREFIX = {};

const prettyJson = (value) => JSON.stringify(value, null, 2);

const readResponseText = async (response) => {
  const text = await response.text();

  try {
    return prettyJson(JSON.parse(text));
  } catch {
    return text;
  }
};

const methodNameFromUrl = (url) => {
  const clean = String(url || "").trim().split("?")[0];
  if (!clean) return "";

  try {
    const path = new URL(clean, window.location.origin).pathname;
    return path.split("/").filter(Boolean).pop() || "";
  } catch {
    return clean.split("/").filter(Boolean).pop() || "";
  }
};

const PostApiPanel = ({ apiPrefix }) => {
  const methods = POST_METHODS_BY_PREFIX[apiPrefix] || DEFAULT_POST_METHODS;
  const initialMethod = methods[0] || { name: "", label: "POST", body: {} };

  const [selectedMethod, setSelectedMethod] = useState(initialMethod.name);
  const [postUrl, setPostUrl] = useState(`/api/${apiPrefix}/${initialMethod.name}`);
  const [requestBody, setRequestBody] = useState(prettyJson(initialMethod.body || {}));
  const [lastRequest, setLastRequest] = useState(null);

  const [responseStatus, setResponseStatus] = useState("");
  const [responseBody, setResponseBody] = useState("");

  const [mockRequest, setMockRequest] = useState(null);
  const [mockStatus, setMockStatus] = useState("");
  const [mockResult, setMockResult] = useState("");

  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  const chooseMethod = (method) => {
    setSelectedMethod(method.name);
    setPostUrl(`/api/${apiPrefix}/${method.name}`);
    setRequestBody(prettyJson(method.body || {}));

    setLastRequest(null);
    setResponseStatus("");
    setResponseBody("");

    setMockRequest(null);
    setMockStatus("");
    setMockResult("");

    setError("");
  };

  const formatRequest = () => {
    try {
      if (!requestBody.trim()) {
        setRequestBody("{}");
        setError("");
        return;
      }

      setRequestBody(prettyJson(JSON.parse(requestBody)));
      setError("");
    } catch (err) {
      setError(`Request JSON is invalid: ${err.message}`);
    }
  };

  const formatResponse = () => {
    try {
      if (!responseBody.trim()) {
        setResponseBody("{}");
        setError("");
        return;
      }

      setResponseBody(prettyJson(JSON.parse(responseBody)));
      setError("");
    } catch (err) {
      setError(`Response JSON is invalid: ${err.message}`);
    }
  };

  const sendPostRequest = async () => {
    setError("");
    setResponseStatus("");
    setBusy(true);

    try {
      const url = postUrl.trim();
      if (!url) {
        throw new Error("Enter a POST URL.");
      }

      let parsedBody;
      if (!requestBody.trim()) {
        parsedBody = {};
      } else {
        try {
          parsedBody = JSON.parse(requestBody);
        } catch (err) {
          throw new Error(`Request JSON is invalid: ${err.message}`);
        }
      }

      const formattedBody = prettyJson(parsedBody);
      setRequestBody(formattedBody);

      setLastRequest({
        url,
        body: formattedBody,
      });

      const response = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(parsedBody),
      });

      setResponseStatus(`${response.status} ${response.statusText}`);
      setResponseBody(await readResponseText(response));

      if (!response.ok) {
        setError(`POST request failed with HTTP ${response.status}.`);
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  };

  const sendMockResponse = async () => {
    setError("");
    setMockRequest(null);
    setMockStatus("");
    setMockResult("");
    setBusy(true);

    try {
      const apiName = methodNameFromUrl(postUrl) || selectedMethod;
      if (!apiName) {
        throw new Error("Could not determine the API method name from the POST URL.");
      }

      let parsedResponse;
      if (!responseBody.trim()) {
        parsedResponse = {};
      } else {
        try {
          parsedResponse = JSON.parse(responseBody);
        } catch (err) {
          throw new Error(`Response JSON is invalid: ${err.message}`);
        }
      }

      const formattedResponse = prettyJson(parsedResponse);
      setResponseBody(formattedResponse);

      // This uses the same mock-response contract as your existing SetMockResponsePanel:
      //
      // POST /api/{apiPrefix}/setResponse
      // {
      //   "api": "FindPosition",
      //   "response": { ... }
      // }
      //
      // If your backend instead expects:
      //
      // POST /api/setresponse/{apiPrefix}/{apiName}
      // { ...response JSON... }
      //
      // change this section accordingly.
      const mockUrl = `/api/${apiPrefix}/setResponse`;
      const mockPayload = {
        api: apiName,
        response: parsedResponse,
      };

      setMockRequest({
        url: mockUrl,
        body: prettyJson(mockPayload),
      });

      const response = await fetch(mockUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(mockPayload),
      });

      setMockStatus(`${response.status} ${response.statusText}`);
      setMockResult(await readResponseText(response));

      if (!response.ok) {
        setError(`Setting mock response failed with HTTP ${response.status}.`);
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  };

  return html`
    <div class="panel">
      <div class="panel-header">
        <h4 class="panel-title">POST API Tester</h4>
      </div>

      <div class="panel-body">
        <div class="form-group">
          ${methods.map(
            (method) => html`
              <button
                key=${method.name}
                type="button"
                class=${`btn ${selectedMethod === method.name ? "btn-primary" : ""}`}
                disabled=${busy}
                onClick=${() => chooseMethod(method)}
              >
                ${method.label}
              </button>
            `
          )}
        </div>

        <div class="form-group">
          <label class="form-label">POST URL</label>
          <input
            class="form-input"
            type="text"
            value=${postUrl}
            disabled=${busy}
            onInput=${(e) => setPostUrl(e.target.value)}
          />
          <p class="form-input-hint">Current request: POST ${postUrl || "(no URL)"}</p>
        </div>

        <div class="form-group">
          <label class="form-label">Request JSON Body</label>
          <textarea
            class="form-input json-editor"
            rows="8"
            spellcheck=${false}
            value=${requestBody}
            disabled=${busy}
            onInput=${(e) => setRequestBody(e.target.value)}
          ></textarea>
        </div>

        <div class="form-group">
          <button
            type="button"
            class="btn btn-primary"
            disabled=${busy}
            onClick=${sendPostRequest}
          >
            Send POST
          </button>

          <button
            type="button"
            class="btn"
            disabled=${busy}
            onClick=${formatRequest}
          >
            Format Request
          </button>
        </div>

        ${lastRequest &&
        html`
          <div class="form-group">
            <span class="label label-rounded label-primary">Last Request</span>
            <pre class="code">POST ${lastRequest.url}</pre>
            <pre class="code" data-lang="JSON">${lastRequest.body}</pre>
          </div>
        `}

        ${responseStatus &&
        html`
          <p>
            <span class="label label-rounded label-secondary">
              Response Status: ${responseStatus}
            </span>
          </p>
        `}

        <div class="form-group">
          <label class="form-label">Response JSON, Editable</label>
          <textarea
            class="form-input json-editor"
            rows="10"
            spellcheck=${false}
            placeholder="Send a request, or type JSON here to use it as a mock response."
            value=${responseBody}
            disabled=${busy}
            onInput=${(e) => setResponseBody(e.target.value)}
          ></textarea>
        </div>

        <div class="form-group">
          <button
            type="button"
            class="btn btn-primary"
            disabled=${busy || !responseBody.trim()}
            onClick=${sendMockResponse}
          >
            Set Mock Response
          </button>

          <button
            type="button"
            class="btn"
            disabled=${busy || !responseBody.trim()}
            onClick=${formatResponse}
          >
            Format Response
          </button>
        </div>

        ${busy && html`<div class="loading"></div>`}

        ${error && html`<div class="toast toast-error">${error}</div>`}

        ${mockRequest &&
        html`
          <div class="divider"></div>

          <h6>Mock Request</h6>
          <pre class="code">POST ${mockRequest.url}</pre>
          <pre class="code" data-lang="JSON">${mockRequest.body}</pre>

          ${mockStatus &&
          html`
            <p>
              <span class="label label-rounded label-secondary">
                Mock Response Status: ${mockStatus}
              </span>
            </p>
          `}

          ${mockResult &&
          html`
            <pre class="code" data-lang="JSON">${mockResult}</pre>
          `}
        `}
      </div>
    </div>
  `;
};

const VisionPage = ({ apiPrefix }) => {
  return html`
    <div class="container">
      <div class="columns">
        <div class="column col-6 col-md-12">
          <${PostApiPanel} key=${apiPrefix} apiPrefix=${apiPrefix} />
        </div>

        <div class="column col-6 col-md-12">
          <${GetImagePanel} apiPrefix=${apiPrefix} />
          <${SetMockResponsePanel} apiPrefix=${apiPrefix} />
        </div>
      </div>
    </div>
