## My answer to the prompt

Below is a production-oriented React Native component that:

- Renders the text as one line when collapsed.
- Shows an inline `See more` only when the text would overflow one line.
- Ensures `See more` actually fits at the end of the first line by measuring and truncating the text safely.
- Handles Unicode/grapheme clusters safely using `graphemer`.
- Supports controlled or uncontrolled expansion.
- Includes accessibility support.
- Handles dynamic width changes.
- Avoids showing a hidden measurement layer to the user or accessibility tools.

### 1. Install dependency

```bash
npm install graphemer
```

### 2. `ExpandableText.tsx`

```tsx
import React, {
  useLayoutEffect,
  useMemo,
  useState,
} from 'react';
import {
  LayoutChangeEvent,
  NativeSyntheticEvent,
  StyleProp,
  StyleSheet,
  Text,
  TextLayoutEventData,
  TextStyle,
  useWindowDimensions,
  View,
  ViewStyle,
} from 'react-native';
import Graphemer from 'graphemer';

const graphemer = new Graphemer();

export interface ExpandableTextProps {
  text: string;
  moreLabel?: string;

  containerStyle?: StyleProp<ViewStyle>;
  textStyle?: StyleProp<TextStyle>;
  moreTextStyle?: StyleProp<TextStyle>;

  /**
   * Controlled expanded state.
   * If omitted, the component manages its own state.
   */
  expanded?: boolean;
  defaultExpanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;

  allowFontScaling?: boolean;
  maxFontSizeMultiplier?: number;

  testID?: string;
}

type Phase = 'full' | 'search' | 'done';

interface MeasurementState {
  revision: object;
  phase: Phase;
  low: number;
  high: number;
  best: number;
  fitsWithoutTruncation: boolean;
}

function createMeasurement(
  revision: object,
  graphemeCount: number,
): MeasurementState {
  return {
    revision,
    phase: 'full',
    low: 0,
    high: Math.max(0, graphemeCount - 1),
    best: 0,
    fitsWithoutTruncation: false,
  };
}

interface CollapsedTextProps {
  text: string;
  width: number;
  moreLabel: string;
  textStyle?: StyleProp<TextStyle>;
  moreTextStyle?: StyleProp<TextStyle>;
  allowFontScaling: boolean;
  maxFontSizeMultiplier?: number;
  onExpand: () => void;
  testID?: string;
}

function CollapsedText({
  text,
  width,
  moreLabel,
  textStyle,
  moreTextStyle,
  allowFontScaling,
  maxFontSizeMultiplier,
  onExpand,
  testID,
}: CollapsedTextProps) {
  const { fontScale } = useWindowDimensions();

  const graphemes = useMemo(
    () => graphemer.splitGraphemes(text),
    [text],
  );

  /**
   * Any change that can affect wrapping starts a new measurement pass.
   *
   * Important: if you pass inline style objects directly, their identity
   * changes every render and can cause remeasurement. For best performance,
   * use StyleSheet.create or memoized style objects.
   */
  const revision = useMemo(
    () => ({}),
    [
      text,
      width,
      moreLabel,
      textStyle,
      moreTextStyle,
      allowFontScaling,
      maxFontSizeMultiplier,
      fontScale,
    ],
  );

  const [measurement, setMeasurement] = useState<MeasurementState>(() =>
    createMeasurement(revision, graphemes.length),
  );

  useLayoutEffect(() => {
    setMeasurement(current =>
      current.revision === revision
        ? current
        : createMeasurement(revision, graphemes.length),
    );
  }, [revision, graphemes.length]);

  const isCurrent = measurement.revision === revision;
  const isReady = isCurrent && measurement.phase === 'done';
  const showMore = isReady && !measurement.fitsWithoutTruncation;

  const middle = Math.floor(
    (measurement.low + measurement.high) / 2,
  );

  const renderTruncatedContent = (graphemeCount: number) => {
    const prefix = graphemes
      .slice(0, graphemeCount)
      .join('')
      .trimEnd();

    return (
      <>
        {prefix ? `${prefix}\u2026\u00A0` : null}
        <Text
          style={[styles.moreText, moreTextStyle]}
          allowFontScaling={allowFontScaling}
          maxFontSizeMultiplier={maxFontSizeMultiplier}
        >
          {moreLabel}
        </Text>
      </>
    );
  };

  const handleTextLayout = (
    event: NativeSyntheticEvent<TextLayoutEventData>,
  ) => {
    const { lines } = event.nativeEvent;

    const fits =
      lines.length <= 1 &&
      (lines[0]?.width ?? 0) <= width + 0.5;

    setMeasurement(current => {
      // Ignore stale layout events from previous probes or previous props.
      if (
        current.revision !== revision ||
        current.phase !== measurement.phase ||
        current.low !== measurement.low ||
        current.high !== measurement.high ||
        current.phase === 'done'
      ) {
        return current;
      }

      if (current.phase === 'full') {
        return fits
          ? {
              ...current,
              phase: 'done',
              fitsWithoutTruncation: true,
            }
          : {
              ...current,
              phase: 'search',
            };
      }

      const candidate = Math.floor(
        (current.low + current.high) / 2,
      );

      const nextLow = fits ? candidate + 1 : current.low;
      const nextHigh = fits ? current.high : candidate - 1;
      const nextBest = fits ? candidate : current.best;

      return {
        ...current,
        low: nextLow,
        high: nextHigh,
        best: nextBest,
        phase: nextLow > nextHigh ? 'done' : 'search',
      };
    });
  };

  return (
    <>
      <Text
        testID={testID}
        style={[styles.text, textStyle]}
        numberOfLines={1}
        ellipsizeMode="tail"
        allowFontScaling={allowFontScaling}
        maxFontSizeMultiplier={maxFontSizeMultiplier}
        accessible
        accessibilityRole={showMore ? 'button' : undefined}
        accessibilityLabel={text}
        accessibilityHint={showMore ? moreLabel : undefined}
        accessibilityState={
          showMore ? { expanded: false } : undefined
        }
        onPress={showMore ? onExpand : undefined}
      >
        {showMore
          ? renderTruncatedContent(measurement.best)
          : text}
      </Text>

      {isCurrent && measurement.phase !== 'done' && (
        <View
          style={styles.measurementContainer}
          pointerEvents="none"
          accessible={false}
          accessibilityElementsHidden
          importantForAccessibility="no-hide-descendants"
        >
          <Text
            key={[
              measurement.phase,
              measurement.low,
              measurement.high,
            ].join(':')}
            style={[styles.text, textStyle]}
            allowFontScaling={allowFontScaling}
            maxFontSizeMultiplier={maxFontSizeMultiplier}
            onTextLayout={handleTextLayout}
            accessible={false}
          >
            {measurement.phase === 'full'
              ? text
              : renderTruncatedContent(middle)}
          </Text>
        </View>
      )}
    </>
  );
}

export function ExpandableText({
  text,
  moreLabel = 'See more',
  containerStyle,
  textStyle,
  moreTextStyle,
  expanded,
  defaultExpanded = false,
  onExpandedChange,
  allowFontScaling = true,
  maxFontSizeMultiplier,
  testID,
}: ExpandableTextProps) {
  const [internalExpanded, setInternalExpanded] =
    useState(defaultExpanded);

  const [width, setWidth] = useState(0);

  const isExpanded = expanded ?? internalExpanded;
  const label = moreLabel.trim() || 'See more';

  const handleLayout = (event: LayoutChangeEvent) => {
    const nextWidth = event.nativeEvent.layout.width;

    setWidth(current =>
      current === nextWidth ? current : nextWidth,
    );
  };

  const handleExpand = () => {
    if (isExpanded) {
      return;
    }

    if (expanded === undefined) {
      setInternalExpanded(true);
    }

    onExpandedChange?.(true);
  };

  return (
    <View style={containerStyle}>
      <View style={styles.content} onLayout={handleLayout}>
        {isExpanded || width <= 0 ? (
          <Text
            testID={testID}
            style={[styles.text, textStyle]}
            numberOfLines={isExpanded ? undefined : 1}
            ellipsizeMode="tail"
            allowFontScaling={allowFontScaling}
            maxFontSizeMultiplier={maxFontSizeMultiplier}
          >
            {text}
          </Text>
        ) : (
          <CollapsedText
            text={text}
            width={width}
            moreLabel={label}
            textStyle={textStyle}
            moreTextStyle={moreTextStyle}
            allowFontScaling={allowFontScaling}
            maxFontSizeMultiplier={maxFontSizeMultiplier}
            onExpand={handleExpand}
            testID={testID}
          />
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  content: {
    alignSelf: 'stretch',
    position: 'relative',
  },
  text: {
    fontSize: 16,
    lineHeight: 22,
    color: '#111827',
  },
  moreText: {
    color: '#007AFF',
    fontWeight: '600',
  },
  measurementContainer: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    opacity: 0,
  },
});
```

### 3. Usage example

```tsx
import React from 'react';
import { SafeAreaView, StyleSheet } from 'react-native';
import { ExpandableText } from './ExpandableText';

export default function Screen() {
  return (
    <SafeAreaView style={styles.screen}>
      <ExpandableText
        text="React Native lets you build native applications using React. This longer description initially occupies one line, and expands when the user taps See more."
        containerStyle={styles.description}
        textStyle={styles.text}
        moreTextStyle={styles.more}
        onExpandedChange={value => {
          console.log('Expanded:', value);
        }}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  screen: {
    flex: 1,
    padding: 20,
  },
  description: {
    marginBottom: 16,
  },
  text: {
    fontSize: 16,
    lineHeight: 22,
    color: '#1F2937',
  },
  more: {
    color: '#0066CC',
    fontWeight: '700',
  },
});
```

### Important production notes

1. The component needs a bounded width.  
   If it is inside a horizontal layout, give the container `flex: 1` or a fixed width.

2. Avoid putting horizontal padding/margin in `textStyle` if possible.  
   Put spacing on `containerStyle`. Padding on the measured `Text` can make the available text width different from the container width.

3. If you use custom fonts, make sure they are loaded before rendering this component, or remount it after fonts are loaded.  
   Font metrics affect measurement.

4. This implementation makes the whole collapsed line tappable when expansion is available.  
   That is usually better for touch targets and accessibility. If you want only the literal `See more` text to be tappable, move `onPress` to the nested `moreText` node and adjust accessibility accordingly.

---

## Evaluation of Assistant A and Assistant B

### Assistant A

Assistant A provides a simple component using `numberOfLines={1}` and appending a nested `See more` text inside the same `Text` node.

The intention is correct, but the implementation has a critical production issue: when the text is collapsed, the appended `See more` becomes part of the same one-line text. React Native truncates the whole line using `numberOfLines={1}` and `ellipsizeMode`, so the `See more` label can itself be truncated, hidden, or non-touchable. In other words, the component does not reliably reserve space for the `See more` action.

Other issues:

- `showSeeMore` is only ever set to `true`; it is never reset if the `text` prop later becomes shorter. This can cause `See more` to remain visible even when the text now fits on one line.
- It does not measure the available width or calculate whether the text plus `See more` actually fits.
- It does not handle Unicode grapheme clusters safely, so truncation could split emoji or combined characters if you implement manual slicing later.
- Accessibility is minimal. There is no `accessibilityRole`, expanded state, or hint.
- It is not controlled/uncontrolled; it only supports one-way internal expansion.
- It is fine as a quick demo, but not robust enough for production use.

So while Assistant A’s answer is concise, it does not reliably satisfy the requirement that `See more` appear at the end of the first line when the text overflows.

### Assistant B

Assistant B provides a much more robust solution. It correctly identifies the core problem: `numberOfLines={1}` alone is not enough because React Native may truncate the `See more` label itself.

Its approach:

- Measures the container width.
- Uses a hidden measurement layer.
- Uses `onTextLayout` to determine whether the full text fits.
- Performs a binary search over grapheme-safe text segments to find the longest prefix that fits together with the `See more` label.
- Uses `graphemer` to avoid splitting emoji or combined Unicode characters.
- Supports controlled and uncontrolled expansion.
- Includes accessibility considerations.
- Handles font scaling changes through `useWindowDimensions`.

This is the right general production strategy and is very close to the reference solution I provided.

Minor caveats:

- It is complex, but the problem genuinely requires measurement logic if you want a reliable inline `See more`.
- It requires installing `graphemer`.
- It requires a bounded width, though the answer mentions this.
- The whole collapsed line is tappable, not only the literal `See more` text. This is usually acceptable and often better for accessibility/touch targets, but if the product requirement is strictly “only See more is clickable,” this would need a small modification.
- For perfect parity, the nested `See more` text could also explicitly receive `allowFontScaling` and `maxFontSizeMultiplier`.
- Inline style objects can cause remeasurement if their identity changes every render, so styles should ideally be memoized or created with `StyleSheet.create`.

Overall, Assistant B’s answer is production-oriented, technically accurate, and solves the real edge cases.

My final verdict is Assistant B is significantly better: [[B>>A]]

My production-ready answer to the prompt:

A reliable implementation cannot simply append `" See more"` inside a `Text` with `numberOfLines={1}`, because the appended label will usually be truncated together with the text. The robust approach is:

1. Measure whether the full text exceeds one line.
2. If it does, measure a truncated prefix plus `… See more` until it fits exactly on one line.
3. Render that measured truncated line.
4. Expand on press.

Below is a production-ready TypeScript component.

### 1. Install dependency

This version uses `graphemer` to avoid breaking emoji / combined Unicode characters when truncating.

```bash
npm install graphemer
```

### 2. `ExpandableText.tsx`

```tsx
import React, { useLayoutEffect, useMemo, useState } from 'react';
import {
  LayoutChangeEvent,
  NativeSyntheticEvent,
  StyleProp,
  StyleSheet,
  Text,
  TextLayoutEventData,
  TextStyle,
  useWindowDimensions,
  View,
  ViewStyle,
} from 'react-native';
import Graphemer from 'graphemer';

const graphemer = new Graphemer();

export interface ExpandableTextProps {
  text: string;
  seeMoreLabel?: string;

  containerStyle?: StyleProp<ViewStyle>;

  /**
   * For most reliable measurement, keep this to typography-related styles:
   * color, fontSize, lineHeight, fontWeight, fontFamily, letterSpacing, etc.
   *
   * Put padding/margin/width on containerStyle when possible.
   */
  textStyle?: StyleProp<TextStyle>;
  seeMoreTextStyle?: StyleProp<TextStyle>;

  /** Controlled expanded state */
  expanded?: boolean;

  /** Uncontrolled initial expanded state */
  defaultExpanded?: boolean;

  onExpandedChange?: (expanded: boolean) => void;

  allowFontScaling?: boolean;
  maxFontSizeMultiplier?: number;

  testID?: string;
}

type MeasurePhase = 'full' | 'search' | 'done';

interface MeasureState {
  revision: object;
  phase: MeasurePhase;
  low: number;
  high: number;
  best: number;
  overflow: boolean;
  probeKey: string;
}

function createMeasureState(
  revision: object,
  graphemeCount: number,
): MeasureState {
  return {
    revision,
    phase: 'full',
    low: 0,
    high: Math.max(0, graphemeCount - 1),
    best: 0,
    overflow: false,
    probeKey: 'full',
  };
}

export function ExpandableText({
  text,
  seeMoreLabel = 'See more',
  containerStyle,
  textStyle,
  seeMoreTextStyle,
  expanded,
  defaultExpanded = false,
  onExpandedChange,
  allowFontScaling = true,
  maxFontSizeMultiplier,
  testID,
}: ExpandableTextProps) {
  const [internalExpanded, setInternalExpanded] =
    useState(defaultExpanded);
  const [width, setWidth] = useState(0);

  const { fontScale } = useWindowDimensions();

  const isExpanded = expanded ?? internalExpanded;
  const label = seeMoreLabel.trim() || 'See more';

  const graphemes = useMemo(
    () => graphemer.splitGraphemes(text),
    [text],
  );

  const flattenedTextStyle = useMemo(
    () => StyleSheet.flatten(textStyle),
    [textStyle],
  );

  const flattenedSeeMoreStyle = useMemo(
    () => StyleSheet.flatten(seeMoreTextStyle),
    [seeMoreTextStyle],
  );

  /**
   * Avoid restarting measurement when parents pass inline style objects
   * whose values did not actually change.
   */
  const styleKey = useMemo(
    () =>
      JSON.stringify({
        text: flattenedTextStyle,
        more: flattenedSeeMoreStyle,
      }),
    [flattenedTextStyle, flattenedSeeMoreStyle],
  );

  const revision = useMemo(
    () => ({}),
    [
      text,
      width,
      label,
      styleKey,
      allowFontScaling,
      maxFontSizeMultiplier,
      fontScale,
    ],
  );

  const [measure, setMeasure] = useState(() =>
    createMeasureState(revision, graphemes.length),
  );

  useLayoutEffect(() => {
    setMeasure(current =>
      current.revision === revision
        ? current
        : createMeasureState(revision, graphemes.length),
    );
  }, [revision, graphemes.length]);

  const isCurrent = measure.revision === revision;
  const isReady = isCurrent && measure.phase === 'done';
  const showSeeMore = isReady && measure.overflow;

  const handleLayout = (event: LayoutChangeEvent) => {
    const nextWidth = event.nativeEvent.layout.width;

    setWidth(current =>
      current === nextWidth ? current : nextWidth,
    );
  };

  const handleExpand = () => {
    if (isExpanded) {
      return;
    }

    if (expanded === undefined) {
      setInternalExpanded(true);
    }

    onExpandedChange?.(true);
  };

  const renderWithSuffix = (graphemeCount: number) => {
    const prefix = graphemes
      .slice(0, graphemeCount)
      .join('')
      .replace(/\s+$/, '');

    return (
      <>
        {prefix ? `${prefix}\u2026\u00A0` : null}
        <Text style={[styles.seeMore, seeMoreTextStyle]}>
          {label}
        </Text>
      </>
    );
  };

  const mid = Math.floor(
    (measure.low + measure.high) / 2,
  );

  const handleMeasure = (
    event: NativeSyntheticEvent<TextLayoutEventData>,
  ) => {
    const lines = event.nativeEvent.lines;

    const fits =
      lines.length <= 1 &&
      (lines[0]?.width ?? 0) <= width + 0.5;

    const expectedProbeKey = measure.probeKey;

    setMeasure(prev => {
      if (
        prev.revision !== revision ||
        prev.probeKey !== expectedProbeKey ||
        prev.phase === 'done'
      ) {
        return prev;
      }

      if (prev.phase === 'full') {
        if (fits) {
          return {
            ...prev,
            phase: 'done',
            overflow: false,
            probeKey: 'done',
          };
        }

        return {
          ...prev,
          phase: 'search',
          overflow: true,
          probeKey: `search:${prev.low}:${prev.high}`,
        };
      }

      const candidate = Math.floor(
        (prev.low + prev.high) / 2,
      );

      if (fits) {
        const nextLow = candidate + 1;
        const done = nextLow > prev.high;

        return {
          ...prev,
          low: nextLow,
          best: candidate,
          phase: done ? 'done' : 'search',
          overflow: true,
          probeKey: done
            ? 'done'
            : `search:${nextLow}:${prev.high}`,
        };
      }

      const nextHigh = candidate - 1;
      const done = prev.low > nextHigh;

      return {
        ...prev,
        high: nextHigh,
        phase: done ? 'done' : 'search',
        overflow: true,
        probeKey: done
          ? 'done'
          : `search:${prev.low}:${nextHigh}`,
      };
    });
  };

  return (
    <View style={containerStyle}>
      <View style={styles.content} onLayout={handleLayout}>
        {isExpanded || width <= 0 ? (
          <Text
            testID={testID}
            style={[styles.text, textStyle]}
            numberOfLines={isExpanded ? undefined : 1}
            ellipsizeMode="tail"
            allowFontScaling={allowFontScaling}
            maxFontSizeMultiplier={maxFontSizeMultiplier}
          >
            {text}
          </Text>
        ) : (
          <>
            <Text
              testID={testID}
              style={[styles.text, textStyle]}
              numberOfLines={1}
              ellipsizeMode="tail"
              allowFontScaling={allowFontScaling}
              maxFontSizeMultiplier={maxFontSizeMultiplier}
              onPress={showSeeMore ? handleExpand : undefined}
              accessible={showSeeMore ? true : undefined}
              accessibilityRole={
                showSeeMore ? 'button' : undefined
              }
              accessibilityLabel={
                showSeeMore ? text : undefined
              }
              accessibilityHint={
                showSeeMore ? label : undefined
              }
              accessibilityState={
                showSeeMore ? { expanded: false } : undefined
              }
            >
              {showSeeMore
                ? renderWithSuffix(measure.best)
                : text}
            </Text>

            {isCurrent && measure.phase !== 'done' && (
              <View
                style={styles.hidden}
                pointerEvents="none"
                accessible={false}
                accessibilityElementsHidden
                importantForAccessibility="no-hide-descendants"
              >
                <Text
                  key={measure.probeKey}
                  style={[styles.text, textStyle]}
                  allowFontScaling={allowFontScaling}
                  maxFontSizeMultiplier={maxFontSizeMultiplier}
                  onTextLayout={handleMeasure}
                  accessible={false}
                >
                  {measure.phase === 'full'
                    ? text
                    : renderWithSuffix(mid)}
                </Text>
              </View>
            )}
          </>
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  content: {
    alignSelf: 'stretch',
  },
  hidden: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    opacity: 0,
  },
  text: {
    fontSize: 16,
    lineHeight: 22,
    color: '#111827',
  },
  seeMore: {
    color: '#2563EB',
    fontWeight: '600',
  },
});

export default ExpandableText;
```

