## Modified server

Keep your existing `REGISTERED_EVENTS` array. Replace/add the following parts.

### Includes and constants

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>
#include <errno.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <libevdev/libevdev.h>
#include <libevdev/libevdev-uinput.h>
#include <unistd.h>
#include <linux/input.h>

#define PORT 31415

#define EVENT_COUNT \
    (sizeof(REGISTERED_EVENTS) / sizeof(REGISTERED_EVENTS[0]))

#define PAIR_SIZE 4
#define PACKET_SIZE (EVENT_COUNT * PAIR_SIZE)
```

### Helper to read little-endian `int16`

```c
static int read_i16_le(const uint8_t *p) {
    uint32_t value = (uint32_t)p[0] | ((uint32_t)p[1] << 8);

    if (value & 0x8000u) {
        return (int)value - 65536;
    }

    return (int)value;
}
```

### Use full signed 16-bit axis range

Your example uses `-32768`, so the absolute axis range should be:

```c
static struct libevdev_uinput *controller_create(void) {
    struct libevdev *device = libevdev_new();
    libevdev_set_name(device, "Virtual Game Controller");

    struct input_absinfo absinfo = {
        .value = 0,
        .minimum = -32768,
        .maximum = 32767,
        .flat = 0,
        .fuzz = 0,
        .resolution = 0
    };

    for (size_t i = 0; i < EVENT_COUNT; ++i) {
        libevdev_enable_event_code(
            device,
            REGISTERED_EVENTS[i].type,
            REGISTERED_EVENTS[i].code,
            (REGISTERED_EVENTS[i].type == EV_ABS) ? &absinfo : NULL
        );
    }

    struct libevdev_uinput *ui;
    if (libevdev_uinput_create_from_device(
            device,
            LIBEVDEV_UINPUT_OPEN_MANAGED,
            &ui) < 0) {
        fprintf(stderr, "Failed to create uinput device\n");
        exit(EXIT_FAILURE);
    }

    libevdev_free(device);
    return ui;
}
```

### Replace `udp_server`

```c
static void udp_server(void) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    serv_addr.sin_port = htons(PORT);

    if (bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("bind");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    /*
     * One extra byte allows oversized packets to be rejected.
     */
    uint8_t buffer[PACKET_SIZE + 1];

    for (;;) {
        ssize_t n = recvfrom(
            sockfd,
            buffer,
            sizeof(buffer),
            0,
            NULL,
            NULL
        );

        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }

            perror("recvfrom");
            break;
        }

        if ((size_t)n != PACKET_SIZE) {
            fprintf(
                stderr,
                "Invalid packet size: %zd, expected %zu\n",
                n,
                (size_t)PACKET_SIZE
            );
            continue;
        }

        int values[EVENT_COUNT];
        int valid = 1;

        /*
         * Validate the packet before emitting events.
         *
         * This expects the packet to contain exactly EVENT_COUNT pairs,
         * in the same order as REGISTERED_EVENTS:
         *
         * index 0, value 0
         * index 1, value 1
         * ...
         */
        for (size_t i = 0; i < EVENT_COUNT; ++i) {
            size_t offset = i * PAIR_SIZE;

            int event_index = read_i16_le(buffer + offset);
            int event_value = read_i16_le(buffer + offset + 2);

            if (event_index != (int)i) {
                fprintf(
                    stderr,
                    "Invalid event index at position %zu: got %d, expected %zu\n",
                    i,
                    event_index,
                    i
                );
                valid = 0;
                break;
            }

            if (REGISTERED_EVENTS[i].type == EV_KEY &&
                event_value != 0 &&
                event_value != 1) {
                fprintf(
                    stderr,
                    "Invalid key value for event %d: %d\n",
                    event_index,
                    event_value
                );
                valid = 0;
                break;
            }

            values[i] = event_value;
        }

        if (!valid) {
            continue;
        }

        for (size_t i = 0; i < EVENT_COUNT; ++i) {
            int rc = libevdev_uinput_write_event(
                controller,
                REGISTERED_EVENTS[i].type,
                REGISTERED_EVENTS[i].code,
                values[i]
            );

            if (rc < 0) {
                fprintf(
                    stderr,
                    "Failed to write %s: %s\n",
                    REGISTERED_EVENTS[i].name,
                    strerror(-rc)
                );
            }
        }

        int rc = libevdev_uinput_write_event(
            controller,
            EV_SYN,
            SYN_REPORT,
            0
        );

        if (rc < 0) {
            fprintf(
                stderr,
                "Failed to write SYN_REPORT: %s\n",
                strerror(-rc)
            );
        }
    }

    close(sockfd);
}
```

