## Modified Zig client

Keep your `ControllerEvents` enum and controller-state array.

Add these constants:

```zig
const EVENT_COUNT: usize = @intFromEnum(ControllerEvents.START) + 1;
const PACKET_SIZE: usize = EVENT_COUNT * 4;
```

Replace `sendControllerState` with this:

```zig
fn sendControllerState(
    sock: posix.fd_t,
    addr: *const net.Address,
    controllerState: []const i16,
) !void {
    if (controllerState.len != EVENT_COUNT) {
        return error.InvalidControllerStateLength;
    }

    var packet: [PACKET_SIZE]u8 = undefined;

    for (controllerState, 0..) |value, index| {
        const offset = index * 4;

        // Each pair is:
        //
        // int16 event_index, little-endian
        // int16 event_value, little-endian
        std.mem.writeInt(
            i16,
            packet[offset..][0..2],
            @intCast(index),
            .little,
        );

        std.mem.writeInt(
            i16,
            packet[offset + 2 ..][0..2],
            value,
            .little,
        );
    }

    const sent = try posix.sendto(
        sock,
        packet[0..],
        0,
        &addr.any,
        addr.getOsSockLen(),
    );

    if (sent != packet.len) {
        return error.IncompleteDatagramSend;
    }
}
```

In `main`, parse the address once outside the loop and send the state slice:

```zig
pub fn main() anyerror!void {
    const screenWidth = 800;
    const screenHeight = 450;

    rl.initWindow(
        screenWidth,
        screenHeight,
        "raylib-zig example - keyboard to controller input",
    );
    defer rl.closeWindow();

    rl.setTargetFPS(60);

    var controllerState = initializeControllerState();

    const sock = try posix.socket(posix.AF.INET, posix.SOCK.DGRAM, 0);
    defer posix.close(sock);

    const addr = try net.Address.parseIp4("127.0.0.1", 31415);

    while (!rl.windowShouldClose()) {
        controllerState[@intFromEnum(ControllerEvents.UP)] =
            if (rl.isKeyDown(rl.KeyboardKey.key_up)) 1 else 0;

        controllerState[@intFromEnum(ControllerEvents.DOWN)] =
            if (rl.isKeyDown(rl.KeyboardKey.key_down)) 1 else 0;

        controllerState[@intFromEnum(ControllerEvents.LEFT)] =
            if (rl.isKeyDown(rl.KeyboardKey.key_left)) 1 else 0;

        controllerState[@intFromEnum(ControllerEvents.RIGHT)] =
            if (rl.isKeyDown(rl.KeyboardKey.key_right)) 1 else 0;

        try sendControllerState(sock, &addr, controllerState[0..]);

        rl.beginDrawing();
        rl.clearBackground(rl.Color.white);
        rl.drawText(
            "Press arrow keys to simulate controller input!",
            190,
            200,
            20,
            rl.Color.light_gray,
        );
        rl.endDrawing();
    }
}
```

Also remove `createUDPServer` from the client. The client should not bind the server’s port.

