}

static struct libevdev_uinput *controller_create(void) {
    struct libevdev *device = libevdev_new();
    libevdev_set_name(device, "Virtual Game Controller");

    struct input_absinfo absinfo = {
        .value = 0,
        .minimum = -32768,
        .maximum = 32767,
        .flat = 0,
        .fuzz = 0,
        .resolution = 0,
    };

    for (size_t i = 0; i < EVENT_COUNT; ++i) {
        libevdev_enable_event_code(
            device,
            REGISTERED_EVENTS[i].type,
            REGISTERED_EVENTS[i].code,
            (REGISTERED_EVENTS[i].type == EV_ABS) ? &absinfo : NULL
        );
    }

    struct libevdev_uinput *ui;
    if (libevdev_uinput_create_from_device(device, LIBEVDEV_UINPUT_OPEN_MANAGED, &ui) < 0) {
        fprintf(stderr, "Failed to create uinput device\n");
        exit(EXIT_FAILURE);
    }

    libevdev_free(device);
    return ui;
}

static void udp_server(void) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    serv_addr.sin_port = htons(PORT);

    if (bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("bind");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    /*
     * One extra byte lets us reject oversized UDP packets.
     * Expected packet size is exactly PACKET_SIZE.
     */
    uint8_t buffer[PACKET_SIZE + 1];

    for (;;) {
        ssize_t n = recvfrom(sockfd, buffer, sizeof(buffer), 0, NULL, NULL);

        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }

            perror("recvfrom");
            break;
        }

        if ((size_t)n != PACKET_SIZE) {
            fprintf(
                stderr,
                "Invalid packet size: %zd (expected %zu)\n",
                n,
                PACKET_SIZE
            );
            continue;
        }

        int values[EVENT_COUNT];
        int valid = 1;

        /*
         * Validate the whole packet before emitting events.
         *
         * This format is a full controller-state snapshot:
         * pair 0 must be event index 0,
         * pair 1 must be event index 1,
         * ...
         * pair 17 must be event index 17.
         */
        for (size_t i = 0; i < EVENT_COUNT; ++i) {
            const uint8_t *p = buffer + i * PAIR_SIZE;

            int event_index = read_i16_le(p);
            int event_value = read_i16_le(p + 2);

            if (event_index != (int)i) {
                valid = 0;
                break;
            }

            /*
             * Your server registers D-pad/buttons as EV_KEY, so values
             * should be 0 or 1.
             */
            if (REGISTERED_EVENTS[i].type == EV_KEY &&
                event_value != 0 && event_value != 1) {
                valid = 0;
                break;
            }

            values[i] = event_value;
        }

        if (!valid) {
            fprintf(stderr, "Invalid controller packet\n");
            continue;
        }

        for (size_t i = 0; i < EVENT_COUNT; ++i) {
            int rc = libevdev_uinput_write_event(
                controller,
                REGISTERED_EVENTS[i].type,
                REGISTERED_EVENTS[i].code,
                values[i]
            );

            if (rc < 0) {
                fprintf(
                    stderr,
                    "Failed to write %s: %s\n",
                    REGISTERED_EVENTS[i].name,
                    strerror(-rc)
                );
            }
        }

        int rc = libevdev_uinput_write_event(controller, EV_SYN, SYN_REPORT, 0);
        if (rc < 0) {
            fprintf(stderr, "Failed to write SYN_REPORT: %s\n", strerror(-rc));
        }
    }

    close(sockfd);
}

int main(void) {
    controller = controller_create();
    udp_server();
    libevdev_uinput_destroy(controller);
    return 0;
}
