## Modified Zig client

```zig
const std = @import("std");
const rl = @import("raylib");
const net = std.net;
const posix = std.posix;
const mem = std.mem;

const PORT = 31415;

const ControllerEvents = enum(i16) {
    ANALOG_LX = 0,
    ANALOG_LY = 1,
    ANALOG_RX = 2,
    ANALOG_RY = 3,

    L1 = 4,
    L2 = 5,
    R1 = 6,
    R2 = 7,

    TRIANGLE = 8,
    CROSS = 9,
    SQUARE = 10,
    CIRCLE = 11,

    UP = 12,
    DOWN = 13,
    LEFT = 14,
    RIGHT = 15,

    SELECT = 16,
    START = 17,
};

fn eventIndex(comptime e: ControllerEvents) usize {
    return @as(usize, @intCast(@intFromEnum(e)));
}

const EVENT_COUNT: usize = eventIndex(.START) + 1;
const PACKET_SIZE: usize = EVENT_COUNT * 4;

fn sendControllerState(
    sock: posix.fd_t,
    addr: *const net.Address,
    controllerState: []const i16,
) !void {
    if (controllerState.len != EVENT_COUNT) {
        return error.ControllerStateWrongSize;
    }

    var packet: [PACKET_SIZE]u8 = undefined;

    for (controllerState, 0..) |value, index| {
        const offset = index * 4;

        // Wire format:
        // int16 event index, little-endian
        // int16 event value, little-endian
        mem.writeInt(
            i16,
            packet[offset..],
            @as(i16, @intCast(index)),
            .little,
        );

        mem.writeInt(
            i16,
            packet[offset + 2 ..],
            value,
            .little,
        );
    }

    const sent = try posix.sendto(
        sock,
        &packet,
        0,
        &addr.any,
        addr.getOsSockLen(),
    );

    if (sent != packet.len) {
        return error.ShortUdpSend;
    }
}

pub fn main() anyerror!void {
    const screenWidth = 800;
    const screenHeight = 450;

    rl.initWindow(
        screenWidth,
        screenHeight,
        "raylib-zig example - keyboard to controller input",
    );
    defer rl.closeWindow();

    rl.setTargetFPS(60);

    var controllerState: [EVENT_COUNT]i16 = undefined;
    @memset(controllerState[0..], 0);

    const sock = try posix.socket(posix.AF.INET, posix.SOCK.DGRAM, 0);
    defer posix.close(sock);

    const addr = try net.Address.parseIp4("127.0.0.1", PORT);

    while (!rl.windowShouldClose()) {
        controllerState[eventIndex(.UP)] =
            if (rl.isKeyDown(rl.KeyboardKey.key_up)) 1 else 0;

        controllerState[eventIndex(.DOWN)] =
            if (rl.isKeyDown(rl.KeyboardKey.key_down)) 1 else 0;

        controllerState[eventIndex(.LEFT)] =
            if (rl.isKeyDown(rl.KeyboardKey.key_left)) 1 else 0;

        controllerState[eventIndex(.RIGHT)] =
            if (rl.isKeyDown(rl.KeyboardKey.key_right)) 1 else 0;

        try sendControllerState(sock, &addr, &controllerState);

        rl.beginDrawing();
        rl.clearBackground(rl.Color.white);
        rl.drawText(
            "Press arrow keys to simulate controller input!",
            190,
            200,
            20,
            rl.Color.light_gray,
        );
        rl.endDrawing();
    }
}
