## 2. Recording service

Create `AudioRecordingService.swift`.

```swift
import AVFoundation
import Foundation

enum RecordingEvent {
    case interrupted
    case failed(String)
}

enum AudioRecordingError: LocalizedError {
    case microphonePermissionDenied
    case alreadyRecording
    case unableToStart
    case noActiveRecording
    case emptyRecording

    var errorDescription: String? {
        switch self {
        case .microphonePermissionDenied:
            return "Microphone access is disabled. Enable it in Settings → Privacy & Security → Microphone."
        case .alreadyRecording:
            return "A recording is already in progress."
        case .unableToStart:
            return "The audio recorder could not start."
        case .noActiveRecording:
            return "There is no active recording."
        case .emptyRecording:
            return "The recording did not contain any audio."
        }
    }
}

@MainActor
protocol AudioRecordingService: AnyObject {
    var onEvent: ((RecordingEvent) -> Void)? { get set }
    var elapsedTime: TimeInterval { get }

    func start() async throws
    func stop() throws -> URL
    func cancel()
    func currentLevel() -> Float
}

@MainActor
final class AudioRecorderService: NSObject, AudioRecordingService {
    var onEvent: ((RecordingEvent) -> Void)?

    private var recorder: AVAudioRecorder?
    private var activeURL: URL?
    private var interruptionObserver: NSObjectProtocol?
    private let fileManager = FileManager.default

    var elapsedTime: TimeInterval {
        recorder?.currentTime ?? 0
    }

    func start() async throws {
        guard recorder == nil else {
            throw AudioRecordingError.alreadyRecording
        }

        let granted = await requestMicrophonePermission()
        try Task.checkCancellation()

        guard granted else {
            throw AudioRecordingError.microphonePermissionDenied
        }

        guard recorder == nil else {
            throw AudioRecordingError.alreadyRecording
        }

        let session = AVAudioSession.sharedInstance()

        do {
            try session.setCategory(.record, mode: .default)
            try session.setActive(true)

            let url = try makeRecordingURL()
            activeURL = url

            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44_100.0,
                AVNumberOfChannelsKey: 1,
                AVEncoderBitRateKey: 128_000,
                AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
            ]

            let newRecorder = try AVAudioRecorder(url: url, settings: settings)
            newRecorder.delegate = self
            newRecorder.isMeteringEnabled = true

            recorder = newRecorder
            observeInterruptions()

            guard newRecorder.prepareToRecord(), newRecorder.record() else {
                throw AudioRecordingError.unableToStart
            }
        } catch {
            cancel()
            throw error
        }
    }

    func stop() throws -> URL {
        guard let finishedRecorder = recorder, let url = activeURL else {
            throw AudioRecordingError.noActiveRecording
        }

        let duration = finishedRecorder.currentTime

        recorder = nil
        activeURL = nil
        finishedRecorder.delegate = nil
        finishedRecorder.stop()

        removeInterruptionObserver()
        deactivateAudioSession()

        guard duration > 0, fileManager.fileExists(atPath: url.path) else {
            try? fileManager.removeItem(at: url)
            throw AudioRecordingError.emptyRecording
        }

        return url
    }

    func cancel() {
        let currentRecorder = recorder
        let currentURL = activeURL

        recorder = nil
        activeURL = nil

        currentRecorder?.delegate = nil
        currentRecorder?.stop()

        removeInterruptionObserver()
        deactivateAudioSession()

        if let currentURL {
            try? fileManager.removeItem(at: currentURL)
        }
    }

    func currentLevel() -> Float {
        guard let recorder, recorder.isRecording else {
            return 0
        }

        recorder.updateMeters()

        let decibels = recorder.averagePower(forChannel: 0)
        guard decibels.isFinite else { return 0 }

        // Map roughly -60 dB...0 dB to 0...1 for UI purposes.
        let floor: Float = -60
        let normalized = (decibels - floor) / -floor

        return min(max(normalized, 0), 1)
    }

    private func requestMicrophonePermission() async -> Bool {
        if #available(iOS 17.0, *) {
            return await AVAudioApplication.requestRecordPermission()
        } else {
            return await withCheckedContinuation { continuation in
                AVAudioSession.sharedInstance().requestRecordPermission { granted in
                    continuation.resume(returning: granted)
                }
            }
        }
    }

    private func makeRecordingURL() throws -> URL {
        let documents = try fileManager.url(
            for: .documentDirectory,
            in: .userDomainMask,
            appropriateFor: nil,
            create: true
        )

        let recordingsDirectory = documents.appendingPathComponent(
            "Recordings",
            isDirectory: true
        )

        try fileManager.createDirectory(
            at: recordingsDirectory,
            withIntermediateDirectories: true
        )

        return recordingsDirectory.appendingPathComponent("\(UUID().uuidString).m4a")
    }

    private func observeInterruptions() {
        removeInterruptionObserver()

        let session = AVAudioSession.sharedInstance()

        interruptionObserver = NotificationCenter.default.addObserver(
            forName: AVAudioSession.interruptionNotification,
            object: session,
            queue: .main
        ) { [weak self] notification in
            guard
                let rawValue = notification.userInfo?[
                    AVAudioSessionInterruptionTypeKey
                ] as? UInt,
                let type = AVAudioSession.InterruptionType(rawValue: rawValue),
                type == .began
            else {
                return
            }

            Task { @MainActor [weak self] in
                self?.onEvent?(.interrupted)
            }
        }
    }

    private func removeInterruptionObserver() {
        if let interruptionObserver {
            NotificationCenter.default.removeObserver(interruptionObserver)
            self.interruptionObserver = nil
        }
    }

    private func deactivateAudioSession() {
        try? AVAudioSession.sharedInstance().setActive(
            false,
            options: .notifyOthersOnDeactivation
        )
    }

    private func reportUnexpectedFailure(
        recorderID: ObjectIdentifier,
        message: String
    ) {
        guard
            let currentRecorder = recorder,
            ObjectIdentifier(currentRecorder) == recorderID
        else {
            return
        }

        cancel()
        onEvent?(.failed(message))
    }
}

extension AudioRecorderService: AVAudioRecorderDelegate {
    nonisolated func audioRecorderEncodeErrorDidOccur(
        _ recorder: AVAudioRecorder,
        error: (any Error)?
    ) {
        let recorderID = ObjectIdentifier(recorder)
        let message = error?.localizedDescription ?? "An audio encoding error occurred."

        Task { @MainActor [weak self] in
            self?.reportUnexpectedFailure(recorderID: recorderID, message: message)
        }
    }

    nonisolated func audioRecorderDidFinishRecording(
        _ recorder: AVAudioRecorder,
        successfully flag: Bool
    ) {
        let recorderID = ObjectIdentifier(recorder)
        let message = flag
            ? "Recording ended unexpectedly."
            : "The audio recorder could not finish recording."

        Task { @MainActor [weak self] in
            self?.reportUnexpectedFailure(recorderID: recorderID, message: message)
        }
    }
}
```

