## 3. View model

Create `VoiceRecorderViewModel.swift`.

```swift
import SwiftUI

@MainActor
final class VoiceRecorderViewModel: ObservableObject {
    enum State: Equatable {
        case idle
        case preparing
        case recording
        case saved
        case failed
    }

    @Published private(set) var state: State = .idle
    @Published private(set) var levels: [Float] = Array(repeating: 0, count: 28)
    @Published private(set) var elapsedTime: TimeInterval = 0
    @Published private(set) var savedURL: URL?
    @Published private(set) var errorMessage: String?
    @Published private(set) var infoMessage: String?

    private let recordingService: any AudioRecordingService

    private var startTask: Task<Void, Never>?
    private var meteringTask: Task<Void, Never>?

    init(recordingService: any AudioRecordingService) {
        self.recordingService = recordingService

        recordingService.onEvent = { [weak self] event in
            Task { @MainActor in
                self?.handle(event)
            }
        }
    }

    var canStart: Bool {
        state != .preparing && state != .recording
    }

    var canStop: Bool {
        state == .recording
    }

    var statusText: String {
        switch state {
        case .idle:
            return "Ready to record"
        case .preparing:
            return "Preparing microphone…"
        case .recording:
            return "Recording"
        case .saved:
            return "Recording saved"
        case .failed:
            return "Recording unavailable"
        }
    }

    var formattedElapsedTime: String {
        let seconds = Int(elapsedTime)
        return String(format: "%02d:%02d", seconds / 60, seconds % 60)
    }

    func startRecording() {
        guard canStart else { return }

        state = .preparing
        errorMessage = nil
        infoMessage = nil
        savedURL = nil
        elapsedTime = 0
        levels = Array(repeating: 0, count: levels.count)

        startTask = Task { @MainActor [weak self] in
            guard let self else { return }
            defer { self.startTask = nil }

            do {
                try await self.recordingService.start()

                guard !Task.isCancelled else {
                    self.recordingService.cancel()
                    self.state = .idle
                    return
                }

                self.state = .recording
                self.startMetering()
            } catch {
                guard !Task.isCancelled else { return }

                self.errorMessage = error.localizedDescription
                self.state = .failed
            }
        }
    }

    func stopRecording() {
        finishRecording()
    }

    /// Call this when the screen disappears.
    /// Active recordings are saved; pending start operations are cancelled.
    func screenDidDisappear() {
        startTask?.cancel()
        startTask = nil

        if state == .recording {
            finishRecording()
        } else {
            stopMetering()
            recordingService.cancel()

            if state == .preparing {
                state = .idle
            }
        }
    }

    private func finishRecording(info: String? = nil) {
        guard state == .recording else { return }

        stopMetering()
        elapsedTime = recordingService.elapsedTime

        do {
            savedURL = try recordingService.stop()
            infoMessage = info
            state = .saved
        } catch {
            recordingService.cancel()
            errorMessage = error.localizedDescription
            state = .failed
        }
    }

    private func startMetering() {
        stopMetering()

        meteringTask = Task { @MainActor [weak self] in
            while !Task.isCancelled {
                self?.sampleMeter()

                try? await Task.sleep(nanoseconds: 50_000_000) // 20 fps
            }
        }
    }

    private func stopMetering() {
        meteringTask?.cancel()
        meteringTask = nil
    }

    private func sampleMeter() {
        guard state == .recording else { return }

        levels.removeFirst()
        levels.append(recordingService.currentLevel())
        elapsedTime = recordingService.elapsedTime
    }

    private func handle(_ event: RecordingEvent) {
        switch event {
        case .interrupted:
            finishRecording(
                info: "Recording was interrupted. The captured audio was saved."
            )

        case .failed(let message):
            stopMetering()
            errorMessage = message
            state = .failed
        }
    }
}
