### 3. View model

Create `VoiceRecorderViewModel.swift`:

```swift
import Foundation

@MainActor
final class VoiceRecorderViewModel: ObservableObject {
    enum Phase: Equatable {
        case idle
        case starting
        case recording
        case saved
        case failed
    }

    @Published private(set) var phase: Phase = .idle
    @Published private(set) var levels: [Float] = Array(repeating: 0, count: 32)
    @Published private(set) var elapsedTime: TimeInterval = 0
    @Published private(set) var savedURL: URL?
    @Published private(set) var errorMessage: String?

    private let service: any AudioRecordingService
    private var startTask: Task<Void, Never>?
    private var meterTask: Task<Void, Never>?

    init(service: any AudioRecordingService) {
        self.service = service

        service.onEvent = { [weak self] event in
            self?.handle(event)
        }
    }

    var canStart: Bool {
        phase != .starting && phase != .recording
    }

    var canStop: Bool {
        phase == .recording
    }

    var statusText: String {
        switch phase {
        case .idle:
            return "Ready"
        case .starting:
            return "Preparing…"
        case .recording:
            return "Recording"
        case .saved:
            return "Saved"
        case .failed:
            return "Failed"
        }
    }

    var timeText: String {
        let totalSeconds = max(0, Int(elapsedTime))
        return String(
            format: "%02d:%02d",
            totalSeconds / 60,
            totalSeconds % 60
        )
    }

    func startRecording() {
        guard canStart else { return }

        errorMessage = nil
        savedURL = nil
        elapsedTime = 0
        levels = Array(repeating: 0, count: levels.count)
        phase = .starting

        startTask = Task { @MainActor [weak self] in
            guard let self else { return }

            do {
                try await service.start()

                guard !Task.isCancelled else {
                    service.cancel()
                    return
                }

                phase = .recording
                startMetering()
            } catch is CancellationError {
                guard !Task.isCancelled else { return }
                phase = .idle
            } catch {
                guard !Task.isCancelled else { return }
                errorMessage = error.localizedDescription
                phase = .failed
            }

            startTask = nil
        }
    }

    func stopRecording() {
        finishRecording()
    }

    func clearError() {
        errorMessage = nil
    }

    func handleDisappear() {
        startTask?.cancel()
        startTask = nil

        if phase == .recording {
            finishRecording()
        } else {
            stopMetering()
            service.cancel()

            if phase == .starting {
                phase = .idle
            }
        }
    }

    private func finishRecording() {
        guard phase == .recording else { return }

        stopMetering()
        elapsedTime = service.elapsedTime

        do {
            savedURL = try service.stop()
            phase = .saved
        } catch {
            service.cancel()
            errorMessage = error.localizedDescription
            phase = .failed
        }
    }

    private func startMetering() {
        stopMetering()

        meterTask = Task { @MainActor [weak self] in
            while !Task.isCancelled {
                guard let self else { return }

                self.sampleMeter()

                do {
                    try await Task.sleep(nanoseconds: 50_000_000)
                } catch {
                    return
                }
            }
        }
    }

    private func stopMetering() {
        meterTask?.cancel()
        meterTask = nil
    }

    private func sampleMeter() {
        guard phase == .recording else { return }

        elapsedTime = service.elapsedTime

        levels.removeFirst()
        levels.append(service.currentLevel())
    }

    private func handle(_ event: AudioRecorderEvent) {
        switch event {
        case .interrupted:
            finishRecording()

        case .failed(let message):
            stopMetering()
            errorMessage = message
            phase = .failed
        }
    }
}
```

