// e2e/users/playwright-user-gateway.ts
import type { APIRequestContext, APIResponse } from '@playwright/test';
import type { UserGateway } from './user-gateway';
import type { CreateUserPayload, CreateUserResponse, UpdatePermissionsPayload, UserCredentials, UserId } from './types';

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function isCreateUserResponse(value: unknown): value is CreateUserResponse {
  return isRecord(value) && typeof value.id === 'string' && value.id.length > 0;
}

function isUserCredentials(value: unknown): value is UserCredentials {
  return isRecord(value) && typeof value.username === 'string' && typeof value.password === 'string';
}

export class PlaywrightUserGateway implements UserGateway {
  constructor(private readonly request: APIRequestContext) {}

  async createUser(payload: CreateUserPayload): Promise<CreateUserResponse> {
    const response = await this.request.post('/users/v2/create', { data: payload });
    await this.ensureStatus(response, [201], 'createUser');
    const body: unknown = await response.json();
    if (!isCreateUserResponse(body)) {
      throw new Error('createUser returned an invalid response: expected { id: string }');
    }
    return body;
  }

  async updatePermissions(userId: UserId, payload: UpdatePermissionsPayload): Promise<UserCredentials> {
    const response = await this.request.post('/users/v2/permissions', {
      data: { ...payload, id: userId },
    });
    await this.ensureStatus(response, [200], 'updatePermissions');
    const body: unknown = await response.json();
    if (!isUserCredentials(body)) {
      throw new Error('updatePermissions returned an invalid response: expected { username, password }');
    }
    return body;
  }

  async deleteUser(userId: UserId): Promise<void> {
    const response = await this.request.delete(`/users/v2/${encodeURIComponent(userId)}`);
    await this.ensureStatus(response, [200, 204, 404], 'deleteUser');
  }

  private async ensureStatus(response: APIResponse, expectedStatuses: number[], operation: string): Promise<void> {
    if (expectedStatuses.includes(response.status())) return;
    let details = '';
    try {
      details = await response.text();
    } catch {
      // ignore body read failures
    }
    throw new Error(
      `${operation} failed. Expected status ${expectedStatuses.join(' or ')}, received ${response.status()}.` +
        (details ? ` Response: ${details}` : ''),
    );
  }
}
```
