    const userApi = new PlaywrightUserApiAdapter(request);
    const userProvisioner = new UserProvisioningService(userApi);

    try {
      await use(userProvisioner);
    } finally {
      await userProvisioner.cleanup();
    }
  },
});

export { expect };
```

---

### 6. Keep UI interactions in a Page Object

```typescript
// e2e/pages/login.page.ts

import type { Page } from "@playwright/test";

export class LoginPage {
  constructor(private readonly page: Page) {}

  async goto(): Promise<void> {
    await this.page.goto("/login");
  }

  async login(username: string, password: string): Promise<void> {
