import { LoginPage } from "../pages/login.page";
import { buildCreateAdminUserPayload } from "../support/test-data.factory";

test("create admin user and login", async ({ page, userProvisioner }) => {
  const createPayload = buildCreateAdminUserPayload();

  const adminUser = await userProvisioner.createAdminUser(createPayload);

  const loginPage = new LoginPage(page);

  await loginPage.goto();
  await loginPage.login(adminUser.username, adminUser.password);

  // Assert the real user-visible outcome, not only that login was attempted.
  await expect(page).toHaveURL(/dashboard/);
