import { defineStore } from 'pinia'
import { ref } from 'vue'

export const useRowsStore = defineStore('rows', () => {
  const rows = ref([])
  const loading = ref(false)
  const error = ref(null)
  const hasMore = ref(true)
  const pageSize = 50

  async function fetchNextPage() {
    if (loading.value || !hasMore.value) return false
    loading.value = true
    error.value = null
    try {
      const start = rows.value.length
      const url = new URL('/api/rows', window.location.origin) // or relative
      url.search = new URLSearchParams({ start, count: pageSize })
      const res = await fetch(url)
      if (!res.ok) throw new Error(`Request failed ${res.status}`)
      const payload = await res.json()
      const newRows = payload.items ?? payload.rows ?? payload.data
      if (!Array.isArray(newRows)) throw new Error('Expected array')
      rows.value.push(...newRows)
      if (typeof payload.total === 'number') hasMore.value = rows.value.length < payload.total
      else hasMore.value = newRows.length === pageSize
      if (newRows.length === 0) hasMore.value = false
      return newRows.length > 0
    } catch (e) {
      error.value = e.message
      return false
    } finally { loading.value = false }
  }

  function $reset() { rows.value=[]; hasMore.value=true; error.value=null }
  return { rows, loading, error, hasMore, pageSize, fetchNextPage, $reset }
})
```
