<script setup>
import { onBeforeUnmount, onMounted, ref, nextTick } from 'vue'
import { useRowsStore } from '../stores/rows'

const store = useRowsStore()
const scroller = ref(null)
const threshold = 120
let filling = false
let resizeObserver

function isNearBottom() {
  const el = scroller.value
  if (!el) return false
  return el.scrollHeight - el.scrollTop - el.clientHeight <= threshold
}

async function maintainRows() {
  if (filling || store.error) return
  filling = true
  try {
    await nextTick()
    while (!store.error && store.hasMore && isNearBottom()) {
      const added = await store.loadNextPage()
      if (!added) break
      await nextTick()
    }
  } finally {
    filling = false
  }
}

function retry() {
  store.error = null
  maintainRows()
}

onMounted(() => {
  resizeObserver = new ResizeObserver(() => maintainRows())
  if (scroller.value) resizeObserver.observe(scroller.value)
  maintainRows()
})

onBeforeUnmount(() => {
  resizeObserver?.disconnect()
})
</script>

