### 1. Pinia store

```js
// src/stores/rows.js
import { defineStore } from 'pinia'

export const useRowsStore = defineStore('rows', {
  state: () => ({
    rows: [],
    loading: false,
    error: null,
    hasMore: true,
    total: null,
    pageSize: 50,
  }),

  actions: {
    async loadNextPage() {
      if (this.loading || !this.hasMore) {
        return false
      }

      this.loading = true
      this.error = null

      try {
        const start = this.rows.length
        const count = this.pageSize

        const response = await fetch(`/api/rows?start=${start}&count=${count}`)

        if (!response.ok) {
          throw new Error(`Request failed with status ${response.status}`)
        }

        const data = await response.json()

        // Adjust this if your API returns `data.rows` instead of `data.items`.
        const items = data.items

        if (!Array.isArray(items)) {
          throw new Error('Invalid API response: expected an array of rows')
        }

        this.rows.push(...items)

        if (typeof data.total === 'number') {
          this.total = data.total
          this.hasMore = this.rows.length < this.total
        } else {
          // If the API does not return a total, assume we are done
          // when a page returns fewer rows than requested.
          this.hasMore = items.length === this.pageSize
        }

        if (items.length === 0) {
          this.hasMore = false
        }

        return true
      } catch (err) {
        this.error = err.message || 'Failed to load rows'
        return false
      } finally {
        this.loading = false
      }
    },

    clearError() {
      this.error = null
    },
  },
})
```

