<script setup>
import { ref, nextTick, onMounted, onBeforeUnmount } from 'vue'
import { useRowsStore } from '../stores/rows'

const store = useRowsStore()

const scrollContainer = ref(null)

// Start loading before the user reaches the exact bottom.
const bottomThreshold = 150

let filling = false
let resizeObserver = null

function isNearBottom() {
  const el = scrollContainer.value

  if (!el) {
    return false
  }

  const remaining = el.scrollHeight - el.scrollTop - el.clientHeight

  return remaining <= bottomThreshold
}

async function fillAvailableSpace() {
  if (filling || store.error) {
    return
  }

  filling = true

  try {
    // Wait for currently rendered rows before measuring.
    await nextTick()

    // Keep loading while:
    // 1. there are more rows,
    // 2. there is no error,
    // 3. the visible area is still not filled enough to scroll away from.
    while (!store.error && store.hasMore && isNearBottom()) {
      const loaded = await store.loadNextPage()

      if (!loaded) {
        break
      }

      // Wait for the newly added rows to render before measuring again.
      await nextTick()
    }
  } finally {
    filling = false
  }
}

function retry() {
  store.clearError()
  fillAvailableSpace()
}

onMounted(() => {
  resizeObserver = new ResizeObserver(() => {
    fillAvailableSpace()
  })

  if (scrollContainer.value) {
    resizeObserver.observe(scrollContainer.value)
  }

  fillAvailableSpace()
})

onBeforeUnmount(() => {
  resizeObserver?.disconnect()
})
</script>

