## 8. Add the guided process JavaScript

`wwwroot/js/guided-registration.js`

```js
(() => {
    const form = document.getElementById("registrationForm");
    const guideTitle = document.getElementById("guideTitle");
    const guideInstruction = document.getElementById("guideInstruction");
    const progress = document.getElementById("progress");
    const errorBox = document.getElementById("error");
    const backButton = document.getElementById("backButton");
    const nextButton = document.getElementById("nextButton");
    const result = document.getElementById("result");
    const backdrop = document.getElementById("backdrop");
    const guide = document.getElementById("guide");

    const steps = Array.from(document.querySelectorAll(".step")).map(container => {
        return {
            container,
            input: container.querySelector("input"),
            title: container.dataset.title,
            instruction: container.dataset.instruction,
            serverKey: container.dataset.serverKey
        };
    });

    let currentIndex = 0;
    let submitting = false;

    function showStep(index) {
        currentIndex = index;
        errorBox.textContent = "";

        steps.forEach((step, stepIndex) => {
            const active = stepIndex === currentIndex;

            step.container.disabled = !active;
            step.container.inert = !active;
            step.container.classList.toggle("active", active);
        });

        const current = steps[currentIndex];

        progress.textContent = `Step ${currentIndex + 1} of ${steps.length}`;
        guideTitle.textContent = current.title;
        guideInstruction.textContent = current.instruction;

        backButton.disabled = submitting || currentIndex === 0;
        nextButton.disabled = submitting;
        nextButton.textContent = submitting
            ? "Creating account..."
            : currentIndex === steps.length - 1
                ? "Create account"
                : "Next";

        current.container.scrollIntoView({
            behavior: "auto",
            block: "center"
        });

        current.input.focus({ preventScroll: true });
    }

    function validateCurrentStep() {
        const current = steps[currentIndex];
        const input = current.input;

        input.setCustomValidity("");

        if (input.id === "fullName") {
            input.value = input.value.trim();

            if (input.value.length < 2) {
                input.setCustomValidity("Enter at least 2 characters.");
            }
        }

        if (input.id === "confirmPassword") {
            const password = document.getElementById("password").value;

            if (input.value !== password) {
                input.setCustomValidity("Passwords do not match.");
            }
        }

        if (!input.checkValidity()) {
            errorBox.textContent = input.validationMessage;
            input.reportValidity();
            return false;
        }

        return true;
    }

    function collectFormData() {
        const previousStates = steps.map(step => step.container.disabled);

        try {
            steps.forEach(step => {
                step.container.disabled = false;
            });

            return new FormData(form);
        } finally {
            steps.forEach((step, index) => {
                step.container.disabled = previousStates[index];
            });
        }
    }

    function showServerErrors(errors) {
        if (!errors) {
            errorBox.textContent = "Please check your information and try again.";
            return;
        }

        const invalidStepIndex = steps.findIndex(step =>
            errors[step.serverKey] && errors[step.serverKey].length > 0);

        if (invalidStepIndex >= 0) {
            showStep(invalidStepIndex);
        }

        errorBox.textContent = Object.values(errors).flat().join(" ");
    }

    function showSuccess(message) {
        form.reset();
        form.hidden = true;
        guide.hidden = true;
        backdrop.hidden = true;

        result.textContent = message;
        result.hidden = false;
        result.focus();
    }

    async function submitRegistration() {
        submitting = true;
        showStep(currentIndex);
        errorBox.textContent = "";

        try {
            const data = collectFormData();

            steps[currentIndex].container.disabled = true;

            const response = await fetch(form.action, {
                method: "POST",
                body: data,
                credentials: "same-origin",
                headers: {
                    "Accept": "application/json"
                }
            });

            const contentType = response.headers.get("content-type") || "";

            if (!contentType.includes("application/json")) {
                throw new Error("Unexpected server response.");
            }

            const body = await response.json();

            if (!response.ok || !body.success) {
                if (body.errors) {
                    showServerErrors(body.errors);
                    return;
                }

                throw new Error("Registration failed.");
            }

            showSuccess(body.message);
        } catch {
            errorBox.textContent =
                "We could not complete registration. Please try again.";
        } finally {
            submitting = false;

            if (!form.hidden) {
                steps[currentIndex].container.disabled = false;
                showStep(currentIndex);
            }
        }
    }

    form.addEventListener("submit", async event => {
        event.preventDefault();

        if (submitting || !validateCurrentStep()) {
            return;
        }

        if (currentIndex < steps.length - 1) {
            showStep(currentIndex + 1);
        } else {
            await submitRegistration();
        }
    });

    backButton.addEventListener("click", () => {
        if (!submitting && currentIndex > 0) {
            showStep(currentIndex - 1);
        }
    });

    steps.forEach(step => {
        step.input.addEventListener("input", () => {
            step.input.setCustomValidity("");
            errorBox.textContent = "";
        });
    });

    showStep(0);
})();
```

