## 4. JavaScript guided-process controller

The JavaScript defines the steps and controls the active step.

```javascript
(() => {
    const form = document.getElementById("registration-form");
    const backdrop = document.getElementById("backdrop");
    const guidePanel = document.getElementById("guide-panel");

    const progress = document.getElementById("step-progress");
    const title = document.getElementById("step-title");
    const instruction = document.getElementById("step-instruction");
    const error = document.getElementById("step-error");

    const backButton = document.getElementById("back-button");
    const nextButton = document.getElementById("next-button");

    const steps = [
        {
            containerId: "step-fullName",
            inputId: "fullName",
            serverField: "Input.FullName",
            title: "Enter your full name",
            instruction: "Enter your full name. It must be at least 2 characters."
        },
        {
            containerId: "step-email",
            inputId: "email",
            serverField: "Input.Email",
            title: "Enter your email",
            instruction: "Enter a valid email address, for example: user@example.com."
        },
        {
            containerId: "step-password",
            inputId: "password",
            serverField: "Input.Password",
            title: "Create a password",
            instruction: "Use at least 12 characters."
        },
        {
            containerId: "step-confirmPassword",
            inputId: "confirmPassword",
            serverField: "Input.ConfirmPassword",
            title: "Confirm your password",
            instruction: "Enter the same password again."
        }
    ].map(step => ({
        ...step,
        container: document.getElementById(step.containerId),
        input: document.getElementById(step.inputId)
    }));

    let currentStep = 0;

    function showStep(index) {
        currentStep = index;
        error.textContent = "";

        steps.forEach((step, i) => {
            const active = i === currentStep;

            step.container.disabled = !active;
            step.container.inert = !active;
            step.container.classList.toggle("active", active);
        });

        const step = steps[currentStep];

        progress.textContent = `Step ${currentStep + 1} of ${steps.length}`;
        title.textContent = step.title;
        instruction.textContent = step.instruction;

        backButton.disabled = currentStep === 0;

        nextButton.textContent =
            currentStep === steps.length - 1
                ? "Create account"
                : "Next";

        step.container.scrollIntoView({
            behavior: "smooth",
            block: "center"
        });

        step.input.focus({ preventScroll: true });
    }

    function validateCurrentStep() {
        const step = steps[currentStep];
        const input = step.input;

        input.setCustomValidity("");

        if (input.id === "fullName" && input.value.trim().length < 2) {
            input.setCustomValidity("Enter at least 2 characters.");
        }

        if (input.id === "confirmPassword") {
            const password = document.getElementById("password").value;

            if (input.value !== password) {
                input.setCustomValidity("Passwords do not match.");
            }
        }

        if (!input.checkValidity()) {
            error.textContent = input.validationMessage;
            input.reportValidity();
            return false;
        }

        return true;
    }

    function collectFormData() {
        const previousDisabledStates = steps.map(step => step.container.disabled);

        try {
            steps.forEach(step => {
                step.container.disabled = false;
            });

            return new FormData(form);
        } finally {
            steps.forEach((step, index) => {
                step.container.disabled = previousDisabledStates[index];
            });
        }
    }

    async function submitForm() {
        nextButton.disabled = true;
        backButton.disabled = true;
        error.textContent = "";

        try {
            const data = collectFormData();

            const response = await fetch(form.action, {
                method: "POST",
                body: data,
                credentials: "same-origin",
                headers: {
                    "Accept": "application/json"
                }
            });

            const body = await response.json();

            if (!response.ok || !body.success) {
                if (body.errors) {
                    const firstInvalidStep = steps.findIndex(step =>
                        body.errors[step.serverField]?.length > 0
                    );

                    if (firstInvalidStep >= 0) {
                        showStep(firstInvalidStep);
                    }

                    error.textContent =
                        Object.values(body.errors)
                            .flat()
                            .join(" ");
                } else {
                    error.textContent = "Registration failed. Please try again.";
                }

                return;
            }

            form.hidden = true;
            backdrop.hidden = true;
            guidePanel.hidden = true;

            alert(body.message || "Registration completed successfully.");
        } catch {
            error.textContent = "An unexpected error occurred. Please try again.";
        } finally {
            nextButton.disabled = false;
            backButton.disabled = currentStep === 0;
        }
    }

    form.addEventListener("submit", async event => {
        event.preventDefault();

        if (!validateCurrentStep()) {
            return;
        }

        if (currentStep < steps.length - 1) {
            showStep(currentStep + 1);
        } else {
            await submitForm();
        }
    });

    backButton.addEventListener("click", () => {
        if (currentStep > 0) {
            showStep(currentStep - 1);
        }
    });

    showStep(0);
})();
```

