<style>
:root{
  --bg:#111;--panel:#1b1b1b;--editor:#141414;--border:#333;--text:#eee;--muted:#999;
  --accent:#7aa2f7;--selection:rgba(122,162,247,.35);--keyword:#bb9af7;--string:#9ece6a;
  --number:#ff9e64;--comment:#565f89;--tag:#7dcfff
}
body[data-theme="light"]{
  --bg:#f7f7f7;--panel:#fff;--editor:#fff;--border:#ddd;--text:#222;--muted:#666;
  --accent:#2364d2;--selection:rgba(35,100,210,.25);--keyword:#7c4dff;--string:#186f3d;
  --number:#b45309;--comment:#6b7280;--tag:#0366d6
}
*{box-sizing:border-box}
html,body{height:100%;margin:0}
body{background:var(--bg);color:var(--text);font:14px/1.5 system-ui,sans-serif;display:flex;flex-direction:column}
[hidden]{display:none !important}
header,#tabs,#findbar,footer{background:var(--panel);border-bottom:1px solid var(--border)}
header{display:flex;gap:8px;align-items:center;padding:8px 10px;flex-wrap:wrap}
button,select,input{font:inherit;color:inherit;background:transparent;border:1px solid var(--border);border-radius:6px;padding:5px 8px}
button:hover{border-color:var(--accent)}
button.active{background:var(--accent);color:#fff;border-color:var(--accent)}
#tabs{display:flex;gap:4px;padding:6px 8px;overflow:auto}
.tab{white-space:nowrap;cursor:pointer}
.tab.active{border-color:var(--accent);color:var(--accent)}
.tab .close{margin-left:8px;opacity:.7}
#findbar{display:flex;gap:6px;padding:8px;align-items:center;flex-wrap:wrap}
main{flex:1;display:flex;min-height:0}
#editorPane{flex:1;display:flex;min-width:0}
#lineNumbers{width:56px;overflow:hidden;background:var(--panel);border-right:1px solid var(--border);color:var(--muted);text-align:right;user-select:none}
#lineNumbersInner{padding:12px 10px 12px 0;font:13px/1.5 ui-monospace,Menlo,Consolas,monospace}
#lineNumbersInner div{min-height:1.5em}
#editorWrapper{position:relative;flex:1;overflow:hidden;background:var(--editor)}
#highlight,#editor{
  position:absolute;inset:0;margin:0;padding:12px;
  font:13px/1.5 ui-monospace,Menlo,Consolas,monospace;tab-size:2;white-space:pre
}
#highlight{pointer-events:none;overflow:hidden;min-width:100%;width:max-content;color:var(--text)}
#editor{
  border:none;resize:none;background:transparent;color:transparent;
  -webkit-text-fill-color:transparent;caret-color:var(--text);overflow:auto;outline:none
}
#editor::selection{background:var(--selection)}
.wrap #highlight,.wrap #editor{white-space:pre-wrap;overflow-wrap:anywhere}
.wrap #highlight{width:100%}
#previewPane{width:40%;min-width:220px;border-left:1px solid var(--border);display:flex}
#previewPane iframe{border:0;width:100%;height:100%;background:#fff}
footer{display:flex;gap:12px;align-items:center;padding:5px 8px;font-size:12px;color:var(--muted);overflow:auto;white-space:nowrap}
footer .spacer{flex:1}
.tok-keyword{color:var(--keyword)}
.tok-string{color:var(--string)}
.tok-number{color:var(--number)}
.tok-comment{color:var(--comment);font-style:italic}
.tok-tag{color:var(--tag)}
.tok-attr{color:var(--accent)}
.tok-operator{color:var(--accent)}
@media(max-width:800px){#previewPane{display:none}}
</style>
</head>
<body data-theme="dark">
<header>
  <strong>Advanced Notepad</strong>
  <button id="newBtn">New</button>
  <button id="openBtn">Open</button>
  <button id="saveBtn">Save</button>
  <button id="exportBtn">Export All</button>
  <button id="undoBtn">Undo</button>
  <button id="redoBtn">Redo</button>
  <button id="findBtn">Find</button>
  <button id="previewBtn">Preview</button>
  <button id="wrapBtn">Wrap</button>
  <select id="themeSelect" aria-label="Theme">
    <option value="dark">Dark</option>
    <option value="light">Light</option>
  </select>
</header>

<div id="tabs" aria-label="Open documents"></div>

<div id="findbar" hidden aria-label="Find and replace">
  <input id="findInput" placeholder="Find" aria-label="Find">
  <input id="replaceInput" placeholder="Replace" aria-label="Replace">
  <button id="caseBtn" title="Match case">Aa</button>
  <button id="regexBtn" title="Regular expression">.*</button>
  <span id="matchCount"></span>
  <button id="prevBtn">Prev</button>
  <button id="nextBtn">Next</button>
  <button id="replaceBtn">Replace</button>
  <button id="replaceAllBtn">Replace All</button>
  <button id="closeFindBtn">Close</button>
</div>

<main>
  <div id="editorPane">
    <div id="lineNumbers" aria-hidden="true"><div id="lineNumbersInner"></div></div>
    <div id="editorWrapper">
      <pre id="highlight" aria-hidden="true"></pre>
      <textarea id="editor" spellcheck="false" autocapitalize="off" autocomplete="off" wrap="off" aria-label="Text editor"></textarea>
    </div>
  </div>

  <div id="previewPane" hidden>
    <iframe id="previewFrame" title="Preview" sandbox=""></iframe>
  </div>
</main>

<footer>
  <span id="saveStatus">Saved</span>
  <span class="spacer"></span>
  <span id="cursorStatus">Ln 1, Col 1</span>
  <span id="stats">0 chars</span>
  <select id="languageSelect" aria-label="Language">
    <option value="text">Plain Text</option>
    <option value="javascript">JavaScript</option>
    <option value="html">HTML</option>
    <option value="css">CSS</option>
    <option value="json">JSON</option>
    <option value="markdown">Markdown</option>
    <option value="python">Python</option>
  </select>
</footer>

<input type="file" id="fileInput" multiple hidden>

<script>
(() => {
  const $ = id => document.getElementById(id);
  const editor = $("editor");
  const highlight = $("highlight");
  const lineNumbersInner = $("lineNumbersInner");

  const STORAGE_KEY = "advanced-notepad-v1";
  const defaults = { theme: "dark", wrap: false, autosave: true, tabSize: 2 };

  let state = { docs: [], active: null, settings: { ...defaults } };
  let histories = new Map();
  let matches = [];
  let matchIndex = -1;
  let findOptions = { case: false, regex: false };
  let saveTimer;
  let previewTimer;

  const uid = () => globalThis.crypto?.randomUUID?.() || Date.now().toString(36) + Math.random().toString(36).slice(2);
  const escapeHtml = s => String(s).replace(/[&<>"']/g, c => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
  }[c]));
  const escapeRegExp = s => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

  const inferLanguage = name => {
    const ext = name.split(".").pop().toLowerCase();
    return ({
      js: "javascript",
      mjs: "javascript",
      html: "html",
      htm: "html",
      css: "css",
      json: "json",
      md: "markdown",
      py: "python"
    })[ext] || "text";
  };

  const makeDoc = (name, content = "", lang = inferLanguage(name)) => ({
    id: uid(),
    name,
    content,
    lang,
    cursor: 0,
    scroll: 0
  });

  const activeDoc = () => state.docs.find(d => d.id === state.active) || state.docs[0];

  const getHistory = id => {
    if (!histories.has(id)) histories.set(id, { undo: [], redo: [], lastValue: "" });
    return histories.get(id);
  };

  function loadState() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const saved = JSON.parse(raw);
        if (Array.isArray(saved.docs) && saved.docs.length) {
          state.docs = saved.docs
            .filter(d => d && typeof d.content === "string")
            .map(d => ({
              ...makeDoc(d.name || "untitled.txt", d.content, d.lang),
              id: d.id || uid(),
              cursor: d.cursor || 0,
              scroll: d.scroll || 0
            }));
          state.active = saved.docs.some(d => d.id === saved.active) ? saved.active : state.docs[0].id;
          state.settings = { ...defaults, ...saved.settings };
          return;
        }
      }
    } catch (e) {}

    state.docs = [makeDoc("welcome.js", [
      "// Advanced Notepad",
      "// Features: tabs, syntax highlighting, find/replace, autosave, preview, themes.",
      "const features = [\"tabs\", \"highlighting\", \"find\", \"autosave\"];",
      "function demo() {",
      "  return features.length;",
      "}",
      "demo();"
    ].join("\n"))];
    state.active = state.docs[0].id;
  }

  function persist() {
    try {
      const d = activeDoc();
      if (d) {
        d.cursor = editor.selectionStart;
        d.scroll = editor.scrollTop;
      }
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
      $("saveStatus").textContent = "Saved";
    } catch (e) {
      $("saveStatus").textContent = "Storage unavailable";
    }
  }

  function scheduleSave() {
    clearTimeout(saveTimer);
    $("saveStatus").textContent = "Saving...";
    saveTimer = setTimeout(persist, 300);
  }

  function renderTabs() {
    const tabs = $("tabs");
    tabs.innerHTML = "";

    for (const d of state.docs) {
      const b = document.createElement("button");
      b.className = "tab" + (d.id === state.active ? " active" : "");
      b.textContent = d.name;
      b.onclick = () => switchDoc(d.id);
      b.ondblclick = () => renameDoc(d.id);

      const x = document.createElement("span");
      x.className = "close";
      x.textContent = "×";
      x.onclick = e => {
        e.stopPropagation();
        closeDoc(d.id);
      };

      b.appendChild(x);
      tabs.appendChild(b);
    }

    const add = document.createElement("button");
    add.className = "tab";
    add.textContent = "+";
    add.onclick = newDoc;
    tabs.appendChild(add);

    if (activeDoc()) $("languageSelect").value = activeDoc().lang;
  }

  function switchDoc(id) {
    if (id === state.active) return;
    persist();
    state.active = id;
    renderTabs();
    loadActive();
    editor.focus();
  }

  function newDoc() {
    let n = 1;
    while (state.docs.some(d => d.name === `untitled-${n}.txt`)) n++;
    const doc = makeDoc(`untitled-${n}.txt`);
    state.docs.push(doc);
    state.active = doc.id;
    renderTabs();
    loadActive();
    editor.focus();
    scheduleSave();
  }

  function closeDoc(id) {
    const idx = state.docs.findIndex(d => d.id === id);
    if (idx < 0) return;

    if (state.docs[idx].content && !confirm(`Close ${state.docs[idx].name}?`)) return;

    state.docs.splice(idx, 1);
    if (!state.docs.length) state.docs.push(makeDoc("untitled.txt"));
    state.active = state.docs[Math.max(0, Math.min(idx, state.docs.length - 1))].id;

    renderTabs();
    loadActive();
    scheduleSave();
  }

  function renameDoc(id = state.active) {
    const d = state.docs.find(x => x.id === id);
    if (!d) return;
    const name = prompt("Document name", d.name);
    if (!name) return;
    d.name = name.trim();
    d.lang = inferLanguage(d.name);
    renderTabs();
    renderEditor();
    scheduleSave();
  }

  function loadActive() {
    const d = activeDoc();
    if (!d) return;

    editor.value = d.content;
    const pos = Math.min(d.cursor || 0, editor.value.length);
    editor.setSelectionRange(pos, pos);

    $("languageSelect").value = d.lang;
    getHistory(d.id).lastValue = editor.value;

    renderEditor();
    updatePreview();

    requestAnimationFrame(() => {
      editor.scrollTop = d.scroll || 0;
      syncScroll();
    });

    editor.focus();
  }

  function renderEditor() {
    highlight.innerHTML = highlightCode(editor.value, activeDoc().lang) + "\n";
    updateLineNumbers();
    updateStatus();
    syncScroll();
    updateUndoRedoButtons();
  }

  function updateLineNumbers() {
    const count = editor.value.split("\n").length;
    lineNumbersInner.innerHTML = Array.from({ length: count }, (_, i) => `<div>${i + 1}</div>`).join("");
  }

  function syncScroll() {
    highlight.style.transform = `translate(${-editor.scrollLeft}px, ${-editor.scrollTop}px)`;
    lineNumbersInner.style.transform = `translateY(${-editor.scrollTop}px)`;
  }

  function updateStatus() {
    const v = editor.value;
    const s = editor.selectionStart;
    const e = editor.selectionEnd;

    const line = v.slice(0, s).split("\n").length;
    const col = s - v.lastIndexOf("\n", s - 1);

    $("cursorStatus").textContent = `Ln ${line}, Col ${col}${e > s ? ` (${e - s} selected)` : ""}`;

    const words = (v.match(/\S+/g) || []).length;
    $("stats").textContent = `${v.length} chars · ${words} words · ${v.split("\n").length} lines`;
  }

  function updateUndoRedoButtons() {
    const h = getHistory(state.active);
    $("undoBtn").disabled = !h.undo.length;
    $("redoBtn").disabled = !h.redo.length;
  }

  function rulesFor(lang) {
    if (lang === "javascript") {
      return [
        ["comment", /\/\/[^\n]*|\/\*[\s\S]*?\*\//],
        ["string", /`(?:\\[\s\S]|[^\\`])*`|"(?:\\[\s\S]|[^\\"])*"|'(?:\\[\s\S]|[^\\'])*'/],
        ["keyword", /\b(?:var|let|const|function|return|if|else|for|while|do|break|continue|new|class|extends|super|import|export|default|try|catch|finally|throw|async|await|typeof|instanceof|in|of|delete|void|this|null|undefined|true|false|switch|case|yield)\b/],
        ["number", /\b(?:0[xX][\da-fA-F]+|\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)\b/],
        ["operator", /[+\-*/%=!<>&|?:^~]+/]
      ];
    }

    if (lang === "html") {
      return [
        ["comment", /<!--[\s\S]*?-->/],
        ["string", /"[^"]*"|'[^']*'/],
        ["tag", /<\/?[a-zA-Z][^\s>]*|\/?>/],
        ["attr", /\b[a-zA-Z-]+(?==)/],
        ["entity", /&[a-zA-Z0-9#]+;/]
      ];
    }

    if (lang === "css") {
      return [
        ["comment", /\/\*[\s\S]*?\*\//],
        ["string", /"[^"]*"|'[^']*'/],
        ["keyword", /@[a-z-]+|\b[a-z-]+(?=\s*:)/],
        ["number", /#[0-9a-fA-F]{3,8}\b|\b\d+(?:\.\d+)?(?:px|em|rem|%|vh|vw|s|ms)?/],
        ["tag", /[.#][\w-]+/]
      ];
    }

    if (lang === "json") {
      return [
        ["string", /"(?:\\.|[^"\\])*"/],
        ["number", /-?\b\d+(?:\.\d+)?(?:[eE][+-]?\d+)?\b/],
        ["keyword", /\b(?:true|false|null)\b/]
      ];
    }

    if (lang === "markdown") {
      return [
        ["comment", /```[\s\S]*?```/],
        ["string", /`[^`\n]+`/],
        ["keyword", /^#{1,6}[^\n]*|\*\*[^*\n]+\*\*|\*[^*\n]+\*|__[^\n]+__|\[[^\]]+\]\([^)]+\)/]
      ];
    }

    if (lang === "python") {
      return [
        ["comment", /#[^\n]*/],
        ["string", /"""[\s\S]*?"""|'''[\s\S]*?'''|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'/],
        ["keyword", /\b(?:def|class|return|if|elif|else|for|while|break|continue|import|from|as|try|except|finally|with|lambda|pass|raise|global|nonlocal|assert|yield|async|await|True|False|None|and|or|not|in|is)\b/],
        ["number", /\b\d+(?:\.\d+)?\b/]
      ];
    }

    return null;
  }

  function highlightCode(code, lang) {
    const rules = rulesFor(lang);
    if (!rules) return escapeHtml(code);

    const pattern = rules.map(r => `(${r[1].source})`).join("|");
    const re = new RegExp(pattern, "gm");

    let out = "";
    let last = 0;

    for (const m of code.matchAll(re)) {
      out += escapeHtml(code.slice(last, m.index));

      const idx = m.slice(1).findIndex(g => g !== undefined);
      const cls = rules[idx] ? rules[idx][0] : "";

      out += `<span class="tok-${cls}">${escapeHtml(m[0])}</span>`;
      last = m.index + m[0].length;
    }

    out += escapeHtml(code.slice(last));
    return out;
  }

  editor.addEventListener("input", () => {
    const d = activeDoc();
    const h = getHistory(d.id);

    if (h.lastValue !== editor.value) {
      h.undo.push({
        text: h.lastValue,
        start: editor.selectionStart,
        end: editor.selectionEnd
      });
      if (h.undo.length > 300) h.undo.shift();
      h.redo = [];
      h.lastValue = editor.value;
    }

    d.content = editor.value;
    renderEditor();
    scheduleSave();
    debouncedPreview();
  });

  editor.addEventListener("scroll", syncScroll);
  editor.addEventListener("click", updateStatus);
  editor.addEventListener("keyup", updateStatus);

  editor.addEventListener("beforeinput", e => {
    if (e.inputType === "historyUndo" || e.inputType === "historyRedo") {
      e.preventDefault();
      if (e.inputType === "historyUndo") undo();
      else redo();
    }
  });

  function undo() {
    const h = getHistory(state.active);
    if (!h.undo.length) return;

    const current = {
      text: editor.value,
      start: editor.selectionStart,
      end: editor.selectionEnd
    };

    h.redo.push(current);
    const prev = h.undo.pop();

    editor.value = prev.text;
    editor.setSelectionRange(prev.start, prev.end);

    h.lastValue = editor.value;
    activeDoc().content = editor.value;

    renderEditor();
    scheduleSave();
    updatePreview();
  }

  function redo() {
    const h = getHistory(state.active);
    if (!h.redo.length) return;

    const current = {
      text: editor.value,
      start: editor.selectionStart,
      end: editor.selectionEnd
    };

    h.undo.push(current);
    const next = h.redo.pop();

    editor.value = next.text;
    editor.setSelectionRange(next.start, next.end);

    h.lastValue = editor.value;
    activeDoc().content = editor.value;

    renderEditor();
    scheduleSave();
    updatePreview();
  }

  function replaceRange(start, end, text, selectStart, selectEnd) {
    const h = getHistory(state.active);

    h.undo.push({
      text: editor.value,
      start,
      end
    });

    if (h.undo.length > 300) h.undo.shift();
    h.redo = [];

    editor.setRangeText(text, start, end, "end");

    if (selectStart != null) {
      editor.setSelectionRange(selectStart, selectEnd ?? selectStart);
    }

    h.lastValue = editor.value;
    activeDoc().content = editor.value;

    renderEditor();
    scheduleSave();
    updatePreview();
    editor.focus();
  }

  function replaceDocument(text) {
    replaceRange(0, editor.value.length, text, Math.min(editor.selectionStart, text.length));
  }

  editor.addEventListener("keydown", e => {
    if (e.isComposing) return;

    const mod = e.ctrlKey || e.metaKey;

    if (e.key === "Tab") {
      e.preventDefault();
      indentSelection(e.shiftKey);
      return;
    }

    if (mod && e.key === "/") {
      e.preventDefault();
      toggleComment();
      return;
    }

    if (e.key === "Enter" && !mod && !e.shiftKey) {
      e.preventDefault();
      autoIndent();
      return;
    }

    const pairs = {
      "(": ")",
      "[": "]",
      "{": "}",
      '"': '"',
      "'": "'",
      "`": "`"
    };

    const s = editor.selectionStart;
    const end = editor.selectionEnd;

    if (!mod && !e.altKey && pairs[e.key]) {
      e.preventDefault();
      const selected = editor.value.slice(s, end);
      replaceRange(s, end, e.key + selected + pairs[e.key], s + 1, end + 1);
      return;
    }

    if (!mod && [")", "]", "}", '"', "'", "`"].includes(e.key) && s === end && editor.value[s] === e.key) {
      e.preventDefault();
      editor.setSelectionRange(s + 1, s + 1);
      updateStatus();
      return;
    }

    if (e.key === "Backspace" && s === end && s > 0 && pairs[editor.value[s - 1]] === editor.value[s]) {
      e.preventDefault();
      replaceRange(s - 1, s + 1, "");
      return;
    }
  });

  function indentSelection(outdent) {
    const s = editor.selectionStart;
    const e = editor.selectionEnd;
    const value = editor.value;
    const size = state.settings.tabSize || 2;

    if (s === e && !outdent) {
      replaceRange(s, e, " ".repeat(size));
      return;
    }

    const start = value.lastIndexOf("\n", s - 1) + 1;
    let end = value.indexOf("\n", e);
    if (end === -1) end = value.length;

    const block = value.slice(start, end);

    const transformed = block.split("\n").map(line => {
      return outdent
        ? line.replace(new RegExp(`^ {1,${size}}`), "")
        : " ".repeat(size) + line;
    }).join("\n");

    replaceRange(start, end, transformed, start, start + transformed.length);
  }

  function autoIndent() {
    const s = editor.selectionStart;
    const e = editor.selectionEnd;
    const value = editor.value;

    const lineStart = value.lastIndexOf("\n", s - 1) + 1;
    const line = value.slice(lineStart, s);
    const indent = (line.match(/^[ \t]*/) || [""])[0];

    const extra = ["{", "[", "("].includes(value[s - 1])
      ? " ".repeat(state.settings.tabSize || 2)
      : "";

    const right = value.slice(e);

    if (extra && /^[}\])]/.test(right)) {
      replaceRange(s, e, "\n" + indent + extra + "\n" + indent, s + 1 + indent.length + extra.length);
    } else {
      replaceRange(s, e, "\n" + indent, s + 1 + indent.length);
    }
  }

  function toggleComment() {
    const d = activeDoc();
    const value = editor.value;
    const s = editor.selectionStart;
    const e = editor.selectionEnd;

    const start = value.lastIndexOf("\n", s - 1) + 1;
    let end = value.indexOf("\n", e);
    if (end === -1) end = value.length;

    const block = value.slice(start, end);

    if (d.lang === "html") {
      const out = block.trim().startsWith("<!--")
        ? block.replace(/^\s*<!--|-->\s*$/g, "")
        : `<!-- ${block} -->`;
      replaceRange(start, end, out, start, start + out.length);
      return;
    }

    if (d.lang === "css") {
      const out = block.trim().startsWith("/*")
        ? block.replace(/^\s*\/\*|\*\/\s*$/g, "")
        : `/* ${block} */`;
      replaceRange(start, end, out, start, start + out.length);
      return;
    }

    const prefix = d.lang === "python" ? "#" : "//";
    const lines = block.split("\n");

    const uncomment = lines
      .filter(l => l.trim())
      .every(l => l.trim().startsWith(prefix));

    const out = lines.map(line => {
      if (!line.trim()) return line;
      const ws = line.match(/^[ \t]*/)[0];
      const content = line.slice(ws.length);

      return uncomment
        ? ws + content.slice(prefix.length).replace(/^ /, "")
        : ws + prefix + " " + content;
    }).join("\n");

    replaceRange(start, end, out, start, start + out.length);
  }

  function toggleFind(force) {
    const open = force ?? $("findbar").hidden;
    $("findbar").hidden = !open;
    $("findBtn").classList.toggle("active", open);

    if (open) {
      const sel = editor.value.slice(editor.selectionStart, editor.selectionEnd);
      if (sel && !sel.includes("\n")) $("findInput").value = sel;
