  function updateMatches() {
    matches = [];
    matchIndex = -1;
    $("matchCount").textContent = "";

    const term = $("findInput").value;
    if (!term || $("findbar").hidden) return;

    try {
      const re = buildFindRegex();
      if (!re) return;

      let m;
      while ((m = re.exec(editor.value)) && matches.length < 20000) {
        matches.push({ start: m.index, end: m.index + m[0].length });
        if (!m[0].length) re.lastIndex++;
      }

      $("matchCount").textContent = matches.length ? `${matches.length} matches` : "No matches";
    } catch (e) {
      $("matchCount").textContent = "Invalid regex";
    }
  }

  function findNext(dir = 1) {
    if (!matches.length) updateMatches();
    if (!matches.length) return;

    const pos = editor.selectionStart;

    if (matchIndex < 0) {
      let idx = -1;

      if (dir > 0) {
        idx = matches.findIndex(m => m.start >= pos);
      } else {
        for (let i = matches.length - 1; i >= 0; i--) {
          if (matches[i].start <= pos) {
            idx = i;
            break;
          }
        }
      }

      matchIndex = idx >= 0 ? idx : (dir > 0 ? 0 : matches.length - 1);
    } else {
      matchIndex = (matchIndex + dir + matches.length) % matches.length;
    }

    const m = matches[matchIndex];
    editor.focus();
    editor.setSelectionRange(m.start, m.end);
    $("matchCount").textContent = `${matchIndex + 1}/${matches.length}`;
    updateStatus();
  }

  function replaceOne() {
    if (!matches.length) updateMatches();
    if (!matches.length) return;

    const s = editor.selectionStart;
    const e = editor.selectionEnd;

    const idx = matches.findIndex(m => m.start === s && m.end === e);
    if (idx < 0) {
      findNext(1);
      return;
    }

    const m = matches[idx];
    const replacement = $("replaceInput").value;

    replaceRange(m.start, m.end, replacement, m.start + replacement.length);
    updateMatches();
    findNext(1);
  }

  function replaceAll() {
    const term = $("findInput").value;
    if (!term) return;

    let count = 0;
    let result;

    try {
      const re = buildFindRegex();
      result = editor.value.replace(re, () => {
        count++;
        return $("replaceInput").value;
      });
    } catch (e) {
      $("matchCount").textContent = "Invalid regex";
