#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

string normalize(const string& s) {
    size_t pos = s.find_first_not_of('0');
    if (pos == string::npos) return "0";
    return s.substr(pos);
}

string addBig(const string& a, const string& b) {
    string x = normalize(a);
    string y = normalize(b);

    int i = (int)x.size() - 1;
    int j = (int)y.size() - 1;
    int carry = 0;
    string result;

    while (i >= 0 || j >= 0 || carry) {
        int sum = carry;

        if (i >= 0) sum += x[i--] - '0';
        if (j >= 0) sum += y[j--] - '0';

        result.push_back(char('0' + (sum % 10)));
        carry = sum / 10;
    }

    reverse(result.begin(), result.end());
    return normalize(result);
}

int compareBig(const string& a, const string& b) {
    string x = normalize(a);
    string y = normalize(b);

    if (x.size() != y.size())
        return x.size() < y.size() ? -1 : 1;

    if (x == y) return 0;
    return x < y ? -1 : 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    string sum1 = "0", sum2 = "0", score;

    for (int i = 0; i < n; ++i) {
        cin >> score;
        sum1 = addBig(sum1, score);
    }

    for (int i = 0; i < n; ++i) {
        cin >> score;
        sum2 = addBig(sum2, score);
    }

    if (compareBig(sum1, sum2) > 0)
        cout << "one\n";
    else
        cout << "two\n";

    return 0;
}
