## My answer

A geometry shader cannot “iterate over every texture pixel” by itself. It only runs for input primitives. So the usual Unity setup is:

1. Generate a mesh with **one point per texture pixel/texel**.
2. Each point has a UV pointing to the center of its texel.
3. The geometry shader samples the texture in the geometry stage.
4. If alpha is above a cutoff, it emits a quad or an extruded box.

Below is a complete Built-in Render Pipeline example. It creates one point per texture pixel and extrudes non-transparent pixels along local `+Z`.

### Shader

```hlsl
Shader "Custom/TexturePixelExtrudeGeometry"
{
    Properties
    {
        _MainTex ("Texture", 2D) = "white" {}
        _AlphaCutoff ("Alpha Cutoff", Range(0, 1)) = 0.01
        _PixelSize ("Pixel Size", Float) = 0.01
        _Extrusion ("Extrusion Factor", Float) = 1.0
    }

    SubShader
    {
        Tags
        {
            "RenderType" = "Opaque"
        }

        Pass
        {
            Cull Off
            ZWrite On

            CGPROGRAM
            #pragma target 4.0
            #pragma vertex vert
            #pragma geometry geom
            #pragma fragment frag

            #include "UnityCG.cginc"

            sampler2D _MainTex;
            float _AlphaCutoff;
            float _PixelSize;
            float _Extrusion;

            struct appdata
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct v2g
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct g2f
            {
                float4 pos : SV_POSITION;
                float4 color : TEXCOORD0;
            };

            v2g vert(appdata v)
            {
                v2g o;
                o.vertex = v.vertex;
                o.uv = v.uv;
                return o;
            }

            void EmitVertex(
                float3 positionOS,
                float4 color,
                inout TriangleStream<g2f> stream)
            {
                g2f o;
                o.pos = UnityObjectToClipPos(float4(positionOS, 1.0));
                o.color = color;
                stream.Append(o);
            }

            // Emits two triangles for a quad.
            // a, b, c, d should be ordered around the quad perimeter.
            void EmitQuad(
                float3 a,
                float3 b,
                float3 c,
                float3 d,
                float4 color,
                inout TriangleStream<g2f> stream)
            {
                EmitVertex(a, color, stream);
                EmitVertex(b, color, stream);
                EmitVertex(c, color, stream);

                EmitVertex(a, color, stream);
                EmitVertex(c, color, stream);
                EmitVertex(d, color, stream);
            }

            // 6 faces * 2 triangles * 3 vertices = 36 vertices max.
            [maxvertexcount(36)]
            void geom(
                point v2g IN[1],
                inout TriangleStream<g2f> stream)
            {
                // Geometry shaders should use explicit LOD sampling.
                float4 color = tex2Dlod(_MainTex, float4(IN[0].uv, 0.0, 0.0));

                // Skip transparent pixels.
                if (color.a <= _AlphaCutoff)
                    return;

                // This example treats surviving pixels as opaque geometry.
                color.a = 1.0;

                float3 center = IN[0].vertex.xyz;
                float halfSize = _PixelSize * 0.5;
                float depth = _PixelSize * max(_Extrusion, 0.0);

                // Base quad corners.
                float3 p0 = center + float3(-halfSize, -halfSize, 0.0);
                float3 p1 = center + float3( halfSize, -halfSize, 0.0);
                float3 p2 = center + float3( halfSize,  halfSize, 0.0);
                float3 p3 = center + float3(-halfSize,  halfSize, 0.0);

                // If extrusion is zero, emit only a flat quad.
                if (depth <= 0.0)
                {
                    EmitQuad(p0, p1, p2, p3, color, stream);
                    return;
                }

                // Extruded quad corners.
                float3 offset = float3(0.0, 0.0, depth);
                float3 q0 = p0 + offset;
                float3 q1 = p1 + offset;
                float3 q2 = p2 + offset;
                float3 q3 = p3 + offset;

                // Emit a simple box/prism for the extruded pixel.
                EmitQuad(q0, q1, q2, q3, color, stream); // +Z face
                EmitQuad(p0, p3, p2, p1, color, stream); // -Z face
                EmitQuad(p0, p1, q1, q0, color, stream); // -Y face
                EmitQuad(p2, p3, q3, q2, color, stream); // +Y face
                EmitQuad(p1, p2, q2, q1, color, stream); // +X face
                EmitQuad(p3, p0, q0, q3, color, stream); // -X face
            }

            fixed4 frag(g2f i) : SV_Target
            {
                return i.color;
            }
            ENDCG
        }
    }

    Fallback Off
}
```

### C# script to create one point per texture pixel

Attach this to a GameObject with `MeshFilter` and `MeshRenderer`.

```csharp
using UnityEngine;
using UnityEngine.Rendering;

[RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
public class TexturePixelExtrusionPoints : MonoBehaviour
{
    public Texture2D texture;
    public Material material;

    public float pixelSize = 0.01f;
    public float extrusion = 1f;

    [Range(0f, 1f)]
    public float alphaCutoff = 0.01f;

    private Mesh pointMesh;
    private MeshRenderer meshRenderer;
    private MaterialPropertyBlock propertyBlock;

    private int textureWidth;
    private int textureHeight;
    private float builtPixelSize;

    private void Start()
    {
        BuildPointMesh();
    }

    public void BuildPointMesh()
    {
        if (texture == null || material == null)
        {
            Debug.LogError("Assign both a texture and a material.", this);
            return;
        }

        textureWidth = texture.width;
        textureHeight = texture.height;
        builtPixelSize = Mathf.Max(pixelSize, 0.0001f);

        int count = textureWidth * textureHeight;

        var positions = new Vector3[count];
        var uvs = new Vector2[count];
        var indices = new int[count];

        for (int y = 0; y < textureHeight; y++)
        {
            for (int x = 0; x < textureWidth; x++)
            {
                int i = y * textureWidth + x;

                // Center the texture around the local origin.
                positions[i] = new Vector3(
                    (x + 0.5f - textureWidth * 0.5f) * builtPixelSize,
                    (y + 0.5f - textureHeight * 0.5f) * builtPixelSize,
                    0f
                );

                // Sample texel centers.
                uvs[i] = new Vector2(
                    (x + 0.5f) / textureWidth,
                    (y + 0.5f) / textureHeight
                );

                indices[i] = i;
            }
        }

        if (pointMesh != null)
            Destroy(pointMesh);

        pointMesh = new Mesh
        {
            name = "Texture Pixel Points",
            indexFormat = count > 65535
                ? IndexFormat.UInt32
                : IndexFormat.UInt16
        };

        pointMesh.vertices = positions;
        pointMesh.uv = uvs;
        pointMesh.SetIndices(indices, MeshTopology.Points, 0, false);

        GetComponent<MeshFilter>().sharedMesh = pointMesh;

        meshRenderer = GetComponent<MeshRenderer>();
        meshRenderer.sharedMaterial = material;

        propertyBlock = new MaterialPropertyBlock();
        UpdateMaterialBlock();
    }

    private void LateUpdate()
    {
        if (pointMesh != null)
            UpdateMaterialBlock();
    }

    private void UpdateMaterialBlock()
    {
        if (meshRenderer == null || pointMesh == null)
            return;

        float factor = Mathf.Max(extrusion, 0f);
        float depth = builtPixelSize * factor;

        meshRenderer.GetPropertyBlock(propertyBlock);

        propertyBlock.SetTexture("_MainTex", texture);
        propertyBlock.SetFloat("_PixelSize", builtPixelSize);
        propertyBlock.SetFloat("_Extrusion", factor);
        propertyBlock.SetFloat("_AlphaCutoff", alphaCutoff);

        meshRenderer.SetPropertyBlock(propertyBlock);

        // Unity cannot infer the expanded bounds from the geometry shader.
        pointMesh.bounds = new Bounds(
            new Vector3(0f, 0f, depth * 0.5f),
            new Vector3(
                textureWidth * builtPixelSize,
                textureHeight * builtPixelSize,
                Mathf.Max(depth, 0.001f)
            )
        );
    }

    private void OnDestroy()
    {
        if (pointMesh != null)
            Destroy(pointMesh);
    }
}
```

