Shader "Custom/TexturePixelExtrudeGeometry"
{
    Properties
    {
        _MainTex ("Texture", 2D) = "white" {}
        _Cutoff ("Alpha Cutoff", Range(0,1)) = 0.01
        _PixelSize ("Pixel Size", Float) = 0.01
        _Extrusion ("Extrusion Factor", Float) = 1
    }
    SubShader
    {
        Tags { "RenderType"="Opaque" }
        Pass
        {
            Cull Off
            ZWrite On
            CGPROGRAM
            #pragma target 4.0
            #pragma vertex vert
            #pragma geometry geom
            #pragma fragment frag
            #include "UnityCG.cginc"

            sampler2D _MainTex;
            float _Cutoff;
            float _PixelSize;
            float _Extrusion;

            struct appdata { float4 vertex : POSITION; float2 uv : TEXCOORD0; };
            struct v2g { float3 posOS : TEXCOORD0; float2 uv : TEXCOORD1; };
            struct g2f { float4 pos : SV_POSITION; float4 color : COLOR0; };

            v2g vert(appdata v)
            {
                v2g o;
                o.posOS = v.vertex.xyz;
                o.uv = v.uv;
                return o;
            }

            void AppendVtx(float3 posOS, float4 color, inout TriangleStream<g2f> stream)
            {
                g2f o;
                o.pos = UnityObjectToClipPos(float4(posOS, 1.0));
                o.color = color;
                stream.Append(o);
            }

            void EmitTri(float3 a, float3 b, float3 c, float4 color, inout TriangleStream<g2f> stream)
            {
                AppendVtx(a, color, stream);
                AppendVtx(b, color, stream);
                AppendVtx(c, color, stream);
                stream.RestartStrip();
            }

            [maxvertexcount(36)]
            void geom(point v2g input[1], inout TriangleStream<g2f> stream)
            {
                float4 col = tex2Dlod(_MainTex, float4(input[0].uv, 0, 0));
                if (col.a <= _Cutoff)
                    return;

                col.a = 1.0;

                float3 center = input[0].posOS;
                float halfSize = _PixelSize * 0.5;
                float height = _PixelSize * max(_Extrusion, 0.0);

                float3 b0 = center + float3(-halfSize, -halfSize, 0);
                float3 b1 = center + float3( halfSize, -halfSize, 0);
                float3 b2 = center + float3( halfSize,  halfSize, 0);
                float3 b3 = center + float3(-halfSize,  halfSize, 0);

                if (height <= 0.0)
                {
                    EmitTri(b0, b1, b2, col, stream);
                    EmitTri(b0, b2, b3, col, stream);
                    return;
                }

                float3 t0 = b0 + float3(0,0,height);
                float3 t1 = b1 + float3(0,0,height);
                float3 t2 = b2 + float3(0,0,height);
                float3 t3 = b3 + float3(0,0,height);

                // Top (+Z)
                EmitTri(t0, t1, t2, col, stream);
                EmitTri(t0, t2, t3, col, stream);

                // Bottom (-Z)
                EmitTri(b0, b3, b2, col, stream);
                EmitTri(b0, b2, b1, col, stream);

                // -Y side
                EmitTri(b0, t0, t1, col, stream);
                EmitTri(b0, t1, b1, col, stream);

                // +Y side
                EmitTri(b3, b2, t2, col, stream);
                EmitTri(b3, t2, t3, col, stream);

                // -X side
                EmitTri(b0, b3, t3, col, stream);
                EmitTri(b0, t3, t0, col, stream);

                // +X side
                EmitTri(b1, t1, t2, col, stream);
                EmitTri(b1, t2, b2, col, stream);
            }

            fixed4 frag(g2f i) : SV_Target
            {
                return i.color;
            }
            ENDCG
        }
    }
    Fallback Off
}
```
