Shader "Custom/TexturePixelExtrudeGeometry"
{
    Properties
    {
        _MainTex("Texture", 2D) = "white" {}
        _Cutoff("Alpha Cutoff", Range(0,1)) = 0.01
        _PixelSize("Pixel Size", Float) = 0.01
        _Extrusion("Extrusion Factor", Float) = 1
    }

    SubShader
    {
        Tags { "RenderType" = "Opaque" }

        Pass
        {
            Cull Off
            ZWrite On

            CGPROGRAM
            #pragma target 4.0
            #pragma vertex vert
            #pragma geometry geom
            #pragma fragment frag
            #include "UnityCG.cginc"

            sampler2D _MainTex;
            float _Cutoff;
            float _PixelSize;
            float _Extrusion;

            struct appdata
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct v2g
            {
                float3 posOS : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct g2f
            {
                float4 pos : SV_POSITION;
                float4 color : COLOR0;
            };

            v2g vert(appdata v)
            {
                v2g o;
                o.posOS = v.vertex.xyz;
                o.uv = v.uv;
                return o;
            }

            void AppendVertex(float3 posOS, float4 color, inout TriangleStream<g2f> stream)
            {
                g2f o;
                o.pos = UnityObjectToClipPos(float4(posOS, 1.0));
                o.color = color;
                stream.Append(o);
            }

            void EmitTriangle(float3 a, float3 b, float3 c, float4 color, inout TriangleStream<g2f> stream)
            {
                AppendVertex(a, color, stream);
                AppendVertex(b, color, stream);
                AppendVertex(c, color, stream);
                stream.RestartStrip();
            }

            [maxvertexcount(36)]
            void geom(point v2g input[1], inout TriangleStream<g2f> stream)
            {
                float4 color = tex2Dlod(_MainTex, float4(input[0].uv, 0, 0));
                if (color.a <= _Cutoff)
                    return;

                color.a = 1.0;

                float3 center = input[0].posOS * _PixelSize;
                float halfSize = _PixelSize * 0.5;
                float depth = _PixelSize * max(_Extrusion, 0.0);

                float3 b0 = center + float3(-halfSize, -halfSize, 0.0);
                float3 b1 = center + float3( halfSize, -halfSize, 0.0);
                float3 b2 = center + float3( halfSize,  halfSize, 0.0);
                float3 b3 = center + float3(-halfSize,  halfSize, 0.0);

                if (depth <= 0.0)
                {
                    EmitTriangle(b0, b1, b2, color, stream);
                    EmitTriangle(b0, b2, b3, color, stream);
                    return;
                }

                float3 t0 = b0 + float3(0.0, 0.0, depth);
                float3 t1 = b1 + float3(0.0, 0.0, depth);
                float3 t2 = b2 + float3(0.0, 0.0, depth);
                float3 t3 = b3 + float3(0.0, 0.0, depth);

                // Top (+Z)
                EmitTriangle(t0, t1, t2, color, stream);
                EmitTriangle(t0, t2, t3, color, stream);

                // Bottom (-Z)
                EmitTriangle(b0, b3, b2, color, stream);
                EmitTriangle(b0, b2, b1, color, stream);

                // -Y side
                EmitTriangle(b0, t0, t1, color, stream);
                EmitTriangle(b0, t1, b1, color, stream);

                // +Y side
                EmitTriangle(b3, b2, t2, color, stream);
                EmitTriangle(b3, t2, t3, color, stream);

                // -X side
                EmitTriangle(b0, b3, t3, color, stream);
                EmitTriangle(b0, t3, t0, color, stream);

                // +X side
                EmitTriangle(b1, t1, t2, color, stream);
                EmitTriangle(b1, t2, b2, color, stream);
            }

            fixed4 frag(g2f i) : SV_Target
            {
                return i.color;
            }
            ENDCG
        }
    }

    Fallback Off
}
