using UnityEngine;
using UnityEngine.Rendering;

[RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
public class TexturePixelExtrudePoints : MonoBehaviour
{
    public Texture2D texture;
    public Material material;

    [Min(0.0001f)] public float pixelSize = 0.01f;
    [Min(0f)] public float extrusion = 1f;
    [Range(0f, 1f)] public float alphaCutoff = 0.01f;

    Mesh pointMesh;
    MeshRenderer meshRenderer;
    MaterialPropertyBlock propertyBlock;

    void Start()
    {
        if (texture == null || material == null)
        {
            Debug.LogError("Assign texture and material.", this);
            enabled = false;
            return;
        }

        BuildPointMesh();
        meshRenderer = GetComponent<MeshRenderer>();
        meshRenderer.sharedMaterial = material;
        propertyBlock = new MaterialPropertyBlock();
        UpdateMaterialProperties();
    }

    void LateUpdate()
    {
        if (pointMesh != null && meshRenderer != null)
        {
            UpdateMaterialProperties();
            UpdateMeshBounds();
        }
    }

    void BuildPointMesh()
    {
        int w = texture.width;
        int h = texture.height;
        int count = checked(w * h);

        var positions = new Vector3[count];
        var uvs = new Vector2[count];
        var indices = new int[count];

        for (int y = 0; y < h; y++)
        {
            for (int x = 0; x < w; x++)
            {
                int i = y * w + x;

                // Positions are in texel units. The geometry shader multiplies by _PixelSize.
                positions[i] = new Vector3(
                    x + 0.5f - w * 0.5f,
                    y + 0.5f - h * 0.5f,
                    0f);

                uvs[i] = new Vector2(
                    (x + 0.5f) / w,
                    (y + 0.5f) / h);

                indices[i] = i;
            }
        }

        pointMesh = new Mesh
        {
            name = "Texture Pixel Points",
            indexFormat = count > 65535 ? IndexFormat.UInt32 : IndexFormat.UInt16
        };

        pointMesh.vertices = positions;
        pointMesh.uv = uvs;
        pointMesh.SetIndices(indices, MeshTopology.Points, 0, false);

        GetComponent<MeshFilter>().sharedMesh = pointMesh;
        UpdateMeshBounds();
    }

    void UpdateMeshBounds()
    {
        if (pointMesh == null || texture == null)
            return;

        float ps = Mathf.Max(pixelSize, 0.0001f);
        float depth = ps * Mathf.Max(extrusion, 0f);

        pointMesh.bounds = new Bounds(
            new Vector3(0f, 0f, depth * 0.5f),
            new Vector3(texture.width * ps, texture.height * ps, Mathf.Max(depth, 0.001f)));
    }

    void UpdateMaterialProperties()
    {
        meshRenderer.GetPropertyBlock(propertyBlock);
        propertyBlock.SetTexture("_MainTex", texture);
        propertyBlock.SetFloat("_PixelSize", Mathf.Max(pixelSize, 0.0001f));
        propertyBlock.SetFloat("_Extrusion", Mathf.Max(extrusion, 0f));
        propertyBlock.SetFloat("_Cutoff", alphaCutoff);
        meshRenderer.SetPropertyBlock(propertyBlock);
    }

    void OnDestroy()
    {
        if (pointMesh != null)
            Destroy(pointMesh);
    }
}
