import SwiftUI

// MARK: - App

@main
struct TennisScoreTrackerApp: App {
    var body: some Scene {
        WindowGroup {
            ContentView()
        }
    }
}

// MARK: - Point detail

enum PointDetail: String, Codable, CaseIterable, Identifiable {
    case winner = "Winner"
    case unforcedError = "Unforced Error"
    case forcedError = "Forced Error"
    case ace = "Ace"
    case returnWinner = "Return Winner"
    case serveWinner = "Serve Winner"

    var id: String { rawValue }

    var isError: Bool {
        self == .unforcedError || self == .forcedError
    }

    func isAllowed(winner: Int, server: Int) -> Bool {
        switch self {
        case .ace, .serveWinner:
            return winner == server
        case .returnWinner:
            return winner != server
        default:
            return true
        }
    }

    var explanation: String {
        switch self {
        case .winner:
            return "A winning shot by the point winner."
        case .unforcedError:
            return "The point winner won because the opponent made an unforced error."
        case .forcedError:
            return "The point winner won because the opponent made a forced error."
        case .ace:
            return "The server hit an ace."
        case .returnWinner:
            return "The receiver won the point with a return winner."
        case .serveWinner:
            return "The server won the point with a serve winner that the receiver touched."
        }
    }
}

// MARK: - Stored match data

struct PointRecord: Identifiable, Codable {
    var id = UUID()
    var timestamp = Date()
    var winner: Int
    var server: Int
    var detail: PointDetail?
}

struct MatchData: Codable {
    var playerNames = ["Player 1", "Player 2"]
    var firstServer = 0
    var records: [PointRecord] = []

    func name(for player: Int) -> String {
        let name = playerNames[player].trimmingCharacters(in: .whitespacesAndNewlines)
        return name.isEmpty ? "Player \(player + 1)" : name
    }
}

// MARK: - Derived score

struct SetResult {
    let games: [Int]
    let tiebreakPoints: [Int]?

    var winner: Int {
        games[0] > games[1] ? 0 : 1
    }

    var display: String {
        var text = "\(games[0])–\(games[1])"
        if let tiebreakPoints {
            text += " (TB \(tiebreakPoints[0])–\(tiebreakPoints[1]))"
        }
        return text
    }
}

struct TennisScore {
    private(set) var completedSets: [SetResult] = []
    private(set) var games = [0, 0]
    private(set) var points = [0, 0]
    private(set) var currentGameServer: Int

    init(firstServer: Int) {
        currentGameServer = firstServer
    }

    var setWins: [Int] {
        completedSets.reduce(into: [0, 0]) { result, set in
            result[set.winner] += 1
        }
    }

    var matchWinner: Int? {
        setWins.firstIndex(where: { $0 == 2 })
    }

    var isFinished: Bool {
        matchWinner != nil
    }

    var inTiebreak: Bool {
        !isFinished && games[0] == 6 && games[1] == 6
    }

    var currentSetNumber: Int {
        completedSets.count + 1
    }

    var server: Int {
        guard inTiebreak else { return currentGameServer }

        let pointsPlayed = points[0] + points[1]
        let offset = ((pointsPlayed + 1) / 2) % 2
        return (currentGameServer + offset) % 2
    }

    func pointLabel(for player: Int) -> String {
        guard !isFinished else { return "—" }

        if inTiebreak {
            return String(points[player])
        }

        if points[0] >= 3 && points[1] >= 3 {
            if points[player] == points[1 - player] {
                return "40"
            }
            return points[player] > points[1 - player] ? "AD" : "40"
        }

        return ["0", "15", "30", "40"][min(points[player], 3)]
    }

    mutating func awardPoint(to player: Int) {
        guard !isFinished, (0...1).contains(player) else { return }

        let opponent = 1 - player

        if inTiebreak {
            points[player] += 1

            if points[player] >= 7 && points[player] - points[opponent] >= 2 {
                let tiebreakPoints = points
                games[player] += 1
                currentGameServer = 1 - currentGameServer
                finishSet(tiebreakPoints: tiebreakPoints)
            }

            return
        }

        points[player] += 1

        let wonGame = points[player] >= 4 && points[player] - points[opponent] >= 2
        guard wonGame else { return }

        games[player] += 1
        points = [0, 0]
        currentGameServer = 1 - currentGameServer

        let wonSet = games[player] >= 6 && games[player] - games[opponent] >= 2
        if wonSet {
            finishSet(tiebreakPoints: nil)
        }
    }

    private mutating func finishSet(tiebreakPoints: [Int]?) {
        completedSets.append(
            SetResult(
                games: games,
                tiebreakPoints: tiebreakPoints
            )
        )

        games = [0, 0]
        points = [0, 0]
    }
}

// MARK: - Store

final class MatchStore: ObservableObject {
    private static let storageKey = "TennisScoreTracker.match.v1"

    @Published private(set) var match: MatchData {
        didSet {
            save()
        }
    }

    init() {
        if let data = UserDefaults.standard.data(forKey: Self.storageKey),
           let saved = try? JSONDecoder().decode(MatchData.self, from: data),
           saved.playerNames.count == 2,
           (0...1).contains(saved.firstServer),
           saved.records.allSatisfy({
               (0...1).contains($0.winner) && (0...1).contains($0.server)
           }) {
            match = saved
        } else {
            match = MatchData()
        }
    }

    var score: TennisScore {
        var score = TennisScore(firstServer: match.firstServer)

        for record in match.records {
            score.awardPoint(to: record.winner)
        }

        return score
    }

    func setName(_ name: String, for player: Int) {
        guard (0...1).contains(player), match.records.isEmpty else { return }
        match.playerNames[player] = name
    }

    func setFirstServer(_ player: Int) {
        guard (0...1).contains(player), match.records.isEmpty else { return }
        match.firstServer = player
    }

    func awardPoint(to player: Int, detail: PointDetail?) {
        let currentScore = score

        guard !currentScore.isFinished,
              (0...1).contains(player) else {
            return
        }

        if let detail {
            guard detail.isAllowed(winner: player, server: currentScore.server) else {
                return
            }
        }

        match.records.append(
            PointRecord(
                winner: player,
                server: currentScore.server,
                detail: detail
            )
        )
    }

    func undo() {
        guard !match.records.isEmpty else { return }
        match.records.removeLast()
    }

    func startNewMatch() {
        var newMatch = MatchData()
        newMatch.playerNames = match.playerNames
        newMatch.firstServer = match.firstServer
        match = newMatch
    }

    private func save() {
        guard let data = try? JSONEncoder().encode(match) else { return }
        UserDefaults.standard.set(data, forKey: Self.storageKey)
    }
}

