struct ContentView: View {
    @StateObject private var store = MatchStore()
    @AppStorage("TennisScoreTracker.advanced") private var advancedTracking = false
    @State private var pendingPoint: PendingPoint?
    @State private var showNewMatchConfirmation = false

    var body: some View {
        let score = store.score

        NavigationStack {
            List {
                setupSection
                scoreSection(score)
                pointEntrySection(score)

                if !score.completedSets.isEmpty {
                    completedSetsSection(score)
                }

                if !store.match.records.isEmpty {
                    historySection
                }
            }
            .navigationTitle("Tennis Score Tracker")
            .toolbar {
                ToolbarItem(placement: .navigationBarLeading) {
                    Button("Undo", action: store.undo)
                        .disabled(store.match.records.isEmpty)
                }
                ToolbarItem(placement: .navigationBarTrailing) {
                    Button("New Match") {
                        showNewMatchConfirmation = true
                    }
                }
            }
            .confirmationDialog(
                "Start a new match?",
                isPresented: $showNewMatchConfirmation,
                titleVisibility: .visible
            ) {
                Button("Start New Match", role: .destructive) {
                    store.startNewMatch()
                }
                Button("Cancel", role: .cancel) {}
            } message: {
                Text("This clears the current score and point history.")
            }
            .sheet(item: $pendingPoint) { pending in
                PointDetailView(
                    playerNames: [store.match.name(for: 0), store.match.name(for: 1)],
                    winner: pending.winner,
                    server: pending.server
                ) { detail in
                    store.awardPoint(to: pending.winner, detail: detail)
                }
            }
        }
    }

    private var setupSection: some View {
        Section {
            ForEach(0..<2, id: \.self) { player in
                TextField(
                    "Player \(player + 1)",
                    text: Binding(
                        get: { store.match.playerNames[player] },
                        set: { store.setName($0, for: player) }
                    )
                )
                .textInputAutocapitalization(.words)
                .autocorrectionDisabled()
                .disabled(!store.match.records.isEmpty)
            }

            Picker(
                "First server",
                selection: Binding(
                    get: { store.match.firstServer },
                    set: { store.setFirstServer($0) }
                )
            ) {
                ForEach(0..<2, id: \.self) { player in
                    Text(store.match.name(for: player)).tag(player)
                }
            }
            .disabled(!store.match.records.isEmpty)

            Toggle("Advanced point tracking", isOn: $advancedTracking)
        } header: {
            Text("Match setup")
        } footer: {
            Text("Best of three sets. A set uses a seven-point tiebreak at 6–6. Names and first server lock after the first point.")
        }
    }

    private func scoreSection(_ score: TennisScore) -> some View {
        Section {
            HStack {
                Text("Player")
                    .frame(maxWidth: .infinity, alignment: .leading)
                Text("Sets")
                    .frame(width: 42)
                Text("Games")
                    .frame(width: 54)
                Text(score.inTiebreak ? "TB" : "Points")
                    .frame(width: 58)
            }
            .font(.caption)
            .foregroundStyle(.secondary)

            ForEach(0..<2, id: \.self) { player in
                HStack {
                    VStack(alignment: .leading, spacing: 2) {
                        Text(store.match.name(for: player))
                            .fontWeight(.semibold)
                        if !score.isFinished && score.server == player {
                            Text("Serving")
                                .font(.caption2)
                                .foregroundStyle(.green)
                        }
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)

                    Text("\(score.setWins[player])")
                        .frame(width: 42)
                    Text(score.isFinished ? "—" : "\(score.games[player])")
                        .frame(width: 54)
                    Text(score.pointLabel(for: player))
                        .font(.headline)
                        .frame(width: 58)
                }
                .monospacedDigit()
                .padding(.vertical, 2)
            }

            if let winner = score.matchWinner {
                Label("\(store.match.name(for: winner)) wins the match!", systemImage: "trophy.fill")
                    .font(.headline)
                    .foregroundStyle(.green)
            } else {
                Text("Set \(score.currentSetNumber)\(score.inTiebreak ? " · Tiebreak" : "")")
                    .font(.subheadline)
            }
        } header: {
            Text("Score")
        }
    }

    private func pointEntrySection(_ score: TennisScore) -> some View {
        Section {
            ForEach(0..<2, id: \.self) { player in
                Button {
                    if advancedTracking {
                        pendingPoint = PendingPoint(winner: player, server: score.server)
                    } else {
                        store.awardPoint(to: player, detail: nil)
                    }
                } label: {
                    Label("Point for \(store.match.name(for: player))", systemImage: "plus.circle.fill")
                        .frame(maxWidth: .infinity, alignment: .leading)
                }
                .disabled(score.isFinished)
            }
        } header: {
            Text("Who won the point?")
        } footer: {
            Text(
                advancedTracking
                ? "After choosing the point winner, select how the point ended."
                : "Turn on advanced point tracking to record winner/error/ace details."
            )
        }
    }

    private func completedSetsSection(_ score: TennisScore) -> some View {
        Section("Completed sets") {
            ForEach(score.completedSets.indices, id: \.self) { index in
                Text("Set \(index + 1): \(score.completedSets[index].display)")
            }
        }
    }

    private var historySection: some View {
        Section("Point history") {
            ForEach(Array(store.match.records.enumerated()).reversed(), id: \.element.id) { index, record in
                VStack(alignment: .leading, spacing: 3) {
                    Text("Point \(index + 1): \(store.match.name(for: record.winner)) won")
                        .fontWeight(.semibold)
                    if let detail = record.detail {
                        Text(detailText(detail, record: record))
                    } else {
                        Text("No point detail recorded")
                            .foregroundStyle(.secondary)
                    }
                    Text("Server: \(store.match.name(for: record.server))")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
                .padding(.vertical, 2)
            }
        }
    }

    private func detailText(_ detail: PointDetail, record: PointRecord) -> String {
        if detail.isError {
            return "\(detail.rawValue) by \(store.match.name(for: 1 - record.winner))"
        }
        return detail.rawValue
    }
}

