## My answer

Below is a complete single-file SwiftUI implementation for an iOS app called **Tennis Score Tracker**.

It supports:

- Best-of-three match scoring.
- Normal tennis point scoring: `0`, `15`, `30`, `40`, deuce, advantage.
- Games and sets.
- Tiebreak at `6–6`, first to 7 points with a 2-point margin.
- Automatic serve rotation.
- User input by tapping the player who won each point.
- Advanced point tracking toggle.
- Point outcomes:
  - Winner
  - Unforced error
  - Forced error
  - Ace
  - Return winner
  - Serve winner
- Undo.
- Local persistence using `UserDefaults`.
- Basic match statistics and point history.

This targets **iOS 16+**.

```swift
import SwiftUI

// MARK: - App

@main
struct TennisScoreTrackerApp: App {
    var body: some Scene {
        WindowGroup {
            MatchView()
        }
    }
}

// MARK: - Point outcomes

enum PointOutcome: String, Codable, CaseIterable, Identifiable {
    case none = "No detail"
    case winner = "Winner"
    case unforcedError = "Unforced Error"
    case forcedError = "Forced Error"
    case ace = "Ace"
    case returnWinner = "Return Winner"
    case serveWinner = "Serve Winner"

    var id: String { rawValue }

    var isError: Bool {
        self == .unforcedError || self == .forcedError
    }

    func isAllowed(pointWinner: Int, server: Int) -> Bool {
        switch self {
        case .ace, .serveWinner:
            return pointWinner == server
        case .returnWinner:
            return pointWinner != server
        default:
            return true
        }
    }
}

// MARK: - Stored models

struct PointRecord: Identifiable, Codable {
    var id = UUID()
    var timestamp = Date()
    var winnerIndex: Int
    var outcome: PointOutcome
}

struct MatchState: Codable {
    var playerNames: [String]
    var firstServer: Int
    var records: [PointRecord]

    init(
        playerNames: [String] = ["Player 1", "Player 2"],
        firstServer: Int = 0,
        records: [PointRecord] = []
    ) {
        self.playerNames = playerNames
        self.firstServer = firstServer
        self.records = records
    }

    func displayName(for player: Int) -> String {
        let name = playerNames[player].trimmingCharacters(in: .whitespacesAndNewlines)
        return name.isEmpty ? "Player \(player + 1)" : name
    }
}

struct CompletedSet {
    let games: [Int]
    let tiebreakPoints: [Int]?

    var winner: Int {
        games[0] > games[1] ? 0 : 1
    }

    var display: String {
        var text = "\(games[0])–\(games[1])"
        if let tiebreakPoints {
            text += " (TB \(tiebreakPoints[0])–\(tiebreakPoints[1]))"
        }
        return text
    }
}

// MARK: - Tennis scoring engine

struct TennisScore {
    private(set) var completedSets: [CompletedSet] = []
    private(set) var games = [0, 0]
    private(set) var points = [0, 0]
    private var gameServer: Int

    init(firstServer: Int) {
        gameServer = firstServer
    }

    var setWins: [Int] {
        [
            completedSets.filter { $0.winner == 0 }.count,
            completedSets.filter { $0.winner == 1 }.count
        ]
    }

    var matchWinner: Int? {
        setWins.firstIndex(where: { $0 == 2 })
    }

    var isFinished: Bool {
        matchWinner != nil
    }

    var isTiebreak: Bool {
        !isFinished && games[0] == 6 && games[1] == 6
    }

    var currentSetNumber: Int {
        completedSets.count + 1
    }

    var server: Int {
        if !isTiebreak {
            return gameServer
        }

        let pointsPlayed = points[0] + points[1]
        let serverOffset = ((pointsPlayed + 1) / 2) % 2
        return (gameServer + serverOffset) % 2
    }

    func pointLabel(for player: Int) -> String {
        if isFinished {
            return "—"
        }

        if isTiebreak {
            return String(points[player])
        }

        if points[0] >= 3 && points[1] >= 3 {
            if points[player] == points[1 - player] {
                return "40"
            }
            return points[player] > points[1 - player] ? "AD" : "40"
        }

        return ["0", "15", "30", "40"][min(points[player], 3)]
    }

    var summary: String {
        if isFinished {
            return "Final: " + completedSets.map(\.display).joined(separator: ", ")
        }

        if isTiebreak {
            return "Set \(currentSetNumber), games \(games[0])–\(games[1]), tiebreak \(points[0])–\(points[1])"
        }

        return "Set \(currentSetNumber), games \(games[0])–\(games[1]), points \(pointLabel(for: 0))–\(pointLabel(for: 1))"
    }

    mutating func awardPoint(to player: Int) {
        guard !isFinished, (0...1).contains(player) else { return }

        points[player] += 1
        let opponent = 1 - player

        if isTiebreak {
            if points[player] >= 7 && points[player] - points[opponent] >= 2 {
                let finalTiebreak = points
                games[player] += 1
                gameServer = 1 - gameServer
                finishSet(tiebreakPoints: finalTiebreak)
            }
            return
        }

        let wonGame = points[player] >= 4 && points[player] - points[opponent] >= 2
        guard wonGame else { return }

        games[player] += 1
        points = [0, 0]
        gameServer = 1 - gameServer

        let wonSet = games[player] >= 6 && games[player] - games[opponent] >= 2
        if wonSet {
            finishSet(tiebreakPoints: nil)
        }
    }

    private mutating func finishSet(tiebreakPoints: [Int]?) {
        completedSets.append(
            CompletedSet(games: games, tiebreakPoints: tiebreakPoints)
        )
        games = [0, 0]
        points = [0, 0]
    }
}

// MARK: - View model

@MainActor
final class MatchViewModel: ObservableObject {
    private static let storageKey = "TennisScoreTracker.match.v1"

    @Published private(set) var state: MatchState {
        didSet { save() }
    }

    init() {
        if let data = UserDefaults.standard.data(forKey: Self.storageKey),
           let decoded = try? JSONDecoder().decode(MatchState.self, from: data),
           decoded.playerNames.count == 2,
           (0...1).contains(decoded.firstServer),
           decoded.records.allSatisfy({ (0...1).contains($0.winnerIndex) }) {
            state = decoded
        } else {
            state = MatchState()
        }
    }

    var score: TennisScore {
        var score = TennisScore(firstServer: state.firstServer)
        for record in state.records {
            score.awardPoint(to: record.winnerIndex)
        }
        return score
    }

    func name(for player: Int) -> String {
        state.displayName(for: player)
    }

    func updateName(_ name: String, for player: Int) {
        guard state.records.isEmpty, (0...1).contains(player) else { return }
        state.playerNames[player] = name
    }

    func updateFirstServer(_ player: Int) {
        guard state.records.isEmpty, (0...1).contains(player) else { return }
        state.firstServer = player
    }

    func addPoint(winner: Int, outcome: PointOutcome) {
        guard (0...1).contains(winner) else { return }

        let currentScore = score
        guard !currentScore.isFinished,
              outcome.isAllowed(pointWinner: winner, server: currentScore.server) else {
            return
        }

        state.records.append(
            PointRecord(winnerIndex: winner, outcome: outcome)
        )
    }

    func undo() {
        _ = state.records.popLast()
    }

    func startNewMatch() {
        state = MatchState(
            playerNames: state.playerNames,
            firstServer: state.firstServer,
            records: []
        )
    }

    func pointsWon(by player: Int) -> Int {
        state.records.filter { $0.winnerIndex == player }.count
    }

    func count(_ outcome: PointOutcome, for player: Int) -> Int {
        state.records.filter { record in
            guard record.outcome == outcome else { return false }
            let attributed = record.outcome.isError ? 1 - record.winnerIndex : record.winnerIndex
            return attributed == player
        }.count
    }

    private func save() {
        guard let data = try? JSONEncoder().encode(state) else { return }
        UserDefaults.standard.set(data, forKey: Self.storageKey)
    }
}

// MARK: - Main screen

struct PendingPoint: Identifiable {
    let id = UUID()
    let winner: Int
    let server: Int
}

struct MatchView: View {
    @StateObject private var viewModel = MatchViewModel()
    @AppStorage("TennisScoreTracker.advancedMode") private var advancedMode = false

    @State private var pendingPoint: PendingPoint?
    @State private var showNewMatchConfirmation = false

    var body: some View {
        let score = viewModel.score

        NavigationStack {
            List {
                setupSection
                scoreboardSection(score)
                pointEntrySection(score)

                if !score.completedSets.isEmpty {
                    completedSetsSection(score)
                }

                statisticsSection
                historySection
            }
            .navigationTitle("Tennis Score Tracker")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .navigationBarLeading) {
                    Button {
                        viewModel.undo()
                    } label: {
                        Label("Undo", systemImage: "arrow.uturn.backward")
                    }
                    .disabled(viewModel.state.records.isEmpty)
                }

                ToolbarItem(placement: .navigationBarTrailing) {
                    Button("New") {
                        showNewMatchConfirmation = true
                    }
                }
            }
            .confirmationDialog(
                "Start a new match?",
                isPresented: $showNewMatchConfirmation,
                titleVisibility: .visible
            ) {
                Button("Start New Match", role: .destructive) {
                    viewModel.startNewMatch()
                }
                Button("Cancel", role: .cancel) {}
            } message: {
                Text("This clears the current score and point history.")
            }
            .sheet(item: $pendingPoint) { point in
                PointDetailView(
                    playerNames: [
                        viewModel.name(for: 0),
                        viewModel.name(for: 1)
                    ],
                    winner: point.winner,
