enum PointOutcome: String, CaseIterable, Identifiable, Codable {
  case none = "No detail"
  case winner = "Winner"
  case unforcedError = "Unforced Error"
  case forcedError = "Forced Error"
  case ace = "Ace"
  case returnWinner = "Return Winner"
  case serveWinner = "Serve Winner"
  var isError: Bool { self == .unforcedError || self == .forcedError }
  func isAllowed(pointWinner: Int, server: Int) -> Bool { switch self { case .ace, .serveWinner: return pointWinner == server; case .returnWinner: return pointWinner != server; default: return true } }
}

struct PointRecord: Identifiable, Codable { var id = UUID(); var date = Date(); var winnerIndex: Int; var outcome: PointOutcome }

struct SetResult: Codable { var games: [Int]; var tiebreak: [Int]?; var winner: Int { games[0] > games[1] ? 0 : 1 } }

struct TennisScore { 
 private(set) var completedSets: [SetResult] = []
 private(set) var games = [0,0]
 private(set) var points = [0,0]
 private var nextGameServer: Int
 init(firstServer: Int) { nextGameServer = firstServer }
 var setWins: [Int] { [completedSets.filter{$0.winner==0}.count, completedSets.filter{$0.winner==1}.count] }
 var matchWinner: Int? { setWins.firstIndex(of: 2) } // firstIndex where ==2 maybe
 var isFinished: Bool { matchWinner != nil }
 var isTiebreak: Bool { !isFinished && games[0] == 6 && games[1] == 6 }
 var currentSetNumber: Int { min(completedSets.count + 1, 3) } // but if finished? okay.
 var server: Int { if !isTiebreak { return nextGameServer }; let total = points[0]+points[1]; let offset = ((total + 1)/2) % 2; return (nextGameServer + offset) % 2 }
 func pointDisplay(for player: Int) -> String { if isFinished { return "-" }; if isTiebreak { return "\(points[player])" }; if points[0] >= 3 && points[1] >= 3 { if points[player] == points[1-player] { return "40" }; return points[player] > points[1-player] ? "AD" : "40" } return ["0","15","30","40"][min(points[player],3)] }
 mutating func awardPoint(to player: Int) { guard !isFinished, (0...1).contains(player) else { return }; points[player]+=1; let opp = 1-player; if isTiebreak { if points[player] >= 7 && points[player]-points[opp] >= 2 { let tb = points; games[player]+=1; nextGameServer = 1 - nextGameServer; finishSet(tiebreak: tb) }; return }; if points[player] >= 4 && points[player]-points[opp] >= 2 { games[player]+=1; points=[0,0]; nextGameServer = 1-nextGameServer; if games[player] >= 6 && games[player]-games[opp] >= 2 { finishSet(tiebreak: nil) } } }
