<?php

namespace Drupal\example\Plugin\Block;

use Drupal\Core\Block\BlockBase;
use Drupal\Core\Cache\Cache;
use Drupal\Core\Entity\EntityTypeManagerInterface;
use Drupal\Core\Plugin\ContainerFactoryPluginInterface;
use Drupal\node\NodeInterface;
use Symfony\Component\DependencyInjection\ContainerInterface;

/**
 * Provides a Bootstrap-styled teaser list of articles tagged "foobar".
 *
 * @Block(
 *   id = "article_foobar_teaser_list",
 *   admin_label = @Translation("Article foobar teaser list"),
 *   category = @Translation("Custom")
 * )
 */
class ArticleFoobarTeaserListBlock extends BlockBase implements ContainerFactoryPluginInterface {

  /**
   * The entity type manager.
   *
   * @var \Drupal\Core\Entity\EntityTypeManagerInterface
   */
  protected $entityTypeManager;

  /**
   * Constructs a new ArticleFoobarTeaserListBlock object.
   *
   * @param array $configuration
   *   A configuration array containing information about the plugin instance.
   * @param string $plugin_id
   *   The plugin ID for the plugin instance.
   * @param mixed $plugin_definition
   *   The plugin implementation definition.
   * @param \Drupal\Core\Entity\EntityTypeManagerInterface $entity_type_manager
   *   The entity type manager service.
   */
  public function __construct(array $configuration, $plugin_id, $plugin_definition, EntityTypeManagerInterface $entity_type_manager) {
    parent::__construct($configuration, $plugin_id, $plugin_definition);
    $this->entityTypeManager = $entity_type_manager;
  }

  /**
   * {@inheritdoc}
   */
  public static function create(ContainerInterface $container, array $configuration, $plugin_id, $plugin_definition) {
    return new static(
      $configuration,
      $plugin_id,
      $plugin_definition,
      $container->get('entity_type.manager')
    );
  }

  /**
   * {@inheritdoc}
   */
  public function build() {
    $term_storage = $this->entityTypeManager->getStorage('taxonomy_term');
    $node_storage = $this->entityTypeManager->getStorage('node');

    $build = [
      '#type' => 'container',
      '#attributes' => [
        'class' => ['article-foobar-teasers', 'my-4'],
      ],
      '#cache' => [
        'tags' => Cache::mergeTags(
          $this->entityTypeManager->getDefinition('node')->getListCacheTags(),
          $this->entityTypeManager->getDefinition('taxonomy_term')->getListCacheTags()
        ),
        'contexts' => [
          'user.node_grants:view',
          'languages:language_content',
          'languages:language_interface',
        ],
      ],
    ];

    // Resolve the tag term ID(s). For best performance, store/configure the
    // term ID directly and skip this lookup.
    $term_ids = $term_storage->getQuery()
      ->accessCheck(TRUE)
      ->condition('vid', 'tags')
      ->condition('name', 'foobar')
      ->execute();

    if (!$term_ids) {
      $build['empty'] = $this->buildEmptyMessage();
      return $build;
    }

    $nids = $node_storage->getQuery()
      ->accessCheck(TRUE)
      ->condition('type', 'article')
      ->condition('status', NodeInterface::PUBLISHED)
      ->condition('field_tags.target_id', array_values($term_ids), 'IN')
      ->sort('created', 'DESC')
      ->sort('nid', 'DESC')
      ->range(0, 10)
      ->execute();

    if (!$nids) {
      $build['empty'] = $this->buildEmptyMessage();
      return $build;
    }

    $nodes = $node_storage->loadMultiple($nids);

    // Preserve the order returned by the entity query.
    $ordered_nodes = [];
    foreach ($nids as $nid) {
      if (isset($nodes[$nid])) {
        $ordered_nodes[$nid] = $nodes[$nid];
      }
    }

    $teasers = $this->entityTypeManager
      ->getViewBuilder('node')
      ->viewMultiple($ordered_nodes, 'teaser');

    $build['list'] = [
      '#type' => 'container',
      '#attributes' => [
        'class' => ['list-group'],
      ],
    ];

    foreach ($ordered_nodes as $nid => $node) {
      if (!isset($teasers[$nid])) {
        continue;
      }

      $build['list'][$nid] = [
        '#type' => 'container',
        '#attributes' => [
          'class' => ['list-group-item', 'py-4'],
        ],
        'teaser' => $teasers[$nid],
      ];
    }

    return $build;
  }

  /**
   * Builds the empty message render array.
   *
   * @return array
   *   A render array.
   */
  protected function buildEmptyMessage() {
    return [
      '#type' => 'container',
      '#attributes' => [
        'class' => ['alert', 'alert-info'],
      ],
      'message' => [
        '#plain_text' => $this->t('No published articles tagged with “foobar” were found.'),
      ],
    ];
  }

}

