<?php

namespace Drupal\foobar_articles\Controller;

use Drupal\Core\Cache\Cache;
use Drupal\Core\Controller\ControllerBase;
use Drupal\Core\Entity\EntityTypeManagerInterface;
use Drupal\node\NodeInterface;
use Symfony\Component\DependencyInjection\ContainerInterface;

/**
 * Controller to list article teasers tagged with "foobar".
 */
class TaggedArticlesController extends ControllerBase {

  /**
   * The entity type manager.
   *
   * @var \Drupal\Core\Entity\EntityTypeManagerInterface
   */
  protected $entityTypeManager;

  /**
   * Constructs a TaggedArticlesController object.
   *
   * @param \Drupal\Core\Entity\EntityTypeManagerInterface $entity_type_manager
   *   The entity type manager.
   */
  public function __construct(EntityTypeManagerInterface $entity_type_manager) {
    $this->entityTypeManager = $entity_type_manager;
  }

  /**
   * {@inheritdoc}
   */
  public static function create(ContainerInterface $container) {
    return new static(
      $container->get('entity_type.manager')
    );
  }

  /**
   * Builds a Bootstrap 5 teaser list of articles tagged with foobar.
   *
   * @return array
   *   A render array.
   */
  public function build() {
    $term_storage = $this->entityTypeManager->getStorage('taxonomy_term');
    $node_storage = $this->entityTypeManager->getStorage('node');

    // Find the term ID(s) without loading full term entities.
    $term_ids = $term_storage->getQuery()
      ->accessCheck(TRUE)
      ->condition('vid', 'tags')
      ->condition('name', 'foobar')
      ->execute();

    $build = [
      '#type' => 'container',
      '#attributes' => ['class' => ['container', 'my-4']],
      '#cache' => [
        'tags' => Cache::mergeTags(
          $node_storage->getEntityType()->getListCacheTags(),
          $term_storage->getEntityType()->getListCacheTags()
        ),
        'contexts' => [
          'languages:language_content',
          'languages:language_interface',
          'url.query_args.pagers',
          'user.node_grants:view',
          'user.permissions',
        ],
      ],
    ];

    if (empty($term_ids)) {
      $build['empty'] = [
        '#plain_text' => $this->t('No articles tagged "foobar" were found.'),
        '#attributes' => ['class' => ['alert', 'alert-info']],
      ];
      return $build;
    }

    $node_ids = $node_storage->getQuery()
      ->accessCheck(TRUE)
      ->condition('type', 'article')
      ->condition('status', NodeInterface::PUBLISHED)
      ->condition('field_tags.target_id', array_values($term_ids), 'IN')
      ->sort('created', 'DESC')
      ->sort('nid', 'DESC')
      ->pager(10)
      ->execute();

    if (empty($node_ids)) {
      $build['empty'] = [
        '#plain_text' => $this->t('No articles tagged "foobar" were found.'),
        '#attributes' => ['class' => ['alert', 'alert-info']],
      ];
      return $build;
    }

    $loaded_nodes = $node_storage->loadMultiple($node_ids);
    $nodes = [];
    foreach ($node_ids as $node_id) {
      if (isset($loaded_nodes[$node_id])) {
        $nodes[$node_id] = $loaded_nodes[$node_id];
      }
    }

    $teasers = $this->entityTypeManager
      ->getViewBuilder('node')
      ->viewMultiple($nodes, 'teaser');

    $items = [];
    foreach ($nodes as $node_id => $node) {
      $items[] = [
        'data' => $teasers[$node_id],
        'attributes' => ['class' => ['list-group-item', 'py-4']],
      ];
    }

    $build['articles'] = [
      '#theme' => 'item_list',
      '#list_type' => 'ul',
      '#items' => $items,
      '#attributes' => ['class' => ['list-group', 'list-group-flush']],
    ];

    $build['pager'] = [
      '#type' => 'pager',
    ];

    // If Bootstrap 5 is not already provided by the active theme, attach a
    // library that provides it. See foobar_articles.libraries.yml.
    // $build['#attached']['library'][] = 'foobar_articles/bootstrap5';

    return $build;
  }

}

