## My answer

A robust implementation should distinguish between:

1. **Numeric Excel cells**  
   Excel numeric cells are stored as numbers, normally exposed by QXlsx as a numeric `QVariant`, usually `double`. In that case, base notation is irrelevant: `42.0` is valid, `42.5` is invalid.

2. **Text Excel cells**  
   If the cell contains text, then we can parse representations such as:
   - decimal: `42`, `42.0`, `4.2e1`
   - hexadecimal: `0x2A`
   - binary: `0b101010`
   - octal: `0o52` or traditional C-style leading zero `052`

Important assumption used below: an integer-only text value with a leading zero is treated as **octal**, so `"010"` means octal `8` and is therefore invalid. If you want leading zeros to be decimal instead, change that one rule.

```cpp
#include <QCoreApplication>
#include <QDebug>
#include <QMetaType>
#include <QRegularExpression>
#include <QString>
#include <QVariant>

#include "xlsxdocument.h"

namespace {

constexpr int AllowedValues[] = {0, 1, 2, 3, 10, 11, 42};

bool isAllowedInteger(qulonglong value)
{
    for (int allowed : AllowedValues) {
        if (value == static_cast<qulonglong>(allowed))
            return true;
    }
    return false;
}

bool isAllowedDouble(double value)
{
    // Exact comparison is appropriate here because the allowed values are
    // small integers and are exactly representable as double.
    for (int allowed : AllowedValues) {
        if (value == static_cast<double>(allowed))
            return true;
    }
    return false;
}

bool isAllowedBaseInteger(const QString &digits, int base, bool negative)
{
    if (digits.isEmpty())
        return false;

    // Reject whitespace, signs, suffixes, separators, etc.
    // The actual base-specific digit validation is done by toULongLong().
    static const QRegularExpression possibleDigits(
        QStringLiteral(R"(\A[0-9a-fA-F]+\z)"));

    if (!possibleDigits.match(digits).hasMatch())
        return false;

    bool ok = false;
    const qulonglong value = digits.toULongLong(&ok, base);

    if (!ok)
        return false;

    // Allowed values are non-negative. Accept -0 as 0.
    if (negative && value != 0)
        return false;

    return isAllowedInteger(value);
}

// Checks decimal text without rounding through double.
// This prevents values like "42.0000000000000000000001" from being
// accidentally rounded to 42.
bool isAllowedDecimalText(const QString &text)
{
    static const QRegularExpression decimal(
        QStringLiteral(
            R"(\A([+-]?)(?:([0-9]+)(?:\.([0-9]*))?|\.([0-9]+))(?:[eE]([+-]?[0-9]+))?\z)"));

    const auto match = decimal.match(text);
    if (!match.hasMatch())
        return false;

    const QString sign = match.captured(1);
    const QString integerPart = match.captured(2);
    const QString fractionPart =
        integerPart.isEmpty() ? match.captured(4) : match.captured(3);

    QString digits = integerPart + fractionPart;

    int firstNonZero = 0;
    while (firstNonZero < digits.size()
           && digits.at(firstNonZero) == QLatin1Char('0')) {
        ++firstNonZero;
    }

    // +0, -0, 0.0, 0e123, etc. are all zero.
    if (firstNonZero == digits.size())
        return true;

    // Non-zero negative values are not allowed.
    if (sign == QStringLiteral("-"))
        return false;

    digits.remove(0, firstNonZero);

    bool ok = true;
    qlonglong exponent = 0;
    if (!match.captured(5).isEmpty()) {
        exponent = match.captured(5).toLongLong(&ok, 10);
        if (!ok)
            return false;
    }

    const int fractionLength = fractionPart.size();

    // Normalize coefficient by removing trailing zeros.
    int trailingZeros = 0;
    while (digits.endsWith(QLatin1Char('0'))) {
        digits.chop(1);
        ++trailingZeros;
    }

    // Value represented by text is:
    // digits * 10^(exponent - fractionLength + trailingZeros)
    for (int allowed : AllowedValues) {
        if (allowed == 0)
            continue;

        QString target = QString::number(allowed);

        int targetZeros = 0;
        while (target.endsWith(QLatin1Char('0'))) {
            target.chop(1);
            ++targetZeros;
        }

        if (digits == target
            && exponent == qlonglong(fractionLength) - trailingZeros + targetZeros) {
            return true;
        }
    }

    return false;
}

bool isAllowedText(QString text)
{
    text = text.trimmed();
    if (text.isEmpty())
        return false;

    bool negative = false;

    if (text.startsWith(QLatin1Char('+')) || text.startsWith(QLatin1Char('-'))) {
        negative = text.startsWith(QLatin1Char('-'));
        text.remove(0, 1);
    }

    if (text.isEmpty())
        return false;

    // Hexadecimal: 0x2A
    if (text.startsWith(QStringLiteral("0x"), Qt::CaseInsensitive))
        return isAllowedBaseInteger(text.mid(2), 16, negative);

    // Binary: 0b101010
    if (text.startsWith(QStringLiteral("0b"), Qt::CaseInsensitive))
        return isAllowedBaseInteger(text.mid(2), 2, negative);

    // Octal with explicit prefix: 0o52
    if (text.startsWith(QStringLiteral("0o"), Qt::CaseInsensitive))
        return isAllowedBaseInteger(text.mid(2), 8, negative);

    // Integer-only text.
    static const QRegularExpression plainInteger(
        QStringLiteral(R"(\A[0-9]+\z)"));

    if (plainInteger.match(text).hasMatch()) {
        // Convention: a leading zero means octal, except for the single digit "0".
        // Therefore "010" is octal 8 and invalid.
        const int base =
            (text.size() > 1 && text.startsWith(QLatin1Char('0'))) ? 8 : 10;

        return isAllowedBaseInteger(text, base, negative);
    }

    // Decimal floating-point or scientific notation text.
    return isAllowedDecimalText((negative ? QStringLiteral("-") : QString()) + text);
}

bool isAllowedCellValue(const QVariant &value)
{
    if (!value.isValid() || value.isNull())
        return false;

    // Text cells may contain base notation.
    if (value.userType() == QMetaType::QString)
        return isAllowedText(value.toString());

    // Boolean is not a numeric type for this task.
    if (value.userType() == QMetaType::Bool)
        return false;

    // Numeric Excel cells.
    if (value.isNumeric()) {
        bool ok = false;
        const double d = value.toDouble(&ok);
        if (ok)
            return isAllowedDouble(d);
    }

    return false;
}

} // namespace

int main(int argc, char *argv[])
{
    QCoreApplication app(argc, argv);

    const QString xlsxFile = QStringLiteral("table.xlsx");
    const QString cellAddress = QStringLiteral("C7");

    QXlsx::Document doc(xlsxFile);
    if (!doc.load()) {
        qCritical() << "Cannot load workbook:" << xlsxFile;
        return 1;
    }

    const QVariant value = doc.read(cellAddress);
    const bool valid = isAllowedCellValue(value);

    qInfo() << cellAddress << (valid ? "valid" : "invalid");

    return valid ? 0 : 2;
}
```

If your QXlsx version does not provide `read(const QString &)`, use:

```cpp
