A robust solution has to distinguish between:

1. **Numeric Excel cells**  
   Excel/QXlsx normally gives these to you as a numeric `QVariant`, usually `double`.  
   You should accept only values that are exactly one of: `0, 1, 2, 3, 10, 11, 42`.

2. **Text cells containing numeric literals**  
   Excel does not natively store things like `0x2A`, `0b101010`, or `052` as numeric base literals; they will usually be read as `QString`.  
   Therefore, text must be parsed explicitly.

Below is a complete example using **C++**, **Qt**, and **QXlsx**.

> Convention used below:  
> - Hexadecimal: `0x2A` or `0X2A`  
> - Binary: `0b101010` or `0B101010`  
> - Octal: `0o52`, `0O52`, or C-style leading zero `052`  
> - Decimal: `42`, `42.0`, `4.2e1`, etc.  
> - A pure integer text with a leading zero is treated as octal. If you need `"010"` to mean decimal `10`, change that branch to base 10.

```cpp
#include <QCoreApplication>
#include <QDebug>
#include <QMetaType>
#include <QRegularExpression>
#include <QString>
#include <QVariant>
#include <cmath>

#include "xlsxdocument.h"

static bool isAllowedNumber(double value)
{
    static const int allowed[] = {0, 1, 2, 3, 10, 11, 42};

    if (!std::isfinite(value))
        return false;

    for (int v : allowed) {
        if (value == static_cast<double>(v))
            return true;
    }

    return false;
}

static bool validDigits(const QString &s, int base)
{
    if (s.isEmpty())
        return false;

    static const QRegularExpression bin(QStringLiteral(R"(\A[01]+\z)"));
    static const QRegularExpression oct(QStringLiteral(R"(\A[0-7]+\z)"));
    static const QRegularExpression dec(QStringLiteral(R"(\A[0-9]+\z)"));
    static const QRegularExpression hex(QStringLiteral(R"(\A[0-9a-fA-F]+\z)"));

    switch (base) {
    case 2:
        return bin.match(s).hasMatch();
    case 8:
        return oct.match(s).hasMatch();
    case 10:
        return dec.match(s).hasMatch();
    case 16:
        return hex.match(s).hasMatch();
    default:
        return false;
    }
}

static bool isAllowedIntegerMagnitude(const QString &mag, int base, bool negative)
{
    if (!validDigits(mag, base))
        return false;

    bool ok = false;
    const qulonglong u = mag.toULongLong(&ok, base);

    if (!ok || u > 42ULL)
        return false;

    // Only -0 is allowed among negative forms.
    if (negative && u != 0ULL)
        return false;

    return isAllowedNumber(static_cast<double>(u));
}

// Exact decimal-text checking without rounding through double.
// Accepts forms such as: 42, 42.0, .42e2, 4.2e1, 100e-1, etc.
static bool isAllowedDecimalText(const QString &text)
{
    static const QRegularExpression re(QStringLiteral(
        R"(\A([+-]?)(?:([0-9]+)(?:\.([0-9]*))?|\.([0-9]+))(?:[eE]([+-]?[0-9]+))?\z)"
    ));

    const auto m = re.match(text);
    if (!m.hasMatch())
        return false;

    const QString sign = m.captured(1);
    const QString intPart = m.captured(2);
    const QString fracPart = intPart.isEmpty() ? m.captured(4) : m.captured(3);

    QString digits = intPart + fracPart;

    qsizetype firstNonZero = 0;
    while (firstNonZero < digits.size()
           && digits.at(firstNonZero) == QLatin1Char('0')) {
        ++firstNonZero;
    }

    // 0, 0.0, 0e10, -0.000, etc.
    if (firstNonZero == digits.size())
        return true;

    // Allowed set contains no negative nonzero values.
    if (sign == QStringLiteral("-"))
        return false;

    digits.remove(0, firstNonZero);

    bool ok = false;
    qlonglong exponent = 0;

    if (!m.captured(5).isEmpty()) {
        exponent = m.captured(5).toLongLong(&ok, 10);
        if (!ok)
            return false;
    }

    qlonglong trailingZeros = 0;
    while (digits.endsWith(QLatin1Char('0'))) {
        digits.chop(1);
        ++trailingZeros;
    }

    // Value is now: digits * 10^(exponent - fractionLength + trailingZeros)
    const qlonglong power =
        exponent - static_cast<qlonglong>(fracPart.size()) + trailingZeros;

    // Allowed nonzero values normalized:
    // 1  -> digits "1",  power 0
    // 2  -> digits "2",  power 0
    // 3  -> digits "3",  power 0
    // 10 -> digits "1",  power 1
    // 11 -> digits "11", power 0
    // 42 -> digits "42", power 0
    if (power == 0) {
        return digits == QStringLiteral("1")
            || digits == QStringLiteral("2")
            || digits == QStringLiteral("3")
            || digits == QStringLiteral("11")
            || digits == QStringLiteral("42");
    }

    if (power == 1) {
        return digits == QStringLiteral("1"); // 10
    }

    return false;
}

static bool isAllowedText(QString text)
{
    text = text.trimmed();
    if (text.isEmpty())
        return false;

    bool negative = false;

    if (text.startsWith(QLatin1Char('+')) || text.startsWith(QLatin1Char('-'))) {
        negative = text.startsWith(QLatin1Char('-'));
        text.remove(0, 1);

        if (text.isEmpty())
            return false;
    }

    // Hexadecimal
    if (text.startsWith(QStringLiteral("0x"), Qt::CaseInsensitive)) {
        return isAllowedIntegerMagnitude(text.mid(2), 16, negative);
    }

    // Binary
    if (text.startsWith(QStringLiteral("0b"), Qt::CaseInsensitive)) {
        return isAllowedIntegerMagnitude(text.mid(2), 2, negative);
    }

    // Octal with explicit prefix
    if (text.startsWith(QStringLiteral("0o"), Qt::CaseInsensitive)) {
        return isAllowedIntegerMagnitude(text.mid(2), 8, negative);
    }

    // Pure integer text.
    // Convention: leading zero means octal, e.g. "052" == 42.
    // If decimal leading zeros are required, force base 10 here.
    static const QRegularExpression pureInt(QStringLiteral(R"(\A[0-9]+\z)"));

    if (pureInt.match(text).hasMatch()) {
        const int base =
            (text.size() > 1 && text.startsWith(QLatin1Char('0'))) ? 8 : 10;

        return isAllowedIntegerMagnitude(text, base, negative);
    }

    // Decimal floating-point / scientific notation text.
    return isAllowedDecimalText(
        (negative ? QStringLiteral("-") : QString()) + text
    );
}

static bool isAllowedCell(const QVariant &value)
{
    if (!value.isValid() || value.isNull())
        return false;

    const int type = value.userType();

    // Text cell
    if (type == QMetaType::QString)
        return isAllowedText(value.toString());

    // Explicitly reject booleans.
    if (type == QMetaType::Bool)
        return false;

    // Numeric cell
    if (value.isNumeric()) {
        bool ok = false;
        const double d = value.toDouble(&ok);
        return ok && isAllowedNumber(d);
    }

    // Dates, times, rich text, unsupported formula results, etc.
    return false;
}

int main(int argc, char *argv[])
{
    QCoreApplication app(argc, argv);

    if (argc != 3) {
        qInfo() << "Usage: app file.xlsx cellAddress";
        qInfo() << "Example: app table.xlsx C7";
        return 1;
    }

    const QString filePath = QString::fromLocal8Bit(argv[1]);
    const QString cellAddress = QString::fromLocal8Bit(argv[2]);

    QXlsx::Document xlsx(filePath);

    if (!xlsx.load()) {
        qCritical() << "Cannot load workbook:" << filePath;
        return 1;
    }

    const QVariant cellValue = xlsx.read(cellAddress);
    const bool allowed = isAllowedCell(cellValue);

    qInfo() << cellAddress
            << (allowed ? "allowed" : "not allowed");

    return allowed ? 0 : 1;
}
```

Notes:

- `QXlsx::Document::read()` reads from the currently selected sheet.
- If your “cell number” is row/column instead of an address like `"C7"`, use something like:

```cpp
QXlsx::Cell *cell = xlsx.cellAt(row, column);
QVariant value = cell ? cell->value() : QVariant();
bool allowed = isAllowedCell(value);
```

- QXlsx does not evaluate formulas. If the cell contains a formula, you get the cached result stored in the workbook, if present.

