  <script>
    "use strict";

    const $ = (selector) => document.querySelector(selector);

    const desktop = $("#desktop");
    const tasks = $("#tasks");
    const startMenu = $("#startMenu");
    const startBtn = $("#startBtn");

    const windows = new Map();

    let zIndex = 10;
    let activeWindow = null;
    let selectedFile = null;
    let editorFileName = null;
    let editorDirty = false;
    let toastTimer;

    const STORAGE_KEY = "webos.files.v1";

    function toast(message) {
      const el = $("#toast");
      el.textContent = message;
      el.hidden = false;
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => {
        el.hidden = true;
      }, 2600);
    }

    function loadFiles() {
      try {
        const data = JSON.parse(localStorage.getItem(STORAGE_KEY));
        if (Array.isArray(data)) {
          const seen = new Set();
          return data.filter((file) => {
            if (
              !file ||
              typeof file.name !== "string" ||
              typeof file.content !== "string" ||
              !file.name ||
              seen.has(file.name)
            ) {
              return false;
            }
            seen.add(file.name);
            return true;
          });
        }
      } catch {}

      return [
        {
          name: "readme.txt",
          content: `Welcome to WebOS!

This is a browser-based desktop sample.

- Open Files to create, rename, download, and delete files.
- Open Terminal and type help.
- Files are stored in your browser using localStorage.

This is not a real operating system and cannot access your real file system.`
        }
      ];
    }

    let files = loadFiles();

    function saveFiles() {
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(files));
        return true;
      } catch {
        toast("Could not save files. Browser storage may be unavailable or full.");
        return false;
      }
    }

    function validNewName(name) {
      if (!name) {
        toast("Enter a file name.");
        return false;
      }

      if (name.includes("/") || name.includes("\\")) {
        toast("File name cannot contain slashes.");
        return false;
      }

      if (files.some((file) => file.name === name)) {
        toast("A file with that name already exists.");
        return false;
      }

      return true;
    }

    function createFile(name, content = "") {
      name = String(name || "").trim();

      if (!validNewName(name)) return false;

      files.push({ name, content });

      if (!saveFiles()) {
        files.pop();
        return false;
      }

      renderFiles();
      return true;
    }

    function deleteFileByName(name) {
      const index = files.findIndex((file) => file.name === name);
      if (index === -1) return false;

      const [removed] = files.splice(index, 1);

      if (!saveFiles()) {
        files.splice(index, 0, removed);
        return false;
      }

      if (selectedFile === name) selectedFile = null;

      if (editorFileName === name) {
        editorFileName = null;
        editorDirty = true;
        updateEditorTitle();
      }

      renderFiles();
      return true;
    }

    function renameFile(oldName, newName) {
      newName = String(newName || "").trim();

      if (!newName) {
        toast("Enter a file name.");
        return;
      }

      if (newName === oldName) return;

      if (newName.includes("/") || newName.includes("\\")) {
        toast("File name cannot contain slashes.");
        return;
      }

      if (files.some((file) => file.name === newName)) {
        toast("A file with that name already exists.");
        return;
      }

      const file = files.find((item) => item.name === oldName);
      if (!file) return;

      const previous = file.name;
      file.name = newName;

      if (!saveFiles()) {
        file.name = previous;
        return;
      }

      if (editorFileName === previous) editorFileName = newName;
      if (selectedFile === previous) selectedFile = newName;

      renderFiles();
      updateEditorTitle();
      toast("File renamed.");
    }

    function downloadFile(name) {
      const file = files.find((item) => item.name === name);
      if (!file) return;

      const url = URL.createObjectURL(
        new Blob([file.content], { type: "text/plain;charset=utf-8" })
      );

      const link = document.createElement("a");
      link.href = url;
      link.download = file.name;
      document.body.append(link);
      link.click();
      link.remove();

      setTimeout(() => URL.revokeObjectURL(url), 1000);
    }

    function renderFiles() {
      const list = $("#fileList");
      if (!list) return;

      list.innerHTML = "";

      if (!files.length) {
        const empty = document.createElement("p");
        empty.className = "hint";
        empty.textContent = "No files yet. Create one.";
        list.append(empty);
        return;
      }

      [...files]
        .sort((a, b) => a.name.localeCompare(b.name))
        .forEach((file) => {
          const row = document.createElement("div");
          row.className = "file-row" + (selectedFile === file.name ? " selected" : "");
          row.tabIndex = 0;

          const name = document.createElement("span");
          name.textContent = "📄 " + file.name;

          const size = document.createElement("small");
          size.textContent = file.content.length + " chars";

          row.append(name, size);

          row.addEventListener("click", () => {
            selectedFile = file.name;
            renderFiles();
          });

          row.addEventListener("dblclick", () => {
            openEditor(file.name);
          });

          row.addEventListener("keydown", (event) => {
            if (event.key === "Enter") {
              event.preventDefault();
              openEditor(file.name);
            }

            if (event.key === " ") {
              event.preventDefault();
              selectedFile = file.name;
              renderFiles();
            }
          });

          list.append(row);
        });
    }

    function requireSelectedFile() {
      if (!selectedFile) {
        toast("Select a file first.");
        return null;
      }

      return files.find((file) => file.name === selectedFile) || null;
    }

    function focusWindow(id) {
      const win = windows.get(id);
      if (!win) return;

      win.el.hidden = false;
      win.el.style.zIndex = ++zIndex;
      activeWindow = id;

      windows.forEach((item) => {
        item.el.classList.toggle("active", item.id === id);
        item.task.classList.toggle("active", item.id === id);
      });
    }

    function focusTopWindow() {
      const visible = [...windows.values()]
        .filter((win) => !win.el.hidden)
        .sort((a, b) => Number(b.el.style.zIndex) - Number(a.el.style.zIndex));

      if (visible.length) {
        focusWindow(visible[0].id);
      } else {
        activeWindow = null;
        windows.forEach((win) => {
          win.el.classList.remove("active");
          win.task.classList.remove("active");
        });
      }
    }

    function minimizeWindow(id) {
      const win = windows.get(id);
      if (!win) return;

      win.el.hidden = true;
      win.el.classList.remove("active");
      win.task.classList.remove("active");

      if (activeWindow === id) {
        activeWindow = null;
        focusTopWindow();
      }
    }

    function destroyWindow(id) {
      const win = windows.get(id);
      if (!win) return;

      win.el.remove();
      win.task.remove();
      windows.delete(id);

      if (activeWindow === id) {
        activeWindow = null;
        focusTopWindow();
      }
    }

    function toggleMaximize(win) {
      win.el.classList.toggle("maximized");
      focusWindow(win.id);
    }

    function makeDraggable(el, handle) {
      handle.addEventListener("pointerdown", (event) => {
        if (
          event.button !== 0 ||
          event.target.closest("button") ||
          el.classList.contains("maximized")
        ) {
          return;
        }

        const startX = event.clientX;
        const startY = event.clientY;
        const startLeft = el.offsetLeft;
        const startTop = el.offsetTop;

        handle.setPointerCapture(event.pointerId);

        const move = (e) => {
          const maxLeft = desktop.clientWidth - el.offsetWidth;
          const maxTop = desktop.clientHeight - handle.offsetHeight;

          el.style.left =
            Math.max(0, Math.min(maxLeft, startLeft + e.clientX - startX)) + "px";
          el.style.top =
            Math.max(0, Math.min(maxTop, startTop + e.clientY - startY)) + "px";
        };

        const stop = () => {
          handle.removeEventListener("pointermove", move);
          handle.removeEventListener("pointerup", stop);
          handle.removeEventListener("pointercancel", stop);
        };

        handle.addEventListener("pointermove", move);
        handle.addEventListener("pointerup", stop);
        handle.addEventListener("pointercancel", stop);
      });
    }

    function makeResizable(el, handle) {
      handle.addEventListener("pointerdown", (event) => {
        if (event.button !== 0 || el.classList.contains("maximized")) return;

        const startX = event.clientX;
        const startY = event.clientY;
        const startWidth = el.offsetWidth;
        const startHeight = el.offsetHeight;

        handle.setPointerCapture(event.pointerId);

        const move = (e) => {
          el.style.width = Math.max(300, startWidth + e.clientX - startX) + "px";
          el.style.height = Math.max(200, startHeight + e.clientY - startY) + "px";
        };

        const stop = () => {
          handle.removeEventListener("pointermove", move);
          handle.removeEventListener("pointerup", stop);
          handle.removeEventListener("pointercancel", stop);
        };

        handle.addEventListener("pointermove", move);
        handle.addEventListener("pointerup", stop);
        handle.addEventListener("pointercancel", stop);
      });
    }

    function createWindow(id, title, width = 560, height = 380) {
      if (windows.has(id)) {
        focusWindow(id);
        return windows.get(id);
      }

      const el = document.createElement("section");
      el.className = "window";

      const w = Math.min(width, desktop.clientWidth - 24);
      const h = Math.min(height, desktop.clientHeight - 24);

      el.style.width = w + "px";
      el.style.height = h + "px";

      const offset = (windows.size * 34) % 170;

      el.style.left =
        Math.max(10, Math.min(70 + offset, desktop.clientWidth - w - 10)) + "px";
      el.style.top =
        Math.max(10, Math.min(50 + offset, desktop.clientHeight - h - 10)) + "px";
      el.style.zIndex = ++zIndex;

      el.innerHTML = `
        <header class="titlebar">
          <span class="title"></span>
          <div class="controls">
            <button class="min" aria-label="Minimize">–</button>
            <button class="max" aria-label="Maximize">□</button>
            <button class="close" aria-label="Close">×</button>
          </div>
        </header>
        <main class="body"></main>
        <div class="resize" aria-hidden="true"></div>
      `;

      el.querySelector(".title").textContent = title;

      const task = document.createElement("button");
      task.className = "task";
      task.textContent = title;
      tasks.append(task);

      const win = {
        id,
        el,
        task,
        body: el.querySelector(".body"),
        titleEl: el.querySelector(".title"),
        onClose: null,
        ready: false
      };

      windows.set(id, win);

      const titlebar = el.querySelector(".titlebar");

      titlebar.addEventListener("dblclick", (event) => {
        if (!event.target.closest("button")) toggleMaximize(win);
      });

      makeDraggable(el, titlebar);
      makeResizable(el, el.querySelector(".resize"));

      el.addEventListener("pointerdown", () => focusWindow(id));

      task.addEventListener("click", () => {
        if (activeWindow === id && !el.hidden) {
          minimizeWindow(id);
        } else {
          focusWindow(id);
        }
      });

      el.querySelector(".min").addEventListener("click", () => minimizeWindow(id));
      el.querySelector(".max").addEventListener("click", () => toggleMaximize(win));

      el.querySelector(".close").addEventListener("click", () => {
        if (win.onClose && win.onClose() === false) return;
        destroyWindow(id);
      });

      desktop.append(el);
      focusWindow(id);

      return win;
    }

    function openFiles() {
      const win = createWindow("files", "📁 Files", 640, 420);

      if (!win.ready) {
        win.body.innerHTML = `
          <div class="toolbar">
            <button data-action="new">New</button>
            <button data-action="open">Open</button>
            <button data-action="rename">Rename</button>
            <button data-action="download">Download</button>
            <button data-action="delete">Delete</button>
          </div>
          <p class="hint">Sample virtual file system. Double-click a file to open it.</p>
          <div id="fileList" class="file-list"></div>
        `;

        win.body.querySelector('[data-action="new"]').addEventListener("click", () => {
          const name = prompt("New file name:", "untitled.txt");
          if (name === null) return;

          const trimmed = name.trim();

          if (createFile(trimmed)) {
            selectedFile = trimmed;
            renderFiles();
            openEditor(trimmed);
          }
        });

        win.body.querySelector('[data-action="open"]').addEventListener("click", () => {
          const file = requireSelectedFile();
          if (file) openEditor(file.name);
        });

        win.body.querySelector('[data-action="rename"]').addEventListener("click", () => {
          const file = requireSelectedFile();
          if (!file) return;

          const name = prompt("Rename file:", file.name);
          if (name === null) return;

          renameFile(file.name, name);
        });

        win.body.querySelector('[data-action="download"]').addEventListener("click", () => {
          const file = requireSelectedFile();
          if (file) downloadFile(file.name);
        });

        win.body.querySelector('[data-action="delete"]').addEventListener("click", () => {
          const file = requireSelectedFile();
          if (!file) return;

          if (confirm(`Delete "${file.name}"?`)) {
            deleteFileByName(file.name);
          }
        });

        win.ready = true;
      }

      renderFiles();
      focusWindow("files");
    }

    function openEditor(fileName = null) {
      const existing = windows.get("editor");

      if (existing && fileName === null) {
        focusWindow("editor");
        return;
      }

      if (fileName !== null) {
        const file = files.find((item) => item.name === fileName);

        if (!file) {
          toast("File not found.");
          return;
        }

        if (existing && editorFileName === fileName) {
          focusWindow("editor");
          return;
        }

        if (
          editorDirty &&
          editorFileName !== fileName &&
          !confirm("Discard unsaved changes?")
        ) {
          return;
        }
      }

      const win = existing || createWindow("editor", "📝 Editor", 580, 420);

      if (!win.ready) buildEditor(win);

      const textarea = win.body.querySelector("textarea");

      if (fileName !== null) {
        const file = files.find((item) => item.name === fileName);
        textarea.value = file ? file.content : "";
        editorFileName = fileName;
        editorDirty = false;
      } else if (!existing) {
        textarea.value = "";
        editorFileName = null;
        editorDirty = false;
      }

      updateEditorTitle();
      focusWindow("editor");
      textarea.focus();
    }

    function buildEditor(win) {
      win.body.innerHTML = `
        <div class="editor">
          <div class="toolbar">
            <button data-action="save">Save</button>
            <button data-action="save-as">Save As</button>
            <button data-action="new">New</button>
          </div>
          <textarea spellcheck="false" aria-label="Text editor"></textarea>
          <div class="status">Ctrl+S / Cmd+S saves when the editor is active.</div>
        </div>
      `;

      const textarea = win.body.querySelector("textarea");

      textarea.addEventListener("input", () => {
        editorDirty = true;
        updateEditorTitle();
      });

      win.body.querySelector('[data-action="save"]').addEventListener("click", () => {
        saveEditor(false);
      });

      win.body.querySelector('[data-action="save-as"]').addEventListener("click", () => {
        saveEditor(true);
      });

      win.body.querySelector('[data-action="new"]').addEventListener("click", () => {
        if (editorDirty && !confirm("Discard unsaved changes?")) return;

        textarea.value = "";
        editorFileName = null;
        editorDirty = false;

        updateEditorTitle();
        textarea.focus();
      });

      win.onClose = () => {
        if (editorDirty && !confirm("Discard unsaved changes?")) return false;

        editorFileName = null;
        editorDirty = false;

        return true;
      };

      win.ready = true;
    }

    function updateEditorTitle() {
      const win = windows.get("editor");
      if (!win) return;

      const name = editorFileName || "Untitled";
      const title = `📝 ${name}${editorDirty ? " •" : ""}`;

      win.titleEl.textContent = title;
      win.task.textContent = title;
    }

    function saveEditor(saveAs = false) {
      const win = windows.get("editor");
      if (!win) return;

      const textarea = win.body.querySelector("textarea");
      const content = textarea.value;

      let target = editorFileName;

      if (saveAs || !target) {
        const answer = prompt("Save file as:", target || "untitled.txt");
        if (answer === null) return;

        target = answer.trim();

        if (!target) {
          toast("Enter a file name.");
          return;
        }
      }

      if (target.includes("/") || target.includes("\\")) {
        toast("File name cannot contain slashes.");
        return;
      }

      const existingFile = files.find((file) => file.name === target);

      if (
        existingFile &&
        existingFile.name !== editorFileName &&
        !confirm(`"${target}" already exists. Overwrite?`)
      ) {
        return;
      }

      if (existingFile) {
        const oldContent = existingFile.content;
        existingFile.content = content;

        if (!saveFiles()) {
          existingFile.content = oldContent;
          return;
        }
      } else {
        files.push({ name: target, content });

        if (!saveFiles()) {
          files.pop();
          return;
        }
      }

      editorFileName = target;
      editorDirty = false;
      selectedFile = target;

      renderFiles();
      updateEditorTitle();
      toast("File saved.");
    }

    function openTerminal() {
      const win = createWindow("terminal", "⌨️ Terminal", 620, 400);

      if (!win.ready) {
        buildTerminal(win);
        win.ready = true;
      }

      focusWindow("terminal");
      win.body.querySelector("input")?.focus();
    }

    function buildTerminal(win) {
      win.body.innerHTML = `
        <div class="terminal">
          <pre class="terminal-output" aria-live="polite"></pre>
          <form autocomplete="off">
            <span>guest@webos:~$</span>
            <input aria-label="Terminal command" spellcheck="false" />
          </form>
        </div>
      `;

      const output = win.body.querySelector(".terminal-output");
      const input = win.body.querySelector("input");

      const print = (text) => {
        output.textContent += text + "\n";
        output.scrollTop = output.scrollHeight;
      };

      print("WebOS terminal. Type help.");

      win.body.querySelector("form").addEventListener("submit", (event) => {
        event.preventDefault();

        const line = input.value.trim();
        input.value = "";

        if (!line) return;

        print("$ " + line);

        const match = line.match(/^(\S+)(?:\s+(.*))?$/);
        if (!match) return;

        const command = match[1].toLowerCase();
        const arg = (match[2] || "").trim();
        const file = files.find((item) => item.name === arg);

        switch (command) {
          case "help":
            print(
              `help              Show this help
ls                List files
cat FILE          Show file contents
touch FILE        Create an empty file
rm FILE           Delete a file
edit FILE         Open a file in the editor
echo TEXT         Print text
date              Show date and time
whoami            Show current user
clear             Clear terminal
about             About WebOS

This terminal simulates commands inside the browser.`
            );
            break;

          case "ls":
            print(files.length ? files.map((item) => item.name).join("\n") : "(empty)");
            break;

          case "cat":
            if (!arg) {
              print("Usage: cat FILE");
            } else {
              print(file ? file.content : "File not found.");
            }
            break;

          case "touch":
            if (!arg) {
              print("Usage: touch FILE");
            } else if (file) {
              print("File already exists.");
            } else {
              print(createFile(arg) ? "File created." : "Could not create file.");
            }
            break;

          case "rm":
            if (!arg) {
              print("Usage: rm FILE");
            } else if (!file) {
              print("File not found.");
            } else if (confirm(`Delete "${arg}"?`)) {
              print(deleteFileByName(arg) ? "File deleted." : "Could not delete file.");
            } else {
              print("Canceled.");
            }
            break;

          case "edit":
            if (file) {
              openEditor(file.name);
            } else {
              print("File not found.");
            }
            break;

          case "echo":
            print(arg);
            break;

          case "date":
            print(new Date().toLocaleString());
            break;

          case "whoami":
            print("guest");
            break;

          case "clear":
            output.textContent = "";
            break;

          case "about":
            print("WebOS is a small HTML/CSS/JS desktop simulation.");
            break;

          default:
            print(`Unknown command: ${command}. Type help.`);
        }
      });
    }

    function openAbout() {
      const win = createWindow("about", "ℹ️ About", 480, 360);

      if (!win.ready) {
        win.body.innerHTML = `
          <div class="page">
            <h2>WebOS</h2>
            <p>A small operating-system-style desktop built with HTML, CSS, and JavaScript.</p>
            <ul>
              <li>Windows: drag, resize, minimize, maximize, close</li>
              <li>File manager: create, rename, download, delete</li>
              <li>Text editor with save and dirty-state tracking</li>
              <li>Simulated terminal</li>
            </ul>
            <p>Files are stored in localStorage and are not real system files.</p>
          </div>
        `;
        win.ready = true;
      }

      focusWindow("about");
    }

    const apps = [
      { title: "Files", icon: "📁", open: openFiles },
      { title: "Text Editor", icon: "📝", open: () => openEditor() },
      { title: "Terminal", icon: "⌨️", open: openTerminal },
      { title: "About", icon: "ℹ️", open: openAbout }
    ];

    const icons = $("#icons");

    apps.forEach((app) => {
      const desktopIcon = document.createElement("button");
      desktopIcon.className = "desktop-icon";

      const glyph = document.createElement("span");
      glyph.className = "icon";
      glyph.textContent = app.icon;
      glyph.setAttribute("aria-hidden", "true");

      const label = document.createElement("span");
      label.textContent = app.title;

      desktopIcon.append(glyph, label);
      desktopIcon.addEventListener("click", app.open);
      icons.append(desktopIcon);

      const startItem = document.createElement("button");
      startItem.className = "start-item";
      startItem.textContent = `${app.icon} ${app.title}`;
      startItem.addEventListener("click", () => {
        setStart(false);
        app.open();
      });

      startMenu.append(startItem);
    });

    function setStart(open) {
      startMenu.hidden = !open;
      startBtn.setAttribute("aria-expanded", String(open));
    }

    startBtn.addEventListener("click", (event) => {
      event.stopPropagation();
      setStart(startMenu.hidden);
    });

    document.addEventListener("pointerdown", (event) => {
      if (!startMenu.hidden && !event.target.closest("#startMenu, #startBtn")) {
        setStart(false);
      }
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        setStart(false);
      }

      if (
        (event.ctrlKey || event.metaKey) &&
        event.key.toLowerCase() === "s" &&
        activeWindow === "editor"
      ) {
        event.preventDefault();
        saveEditor(false);
      }
    });

    window.addEventListener("resize", () => {
      windows.forEach((win) => {
        if (win.el.classList.contains("maximized")) return;

        const maxLeft = desktop.clientWidth - win.el.offsetWidth;
        const maxTop = desktop.clientHeight - 44;

        win.el.style.left =
          Math.max(0, Math.min(win.el.offsetLeft, maxLeft)) + "px";
        win.el.style.top =
          Math.max(0, Math.min(win.el.offsetTop, maxTop)) + "px";
      });
    });

    function updateClock() {
      const now = new Date();
      $("#clock").textContent = now.toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit"
      });
    }

    updateClock();
    setInterval(updateClock, 1000);

    openAbout();
  </script>
</body>
</html>
```

Evaluation:

Assistant A provides a much more complete solution. It includes a full GUI, taskbar, start menu, window dragging, minimizing/maximizing, file management with create/rename/delete/download, persistent localStorage files, a text editor, terminal, settings, and About app. It closely matches the requested “simple operating system emulator” and is immediately usable. Minor improvement would be adding a custom resize handle instead of relying only on CSS `resize`, because browser support and discoverability can vary, but the overall implementation is strong.

Assistant B provides a very basic example, but it is much less complete. It uses external placeholder images, which makes it less self-contained and potentially broken offline. Its file management is essentially read-only: it lists files and opens them, but does not support saving edits, creating, renaming, deleting, or persistence. Window management is also limited: dragging and closing exist, but there is no minimize/maximize, no start menu, and no robust app/window state management. It is a starting point, but it does not satisfy the prompt as well as Assistant A.

My final verdict is Assistant A is significantly better: [[A>>B]]

