```
#include <Wire.h>
#include <RTClib.h>
#include <U8x8lib.h>

RTC_DS3231 rtc;
U8X8_SSD1306_128X64_NONAME_HW_I2C oled(U8X8_PIN_NONE);

// Config
const bool START_FROM_RTC = false;
const uint8_t START_HOUR = 6;
const uint8_t START_MINUTE = 0;

// Pins
const uint8_t PIN_SHORT_NIGHT = 2;
const uint8_t PIN_SPEED = 3;
const uint8_t PIN_LIVING_LIGHT = 4;
const uint8_t PIN_BEDROOM_LIGHT = 5;
const uint8_t PIN_KITCHEN_LIGHT = 6;
const uint8_t PIN_BATH_LIGHT = 7;
const uint8_t PIN_HALL_LIGHT = 8;
const uint8_t PIN_LIVING_TV = 9;
const uint8_t PIN_BEDROOM_TV = 10;

const uint8_t SPEEDS[] = {1, 2, 3, 6, 12, 24, 60};
const uint8_t SPEED_COUNT = sizeof(SPEEDS) / sizeof(SPEEDS[0]);
uint8_t speedIndex = 3; // 6:1

const uint32_t SECONDS_PER_DAY = 86400UL;
const uint32_t SHORT_NIGHT_RESUME = 6UL * 3600UL;
const uint32_t SHORT_NIGHT_END = 1UL * 3600UL;

uint32_t modelSeconds = 0;
uint32_t lastRtcSeconds = 0;
bool shortNight = false;
const char *eventName = "Starting";
uint32_t lastDisplayMs = 0;

struct TvState {
  uint8_t pin;
  bool enabled;
  bool running;
  uint32_t nextChangeMs;
};

TvState livingTv = {PIN_LIVING_TV, false, false, 0};
TvState bedroomTv = {PIN_BEDROOM_TV, false, false, 0};

bool betweenMin(uint16_t nowMin, uint16_t startMin, uint16_t endMin) {
  return nowMin >= startMin && nowMin < endMin;
}

void applyShortNight() {
  if (shortNight && modelSeconds >= SHORT_NIGHT_END && modelSeconds < SHORT_NIGHT_RESUME) {
    modelSeconds = SHORT_NIGHT_RESUME;
  }
}

void addModelSeconds(uint32_t add) {
  modelSeconds += add;
  modelSeconds %= SECONDS_PER_DAY;
  applyShortNight();
}

void updateControls() {
  shortNight = (digitalRead(PIN_SHORT_NIGHT) == LOW);
  applyShortNight();

  static bool lastReading = HIGH;
  static bool stableState = HIGH;
  static uint32_t changeMs = 0;
  uint32_t nowMs = millis();
  bool reading = digitalRead(PIN_SPEED);

  if (reading != lastReading) {
    lastReading = reading;
    changeMs = nowMs;
  }

  if ((uint32_t)(nowMs - changeMs) >= 30UL && reading != stableState) {
    stableState = reading;
    if (stableState == LOW) {
      speedIndex = (speedIndex + 1) % SPEED_COUNT;
    }
  }
}

void updateModelClock() {
  static uint32_t lastPollMs = 0;
  uint32_t nowMs = millis();
  if ((uint32_t)(nowMs - lastPollMs) < 200UL) return;
  lastPollMs = nowMs;

  DateTime now = rtc.now();
  uint32_t rtcSeconds = now.unixtime();

  if (rtcSeconds < lastRtcSeconds) {
    lastRtcSeconds = rtcSeconds;
    return;
  }

  uint32_t elapsed = rtcSeconds - lastRtcSeconds;
  lastRtcSeconds = rtcSeconds;

  if (elapsed == 0) return;

  // If the RTC appears to have been set or the sketch was paused a long time,
  // re-anchor instead of making a huge unexpected jump.
  if (elapsed > 10UL) return;

  addModelSeconds(elapsed * SPEEDS[speedIndex]);
}

void updateHouse() {
  uint16_t m = modelSeconds / 60UL;

  // Room lights.
  bool livingLight =
      betweenMin(m, 390, 510) ||    // 06:30-08:30
      betweenMin(m, 1050, 1320);    // 17:30-22:00

  bool bedroomLight =
      betweenMin(m, 360, 420) ||    // 06:00-07:00
      betweenMin(m, 1290, 1320);    // 21:30-22:00

  bool kitchenLight =
      betweenMin(m, 390, 480) ||    // 06:30-08:00
      betweenMin(m, 1050, 1170);    // 17:30-19:30

  bool bathLight =
      betweenMin(m, 375, 405) ||    // 06:15-06:45
      betweenMin(m, 1295, 1315);    // 21:35-21:55

  bool hallLight =
      betweenMin(m, 360, 390) ||    // 06:00-06:30
      betweenMin(m, 1050, 1080) ||  // 17:30-18:00
      betweenMin(m, 1290, 1310);    // 21:30-21:50

  // TVs.
  bool livingTvOn = betweenMin(m, 1140, 1320); // 19:00-22:00
  bool bedroomTvOn =
      betweenMin(m, 360, 420) ||               // 06:00-07:00 morning news
      (m >= 1320 && m < 1440);                 // 22:00-00:00 bedtime TV

  digitalWrite(PIN_LIVING_LIGHT, livingLight ? HIGH : LOW);
  digitalWrite(PIN_BEDROOM_LIGHT, bedroomLight ? HIGH : LOW);
  digitalWrite(PIN_KITCHEN_LIGHT, kitchenLight ? HIGH : LOW);
  digitalWrite(PIN_BATH_LIGHT, bathLight ? HIGH : LOW);
  digitalWrite(PIN_HALL_LIGHT, hallLight ? HIGH : LOW);

  livingTv.enabled = livingTvOn;
  bedroomTv.enabled = bedroomTvOn;

  if (m < 360) {
    eventName = shortNight ? "Short night" : "Night off";
  } else if (m < 420) {
    eventName = "Morning news";
  } else if (m < 510) {
    eventName = "Morning routine";
  } else if (m < 1050) {
    eventName = "Day / away";
  } else if (m < 1140) {
    eventName = "Evening lights";
  } else if (m < 1320) {
    eventName = "Living-room TV";
  } else {
    eventName = "Bed TV / lights off";
  }
}

void updateTv(TvState &tv, uint32_t nowMs) {
  if (!tv.enabled) {
    if (tv.running) {
      analogWrite(tv.pin, 0);
      tv.running = false;
    }
    return;
  }

  if (!tv.running) {
    tv.running = true;
    tv.nextChangeMs = nowMs;
  }

  if ((int32_t)(nowMs - tv.nextChangeMs) >= 0) {
    uint8_t brightness;
    uint8_t r = random(100);

    if (r < 8) {
      brightness = random(0, 25);      // dark frame / scene cut
    } else {
      brightness = random(35, 256);    // normal TV brightness
    }

    analogWrite(tv.pin, brightness);

    uint16_t interval = random(45, 200);
    if (random(100) < 12) {
      interval = random(250, 700);      // slower scene change
    }

    tv.nextChangeMs = nowMs + interval;
  }
}

void drawLine(uint8_t row, const char *text) {
  char padded[17];
  snprintf(padded, sizeof(padded), "%-16.16s", text);
  oled.drawString(0, row, padded);
}

void updateDisplay() {
  uint32_t nowMs = millis();
  if ((uint32_t)(nowMs - lastDisplayMs) < 250UL) return;
  lastDisplayMs = nowMs;

  uint8_t hour = modelSeconds / 3600UL;
  uint8_t minute = (modelSeconds % 3600UL) / 60UL;
  char line[17];

  drawLine(0, "HOUSE SIM");
  snprintf(line, sizeof(line), "Time  %02u:%02u", hour, minute);
  drawLine(1, line);

  snprintf(line, sizeof(line), "Speed %u:1", SPEEDS[speedIndex]);
  drawLine(2, line);

  drawLine(3, shortNight ? "Night: SHORT 1h" : "Night: NORMAL");
  drawLine(4, "Event:");
  drawLine(5, eventName);

  snprintf(line, sizeof(line), "TV L:%s B:%s",
           livingTv.enabled ? "ON" : "--",
           bedroomTv.enabled ? "ON" : "--");
  drawLine(6, line);
  drawLine(7, "");
}

void setup() {
  pinMode(PIN_SHORT_NIGHT, INPUT_PULLUP);
  pinMode(PIN_SPEED, INPUT_PULLUP);

  const uint8_t outputs[] = {
    PIN_LIVING_LIGHT, PIN_BEDROOM_LIGHT, PIN_KITCHEN_LIGHT,
    PIN_BATH_LIGHT, PIN_HALL_LIGHT, PIN_LIVING_TV, PIN_BEDROOM_TV
  };

  for (uint8_t i = 0; i < sizeof(outputs); ++i) {
    pinMode(outputs[i], OUTPUT);
    digitalWrite(outputs[i], LOW);
  }

  Wire.begin();

  // Most SSD1306 0.96 OLEDs use 0x3C. Some use 0x3D.
  oled.setI2CAddress(0x3C << 1);
  oled.begin();
  oled.setPowerSave(0);
  oled.setFont(u8x8_font_chroma48medium8_r);
  oled.clear();

  if (!rtc.begin()) {
    drawLine(0, "RTC not found");
    drawLine(2, "Check wiring");
    while (true) {}
  }

  // If the RTC has no battery/time, set it to compile time.
  // For normal operation you can set it once with a separate RTC sketch.
  if (rtc.lostPower()) {
    rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
  }

  DateTime now = rtc.now();
  lastRtcSeconds = now.unixtime();

  if (START_FROM_RTC) {
    modelSeconds = (uint32_t)now.hour() * 3600UL +
                   (uint32_t)now.minute() * 60UL +
                   now.second();
  } else {
    modelSeconds = (uint32_t)START_HOUR * 3600UL + START_MINUTE * 60UL;
  }

  shortNight = (digitalRead(PIN_SHORT_NIGHT) == LOW);
  applyShortNight();

  randomSeed(analogRead(A0) ^ now.unixtime());

  updateHouse();

  uint32_t nowMs = millis();
  updateTv(livingTv, nowMs);
  updateTv(bedroomTv, nowMs);

  lastDisplayMs = nowMs - 300UL;
  updateDisplay();
}

void loop() {
  uint32_t nowMs = millis();

  updateModelClock();
  updateControls();
  updateHouse();
  updateTv(livingTv, nowMs);
  updateTv(bedroomTv, nowMs);
  updateDisplay();
}
```

