Chương trình C gợi ý:

```c
#include <stdio.h>

void euclidMoRong(long long a, long long b,
                  long long *d, long long *x, long long *y)
{
    /* (1) Nếu b = 0 */
    if (b == 0) {
        *d = a;
        *x = 1;
        *y = 0;
        return;
    }

    /* (2) Khởi tạo */
    long long x2 = 1, x1 = 0;
    long long y2 = 0, y1 = 1;

    /* (3) Lặp khi b > 0 */
    while (b > 0) {
        /* 3.1 */
        long long q = a / b;
        long long r = a - q * b;

        long long x = x2 - q * x1;
        long long y = y2 - q * y1;

        /* 3.2 */
        a = b;
        b = r;

        x2 = x1;
        x1 = x;

        y2 = y1;
        y1 = y;
    }

    /* (4) Trả kết quả */
    *d = a;
    *x = x2;
    *y = y2;
}

int main(void)
{
    long long a, b;
    long long d, x, y;

    printf("Nhap hai so nguyen khong am a va b: ");
    if (scanf("%lld %lld", &a, &b) != 2 || a < 0 || b < 0) {
        printf("Du lieu khong hop le.\n");
        return 1;
    }

    if (a == 0 && b == 0) {
        printf("UCLN(0, 0) khong xac dinh.\n");
        return 1;
    }

    euclidMoRong(a, b, &d, &x, &y);

    printf("UCLN(%lld, %lld) = %lld\n", a, b, d);
    printf("x = %lld, y = %lld\n", x, y);
    printf("Bieu dien: %lld * %lld + %lld * %lld = %lld\n",
           a, x, b, y, d);

    return 0;
}
```

