class SegTree {
 vector<int> cover; vector<ll> len; vector<ll> ys; int n;
 public:
 SegTree(const vector<ll>& y) : ys(y) { n = max(0,(int)ys.size()-1); cover.assign(4*max(1,n)+5,0); len.assign(...); }
 void update(int ql,int qr,int delta){ if(ql>=qr || n==0) return; update(1,0,n,ql,qr,delta); }
 ll query() const { return n? len[1]:0; }
 private:
 void update(int node,int l,int r,int ql,int qr,int delta){ if(qr<=l || ql>=r) return; if(ql<=l && r<=qr){ cover[node]+=delta; pull(node,l,r); return; } int mid=(l+r)/2; update(node*2,l,mid,...); update(node*2+1,mid,r,...); pull(node,l,r); }
 void pull(int node,int l,int r){ if(cover[node]>0) len[node]=ys[r]-ys[l]; else if(r-l==1) len[node]=0; else len[node]=len[node*2]+len[node*2+1]; }
};
