## My answer to the prompt

A standard solution is: **sweep line on x + segment tree on compressed y coordinates**.

Each rectangle contributes two vertical events:

- at `x1`: add coverage on `[y1, y2)`
- at `x2`: remove coverage on `[y1, y2)`

The segment tree maintains the total covered length on the y-axis. When moving the sweep line from `prevX` to current `x`, the added area is:

```text
covered_y_length * (x - prevX)
```

Finally take the result modulo `1e9 + 7`.

```cpp
#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1000000007LL;

struct Event {
    ll x, y1, y2;
    int delta;

    bool operator<(const Event& other) const {
        return x < other.x;
    }
};

class SegmentTree {
private:
    int n;
    vector<ll> ys;
    vector<int> cover;
    vector<ll> len;

    void pull(int p, int l, int r) {
        if (cover[p] > 0) {
            len[p] = ys[r + 1] - ys[l];
        } else if (l == r) {
            len[p] = 0;
        } else {
            len[p] = len[p * 2] + len[p * 2 + 1];
        }
    }

    void update(int p, int l, int r, int ql, int qr, int delta) {
        if (ql <= l && r <= qr) {
            cover[p] += delta;
            pull(p, l, r);
            return;
        }

        if (l == r) return;

        int mid = (l + r) / 2;
        if (ql <= mid) {
            update(p * 2, l, mid, ql, qr, delta);
        }
        if (qr > mid) {
            update(p * 2 + 1, mid + 1, r, ql, qr, delta);
        }

        pull(p, l, r);
    }

public:
    explicit SegmentTree(const vector<ll>& coordinates) : ys(coordinates) {
        int m = (int)ys.size();
        n = max(0, m - 1);

        int sz = 4 * max(1, n);
        cover.assign(sz, 0);
        len.assign(sz, 0);
    }

    void add(int l, int r, int delta) {
        if (n == 0 || l > r) return;
        update(1, 0, n - 1, l, r, delta);
    }

    ll coveredLength() const {
        return n == 0 ? 0 : len[1];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<Event> events;
    vector<ll> ys;

    for (int i = 0; i < n; ++i) {
        ll x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;

        if (x1 > x2) swap(x1, x2);
        if (y1 > y2) swap(y1, y2);

        if (x1 == x2 || y1 == y2) continue;

        events.push_back({x1, y1, y2, 1});
        events.push_back({x2, y1, y2, -1});

        ys.push_back(y1);
        ys.push_back(y2);
    }

    if (events.empty()) {
        cout << 0 << '\n';
        return 0;
    }

    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    sort(events.begin(), events.end());

    SegmentTree seg(ys);

    ll ans = 0;
    ll prevX = events[0].x;

    for (size_t i = 0; i < events.size(); ) {
        ll x = events[i].x;
        ll width = x - prevX;

        if (width > 0) {
            ans = (ans + (seg.coveredLength() % MOD) * (width % MOD)) % MOD;
        }

        while (i < events.size() && events[i].x == x) {
            int l = (int)(lower_bound(ys.begin(), ys.end(), events[i].y1) - ys.begin());
            int r = (int)(lower_bound(ys.begin(), ys.end(), events[i].y2) - ys.begin());

            if (l < r) {
                seg.add(l, r - 1, events[i].delta);
            }

            ++i;
        }

        prevX = x;
    }

    cout << ans % MOD << '\n';
    return 0;
}
```

Complexity:

```text
Time: O(n log n)
Space: O(n)
```

