from typing import Any, Callable

_MISSING = object()
_DROP = object()


class ChainError(RuntimeError):
    """Pipeline error with stage context."""


@dataclass(frozen=True)
class Ctx:
    """
    Optional second argument passed to user functions.

    Functions can receive:
      - fn(item)
      - fn(item, config)
      - fn(item, index)
      - fn(item, ctx)

    The mode is inferred from the second parameter name, but can be overridden.
    """

    index: int
    config: Any


def _preview(value: Any, limit: int = 200) -> str:
    try:
        text = repr(value)
    except Exception:
        text = f"<{type(value).__name__}>"
    return text[:limit]


def _unwrap(fn: Callable) -> Callable:
    while isinstance(fn, functools.partial):
        fn = fn.func
    return fn


def _is_async_callable(fn: Callable) -> bool:
    fn = _unwrap(fn)
    return (
        inspect.iscoroutinefunction(fn)
        or inspect.iscoroutinefunction(getattr(fn, "__call__", None))
    )


def _arg_mode(fn: Callable) -> str:
    """
    Infer calling convention.

    Returns one of:
      - "item": fn(item)
      - "config": fn(item, config)
      - "index": fn(item, index)
      - "ctx": fn(item, Ctx)

    The second argument is only passed if the callable can accept two positional
    arguments. If the second parameter is named config/cfg/settings/conf, config
    is passed. If it is named index/idx/i, index is passed. Otherwise Ctx is
    passed.
    """
    fn = _unwrap(fn)

    try:
        sig = inspect.signature(fn)
    except (TypeError, ValueError):
        # If we cannot inspect it, default to the safest simple convention.
        return "item"

    try:
        sig.bind(None, None)
        can_two = True
    except TypeError:
        can_two = False

    if not can_two:
        return "item"

    positional = [
        p
        for p in sig.parameters.values()
        if p.kind
        in (
            inspect.Parameter.POSITIONAL_ONLY,
            inspect.Parameter.POSITIONAL_OR_KEYWORD,
        )
    ]
    has_var_positional = any(
        p.kind == inspect.Parameter.VAR_POSITIONAL for p in sig.parameters.values()
    )

    if len(positional) >= 2:
        second = positional[1].name.lower()
    elif has_var_positional:
        second = ""
    else:
        second = ""

    if second in {"config", "cfg", "settings", "conf"}:
        return "config"

    if second in {"index", "idx", "i"}:
        return "index"

    return "ctx"


async def _invoke(
    fn: Callable,
    item: Any,
    ctx: Ctx,
    mode: str,
    executor: Executor | None = None,
) -> Any:
    if mode == "item":
        args = (item,)
    elif mode == "config":
        args = (item, ctx.config)
    elif mode == "index":
        args = (item, ctx.index)
    else:
        args = (item, ctx)

    if _is_async_callable(fn):
        result = fn(*args)
    elif executor is None:
        # Default: run blocking functions in a thread.
        result = await asyncio.to_thread(fn, *args)
    else:
        # Optional: pass a ThreadPoolExecutor or ProcessPoolExecutor.
        result = await asyncio.get_running_loop().run_in_executor(
            executor,
            functools.partial(fn, *args),
        )

    # Also support sync functions that return awaitables.
    if inspect.isawaitable(result):
        result = await result

    return result


class DiskCache:
    """
    Simple atomic file-backed cache.

    Uses pickle. The cache directory should be trusted.
    """

    def __init__(self, directory: str | Path):
        self.directory = Path(directory)

    @staticmethod
    def key(namespace: Any, item: Any) -> str:
        try:
            payload = pickle.dumps((namespace, item), protocol=5)
        except Exception:
            # Fallback for non-picklable inputs. This is less robust but keeps
            # simple pipelines working.
            payload = repr((namespace, item)).encode("utf-8")

        return hashlib.sha256(payload).hexdigest()

    def get(self, key: str) -> Any:
        path = self.directory / f"{key}.pickle"

        try:
            with path.open("rb") as file:
                return pickle.load(file)
        except FileNotFoundError:
            return _MISSING
        except Exception:
            # Corrupt cache entries are treated as misses.
            return _MISSING

    def put(self, key: str, value: Any) -> None:
        self.directory.mkdir(parents=True, exist_ok=True)

        fd, temporary = tempfile.mkstemp(dir=self.directory, suffix=".tmp")

        try:
            with os.fdopen(fd, "wb") as file:
                pickle.dump(value, file, protocol=5)

            os.replace(temporary, self.directory / f"{key}.pickle")
        finally:
            Path(temporary).unlink(missing_ok=True)


def _read_file(path: Path, format: str):
    """
    Synchronous source iterator.

    It is later advanced in worker threads so file I/O does not block the loop.
    """
    if format == "text":
        with path.open(encoding="utf-8") as file:
            for line in file:
                yield line.rstrip("\n")

    elif format == "jsonl":
        with path.open(encoding="utf-8") as file:
            for number, line in enumerate(file, 1):
                line = line.strip()
                if not line:
                    continue

                try:
                    yield json.loads(line)
                except json.JSONDecodeError as exc:
                    raise ValueError(f"Invalid JSON in {path}, line {number}") from exc

    elif format == "json":
        # Contract: top-level JSON array.
        with path.open("rb") as file:
            try:
                import ijson
            except ImportError:
                data = json.load(file)
                if not isinstance(data, list):
                    raise ValueError(f"{path} must contain a top-level JSON array")
                yield from data
            else:
                yield from ijson.items(file, "item", use_float=True)

    else:
        raise ValueError(f"Unknown input format: {format!r}")


async def _iterate_sync(iterable: Iterable, batch_size: int = 64):
    """
    Bridge a sync iterable into an async iterator without blocking the loop.
    """
    iterator = iter(iterable)

    try:
        while True:
            batch = await asyncio.to_thread(
                lambda: list(itertools.islice(iterator, batch_size))
            )

            if not batch:
                return

            for item in batch:
                yield item
    finally:
        close = getattr(iterator, "close", None)
        if close is not None:
            await asyncio.to_thread(close)


class _AtomicWriter:
    """
    Atomic streaming writer for json / jsonl / text outputs.
    """

    def __init__(self, path: Path, format: str):
        self.path = Path(path)
        self.format = format
        self.temporary: str | None = None
        self.file = None
        self.first = True
        self.committed = False

    def open(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)

        fd, self.temporary = tempfile.mkstemp(
            dir=self.path.parent,
            suffix=".tmp",
        )

        self.file = os.fdopen(fd, "w", encoding="utf-8")

        if self.format == "json":
            self.file.write("[\n")

    def write(self, item: Any) -> None:
        if self.format == "json":
            encoded = json.dumps(
                item,
                ensure_ascii=False,
                default=str,
            )

            if not self.first:
                self.file.write(",\n")

            self.file.write(encoded)
            self.first = False

        elif self.format == "jsonl":
            encoded = json.dumps(
                item,
                ensure_ascii=False,
                default=str,
            )
            self.file.write(encoded + "\n")

        elif self.format == "text":
            self.file.write(str(item) + "\n")

        else:
            raise ValueError(f"Unknown output format: {self.format!r}")

    def commit(self) -> None:
        if self.file is None:
            return

        if self.format == "json":
            self.file.write("\n]\n")

        self.file.close()
        self.file = None

        os.replace(self.temporary, self.path)

        self.temporary = None
        self.committed = True

    def close(self) -> None:
        if self.file is not None:
            self.file.close()
            self.file = None

        if self.temporary is not None and not self.committed:
            Path(self.temporary).unlink(missing_ok=True)

        self.temporary = None


@dataclass(frozen=True)
class _Step:
    kind: str
    name: str
    options: dict[str, Any] = field(default_factory=dict)


@dataclass(frozen=True)
class Chain:
    """
    Declarative, composable, streaming data-processing chain.

    Example:

        chain = (
            Chain(config)
            .load("data/queries.txt")
            .take(config.n)
            .map(search_exa, use_cache=True)
            .flatten()
            .save("data/exa_results.json")
            .map(rerank_result, use_cache=True)
            .groupby("query")
            .map(aggregate_result)
            .map(autoprompt, use_cache=True)
            .filter(lambda x, _: x is not None)
            .save("data/reranked-autoprompt.json")
            .save_to_s3("michael-datasets", "reranked-autoprompt.json")
        )

        chain.run()
    """

    config: Any = None
    concurrency: int = 16
    progress: bool = True
    cache_dir: str | Path = ".chain-cache"
    _steps: tuple[_Step, ...] = field(default=(), repr=False)

    def __post_init__(self):
        if self.concurrency < 1:
            raise ValueError("concurrency must be >= 1")

    # ------------------------------------------------------------------
    # Builder helpers
    # ------------------------------------------------------------------

    def _add(self, kind: str, name: str, **options: Any) -> Chain:
        return replace(
            self,
            _steps=self._steps + (_Step(kind, name, options),),
        )

    def _require_source_slot(self) -> None:
        if self._steps:
            raise ValueError("load()/from_iterable() must be the first stage")

    @staticmethod
    def _infer_input_format(path: Path, format: str | None) -> str:
        if format is not None:
            return format

        suffix = path.suffix.lower()

        if suffix == ".json":
            return "json"

        if suffix in {".jsonl", ".ndjson"}:
            return "jsonl"

        return "text"

    @staticmethod
    def _infer_output_format(suffix: str, default: str = "jsonl") -> str:
        suffix = suffix.lower()

        if suffix == ".json":
            return "json"

        if suffix in {".jsonl", ".ndjson"}:
            return "jsonl"

        if suffix in {".txt", ".text"}:
            return "text"

        return default

    # ------------------------------------------------------------------
    # Public chain operations
    # ------------------------------------------------------------------

    def load(self, path: str | Path, *, format: str | None = None) -> Chain:
        self._require_source_slot()

        path = Path(path)
        format = self._infer_input_format(path, format)

        return self._add(
            "load",
            f"load {path}",
            path=path,
            format=format,
        )

    def from_iterable(self, items: Iterable | AsyncIterable) -> Chain:
        self._require_source_slot()
        return self._add("source", "source", items=items)

    def take(self, n: int | None) -> Chain:
        if n is not None and n < 0:
            raise ValueError("n must be >= 0 or None")

        return self._add("take", f"take {n}", n=n)

    def map(
        self,
        fn: Callable,
        *,
        concurrency: int | None = None,
        ordered: bool = True,
        use_cache: bool = False,
        cache_key: str | None = None,
        executor: Executor | None = None,
        name: str | None = None,
        second_arg: str | None = None,
    ) -> Chain:
        limit = self.concurrency if concurrency is None else concurrency

        if limit < 1:
            raise ValueError("concurrency must be >= 1")

        mode = second_arg or _arg_mode(fn)
        label = name or getattr(fn, "__name__", type(fn).__name__)

        return self._add(
            "map",
            f"map {label}",
            fn=fn,
            arg_mode=mode,
            concurrency=limit,
            ordered=ordered,
            use_cache=use_cache,
            cache_key=cache_key,
            executor=executor,
        )

    def filter(
        self,
        fn: Callable,
        *,
        concurrency: int | None = None,
        ordered: bool = True,
        name: str | None = None,
        second_arg: str | None = None,
    ) -> Chain:
        limit = self.concurrency if concurrency is None else concurrency

        if limit < 1:
            raise ValueError("concurrency must be >= 1")

        mode = second_arg or _arg_mode(fn)
        label = name or getattr(fn, "__name__", "predicate")

        return self._add(
            "filter",
            f"filter {label}",
            fn=fn,
            arg_mode=mode,
            concurrency=limit,
            ordered=ordered,
        )

    def flatten(self) -> Chain:
        """
        Flatten one level.

        Strings, bytes, and mappings are rejected to avoid surprising behavior
        such as flattening dicts into their keys.
        """
        return self._add("flatten", "flatten")

    def groupby(
        self,
        key: str | Callable,
        *,
        name: str | None = None,
    ) -> Chain:
        """
        Gather all upstream items and emit one group dict per key.

        If key == "query", emits:

            {"query": key_value, "items": [...]}

        If key is callable, emits:

            {"key": key_value, "items": [...]}
        """
        mode = _arg_mode(key) if callable(key) else None

        if isinstance(key, str):
            label = name or f"groupby {key}"
        else:
            label = name or f"groupby {getattr(key, '__name__', 'key')}"

        return self._add(
            "groupby",
            label,
            key=key,
            arg_mode=mode,
        )

    def save(self, path: str | Path, *, format: str | None = None) -> Chain:
        """
        Save items to disk while also passing them through downstream.
        """
        path = Path(path)
        format = format or self._infer_output_format(path.suffix, default="jsonl")

        if format not in {"json", "jsonl", "text"}:
            raise ValueError("format must be 'json', 'jsonl', or 'text'")

        return self._add(
            "save",
            f"save {path}",
            path=path,
            format=format,
        )

    def save_to_s3(
        self,
        bucket: str,
        key: str,
        *,
        format: str | None = None,
        extra_args: dict | None = None,
    ) -> Chain:
        """
        Spool items to a temporary file, pass them through, then upload to S3.
        """
        format = format or self._infer_output_format(
            Path(key).suffix,
            default="json",
        )

        if format not in {"json", "jsonl", "text"}:
            raise ValueError("format must be 'json', 'jsonl', or 'text'")

        return self._add(
            "s3",
            f"s3://{bucket}/{key}",
            bucket=bucket,
            key=key,
            format=format,
            extra_args=dict(extra_args or {}),
        )

    # ------------------------------------------------------------------
    # Execution internals
    # ------------------------------------------------------------------

    async def _source(self, step: _Step):
        if step.kind == "load":
            values = _read_file(
                step.options["path"],
                step.options["format"],
            )
        else:
            values = step.options["items"]

        if isinstance(values, AsyncIterable):
            iterator = values.__aiter__()

            try:
                async for item in iterator:
                    yield item
            finally:
                aclose = getattr(iterator, "aclose", None)
                if aclose is not None:
                    await aclose()
        else:
            async with aclosing(_iterate_sync(values)) as iterator:
                async for item in iterator:
                    yield item

    async def _guard(self, iterator, step: _Step, position: int):
        bar = None

        if self.progress:
            try:
                from tqdm.auto import tqdm
            except ImportError:
                tqdm = None

            if tqdm is not None:
                bar = tqdm(
                    desc=step.name,
                    position=position,
                    unit="item",
                    leave=False,
                )

        try:
            async with aclosing(iterator):
                async for item in iterator:
                    if bar is not None:
                        bar.update()
                    yield item

        except ChainError:
            raise

        except Exception as exc:
            raise ChainError(
                f"Stage {position + 1} ({step.name}) failed: {exc}"
            ) from exc

        finally:
            if bar is not None:
                bar.close()

    async def _stage(self, source, step: _Step, position: int):
        # Closing a downstream stage recursively closes upstream stages.
        async with aclosing(source):
            async with aclosing(
                self._guard(
                    self._execute(source, step),
                    step,
                    position,
                )
            ) as results:
                async for item in results:
                    yield item

    async def _parallel(self, source, step: _Step):
        options = step.options

        fn = options["fn"]
        mode = options["arg_mode"]
        concurrency = options["concurrency"]
        ordered = options["ordered"]
        executor = options.get("executor")

        cache = None
        namespace = None

        if options.get("use_cache"):
            cache = DiskCache(self.cache_dir)

            raw_fn = _unwrap(fn)

            try:
                source_code = inspect.getsource(raw_fn)
            except Exception:
                source_code = None

            namespace = (
                options.get("cache_key")
                or (
                    getattr(raw_fn, "__module__", None),
                    getattr(
                        raw_fn,
                        "__qualname__",
                        getattr(raw_fn, "__name__", type(raw_fn).__name__),
                    ),
                    source_code,
                ),
                self.config,
            )

        async def work(index: int, item: Any):
            ctx = Ctx(index=index, config=self.config)

            try:
                key = None

                if cache is not None:
                    key = await asyncio.to_thread(cache.key, namespace, item)
                    cached = await asyncio.to_thread(cache.get, key)

                    if cached is not _MISSING:
                        return cached

                result = await _invoke(fn, item, ctx, mode, executor)

                if step.kind == "filter":
                    return item if result else _DROP

                if key is not None:
                    await asyncio.to_thread(cache.put, key, result)

                return result

            except Exception as exc:
                raise ChainError(
                    f"{step.name}: item #{index}, value={_preview(item)}: {exc}"
                ) from exc

        pending: list[asyncio.Task] = []

        async def receive():
            if ordered:
                task = pending[0]
                result = await task
                pending.pop(0)
                return result

            done, _ = await asyncio.wait(
                pending,
                return_when=asyncio.FIRST_COMPLETED,
            )

            task = next(iter(done))
            result = await task
            pending.remove(task)

            return result

        try:
            index = 0

            async for item in source:
                pending.append(asyncio.create_task(work(index, item)))
                index += 1

                if len(pending) >= concurrency:
                    result = await receive()

                    if result is not _DROP:
                        yield result

            while pending:
                result = await receive()

                if result is not _DROP:
                    yield result

        finally:
            for task in pending:
                task.cancel()

            await asyncio.gather(*pending, return_exceptions=True)

    async def _save_stream(self, source, path: Path, format: str):
        writer = _AtomicWriter(path, format)

        try:
            await asyncio.to_thread(writer.open)

            async for item in source:
                await asyncio.to_thread(writer.write, item)
                yield item

            await asyncio.to_thread(writer.commit)

        finally:
            await asyncio.to_thread(writer.close)

    async def _execute(self, source, step: _Step):
        kind = step.kind
        options = step.options

        if kind == "take":
            n = options["n"]

            if n is None:
                async for item in source:
                    yield item
                return

            if n <= 0:
                return

            count = 0

            async for item in source:
                yield item
                count += 1

                if count >= n:
                    return

        elif kind in {"map", "filter"}:
            async with aclosing(self._parallel(source, step)) as results:
                async for item in results:
                    yield item

        elif kind == "flatten":
            index = 0

            async for item in source:
                if isinstance(item, (str, bytes, bytearray, Mapping)):
                    raise ChainError(
                        f"{step.name}: item #{index} is {type(item).__name__}; "
                        "flatten() expects an iterable item, not a scalar/mapping"
                    )

                if isinstance(item, AsyncIterable):
                    iterator = item.__aiter__()

                    try:
                        async for sub in iterator:
                            yield sub
                    finally:
                        aclose = getattr(iterator, "aclose", None)
                        if aclose is not None:
                            await aclose()

                elif isinstance(item, Iterable):
                    async with aclosing(_iterate_sync(item)) as values:
                        async for sub in values:
                            yield sub

                else:
                    raise ChainError(
                        f"{step.name}: item #{index} is not iterable: "
                        f"{_preview(item)}"
                    )

                index += 1

        elif kind == "groupby":
            groups = defaultdict(list)

            key = options["key"]
            mode = options.get("arg_mode")

            index = 0

            async for item in source:
                try:
                    if callable(key):
                        value = await _invoke(
                            key,
                            item,
                            Ctx(index=index, config=self.config),
                            mode or "item",
                        )
                    elif isinstance(item, Mapping):
                        value = item[key]
                    else:
                        value = getattr(item, key)

                except Exception as exc:
                    raise ChainError(
                        f"{step.name}: item #{index}, value={_preview(item)}: {exc}"
                    ) from exc

                try:
                    groups[value].append(item)
                except TypeError as exc:
                    raise ChainError(
                        f"{step.name}: group key is not hashable: {value!r}"
                    ) from exc

                index += 1

            field_name = key if isinstance(key, str) else "key"

            for value, items in groups.items():
                yield {field_name: value, "items": items}

        elif kind == "save":
            async with aclosing(
                self._save_stream(
                    source,
                    options["path"],
                    options["format"],
                )
            ) as results:
                async for item in results:
                    yield item

        elif kind == "s3":
            with tempfile.TemporaryDirectory(prefix="chain-s3-") as directory:
                path = Path(directory) / "payload"

                async with aclosing(
                    self._save_stream(
                        source,
                        path,
                        options["format"],
                    )
                ) as results:
                    async for item in results:
                        yield item

                def upload():
                    try:
                        import boto3
                    except ImportError as exc:
                        raise RuntimeError(
                            "boto3 is required for save_to_s3()"
                        ) from exc

                    boto3.client("s3").upload_file(
                        str(path),
                        options["bucket"],
                        options["key"],
                        ExtraArgs=options.get("extra_args") or None,
                    )

                await asyncio.to_thread(upload)

        else:
            raise ValueError(f"Unknown stage: {kind}")

    # ------------------------------------------------------------------
    # Async iterator protocol
    # ------------------------------------------------------------------

    def __aiter__(self):
        if not self._steps or self._steps[0].kind not in {"load", "source"}:
            raise ValueError("A chain must start with load() or from_iterable()")

        first = self._steps[0]
        stream = self._guard(self._source(first), first, 0)

        for position, step in enumerate(self._steps[1:], 1):
            stream = self._stage(stream, step, position)

        return stream

    # ------------------------------------------------------------------
    # Entry points
    # ------------------------------------------------------------------

    async def arun(self, *, collect: bool = False):
        """
        Drain the pipeline asynchronously.

        Returns:
          - final item count when collect=False
          - list of final items when collect=True
        """
        output = [] if collect else None
        count = 0

        async with aclosing(self.__aiter__()) as stream:
            async for item in stream:
                count += 1

                if collect:
                    output.append(item)

        return output if collect else count

    def run(self, *, collect: bool = False):
        """
        Drain the pipeline from synchronous code.
        """
        try:
            asyncio.get_running_loop()
        except RuntimeError:
            return asyncio.run(self.arun(collect=collect))

        raise RuntimeError(
            "An event loop is already running. Use `await chain.arun()` instead."
        )

    def __await__(self):
        return self.arun().__await__()
```

Example usage:

```python
config = RerankConfig.parse()

chain = (
    Chain(config, concurrency=20)
    .load("data/queries.txt")
    .take(config.n)
    .map(search_exa, use_cache=True, cache_key="search_exa:v1")
    .flatten()
    .save("data/exa_results.json")
    .map(rerank_result, use_cache=True, cache_key="rerank_result:v1")
    .groupby("query")
    .map(aggregate_result)
    .map(autoprompt, use_cache=True, cache_key="autoprompt:v1")
    .filter(lambda x, _: x is not None)
    .save("data/reranked-autoprompt.json")
    .save_to_s3("michael-datasets", "reranked-autoprompt.json")
)

chain.run()
```

After `.groupby("query")`, downstream functions receive group dictionaries like:

```python
{
    "query": "...",
    "items": [ ... ],
}
```

So an aggregation function can be written as:

```python
def aggregate_result(group):
    query = group["query"]
    items = group["items"]

    return {
        "query": query,
        "results": items,
    }
```

Or, if it wants the config:

```python
def aggregate_result(group, config):
    return {
        "query": group["query"],
        "results": group["items"],
        "model": config.model,
    }
```

Important semantics:

- `.save(...)` passes items through while writing.
- `.save(...)` commits atomically only if the stage fully completes.
- `.groupby(...)` necessarily gathers all upstream items.
- `.map(...)` and `.filter(...)` stream with bounded concurrency.
- `ordered=True` preserves input order.
- `ordered=False` can emit completed work sooner.
- For CPU-bound work, pass an executor:

```python
from concurrent.futures import ProcessPoolExecutor

with ProcessPoolExecutor(max_workers=4) as pool:
    (
        Chain(config)
        .load("input.jsonl")
        .map(cpu_heavy_function, executor=pool, concurrency=4)
        .save("output.jsonl")
        .run()
    )
```

