    { x: 540, y: 520, w: 170, h: 24 },
    { x: 820, y: 430, w: 170, h: 24 },
    { x: 1120, y: 560, w: 180, h: 24 },
    { x: 1400, y: 460, w: 170, h: 24 },
    { x: 1750, y: 600, w: 180, h: 24 },
    { x: 2050, y: 490, w: 180, h: 24 },
    { x: 2350, y: 610, w: 170, h: 24 },
    { x: 2700, y: 520, w: 180, h: 24 },
    { x: 3000, y: 430, w: 180, h: 24 },
    { x: 3250, y: 620, w: 180, h: 24 }
  ];

  coins = [];
  const coinSpots = [
    [150, 720],
    [350, 580],
    [620, 480],
    [890, 390],
    [1180, 520],
    [1470, 420],
    [1820, 560],
    [2120, 450],
    [2420, 570],
    [2770, 480],
    [3070, 390],
    [3320, 580],
    [1000, 720],
    [1900, 720],
    [2800, 720]
  ];

  for (const [x, y] of coinSpots) {
    coins.push({ x, y, taken: false });
  }

  enemies = [];
  const enemySpots = [
    [400, 760, 1],
    [1000, 760, 1],
    [1300, 760, 1],
    [1800, 760, 1],
    [2200, 760, 1],
    [2600, 760, 1],
    [3100, 760, 2],
    [1150, 560, 1],
    [2080, 490, 1],
    [3030, 430, 2]
  ];

  for (const [x, surfaceY, hp] of enemySpots) {
    enemies.push({
      x,
      y: surfaceY - 32,
      w: 32,
      h: 32,
      vx: 0,
      vy: 0,
      dir: 1,
      speed: 70,
      hp,
      dead: false,
      invuln: 0,
      lastSwing: 0,
      onGround: false
    });
  }

  particles = [];
}

function createPlayer() {
  return {
    x: 60,
    y: 700,
    w: 28,
    h: 44,
    vx: 0,
    vy: 0,
    face: 1,
    onGround: false,
    attack: 0,
    cooldown: 0,
    invuln: 0,
    hp: 5,
    spawnX: 60,
    spawnY: 700
  };
}

function newGame() {
  makeLevel();
  player = createPlayer();
  hook = null;

  score = 0;
  kills = 0;
  deaths = 0;
  swingId = 0;
  jumpBuffer = 0;

  camera = { x: 0, y: 300 };
  state = "play";

  say("Reach the golden flag. Aim with the mouse and press E to hook.");
}

function initTitle() {
  makeLevel();
  player = createPlayer();
  hook = null;
  state = "title";
}

function burst(x, y, color, n = 10) {
  for (let i = 0; i < n; i++) {
    const a = Math.random() * Math.PI * 2;
    const s = 50 + Math.random() * 160;
    particles.push({
      x,
      y,
      vx: Math.cos(a) * s,
      vy: Math.sin(a) * s - 60,
      life: 0.5,
      color
    });
  }
}

function moveBody(body, dx, dy) {
  let hitX = false;
  let hitY = false;

  body.x += dx;

  for (const p of platforms) {
    if (!overlap(body, p)) continue;

    if (dx > 0) body.x = p.x - body.w;
    else if (dx < 0) body.x = p.x + p.w;
    else continue;

    body.vx = 0;
    hitX = true;
  }

  body.y += dy;
  body.onGround = false;

  for (const p of platforms) {
    if (!overlap(body, p)) continue;

    if (dy > 0) {
      body.y = p.y - body.h;
      body.onGround = true;
    } else if (dy < 0) {
      body.y = p.y + p.h;
    } else {
      continue;
    }

    body.vy = 0;
    hitY = true;
  }

  return { hitX, hitY };
}

function rayRect(ox, oy, dx, dy, rect, maxDistance) {
  let near = 0;
  let far = maxDistance;

  for (const [o, d, min, max] of [
    [ox, dx, rect.x, rect.x + rect.w],
    [oy, dy, rect.y, rect.y + rect.h]
  ]) {
    if (Math.abs(d) < 1e-8) {
      if (o < min || o > max) return null;
    } else {
      let a = (min - o) / d;
      let b = (max - o) / d;

      if (a > b) [a, b] = [b, a];

      near = Math.max(near, a);
      far = Math.min(far, b);

      if (near > far) return null;
    }
  }

  return near >= 0 && near <= maxDistance ? near : null;
}

function castHook(targetX, targetY) {
  const c = center(player);

  let dx = targetX - c.x;
  let dy = targetY - c.y;
  const len = Math.hypot(dx, dy);

  if (len < 1) return null;

  dx /= len;
  dy /= len;

  let best = null;
  let bestDistance = HOOK_RANGE;

  for (const p of platforms) {
    const d = rayRect(c.x, c.y, dx, dy, p, HOOK_RANGE);

    if (d !== null && d > 8 && d < bestDistance) {
      bestDistance = d;
      best = {
        x: c.x + dx * d,
        y: c.y + dy * d,
        distance: d
      };
    }
  }

  return best;
}

function hookTarget() {
  return castHook(mouse.x + camera.x, mouse.y + camera.y);
}

function toggleHook() {
  if (state !== "play") return;

  if (hook) {
    hook = null;
    return;
  }

  const target = hookTarget();

  if (target) {
    hook = {
      x: target.x,
      y: target.y,
      length: Math.max(50, target.distance)
    };
    burst(target.x, target.y, "#ffffff", 8);
  } else {
    say("No surface in hook range.", 1.5);
  }
}

function attack() {
  if (state !== "play" || player.cooldown > 0) return;

  player.attack = 0.18;
  player.cooldown = 0.32;
  swingId++;
}

function respawn() {
  deaths++;
  hook = null;

  player.x = player.spawnX;
  player.y = player.spawnY;
  player.vx = 0;
  player.vy = 0;
  player.hp = 5;
  player.invuln = 1.5;

  camera.x = clamp(player.x - W * 0.4, 0, WORLD_W - W);
  camera.y = clamp(player.y - H * 0.55, 0, WORLD_H - H);

  say("Respawned.");
}

function hurt(sourceX) {
  if (player.invuln > 0 || state !== "play") return;

  player.hp--;
  player.invuln = 1.2;
  hook = null;

  const c = center(player);
  player.vx = c.x < sourceX ? -300 : 300;
  player.vy = -350;
  player.onGround = false;

  burst(c.x, c.y, "#ff5566", 14);

  if (player.hp <= 0) respawn();
}

function damageEnemy(enemy, direction) {
  if (enemy.dead || enemy.invuln > 0) return;

  enemy.hp--;
  enemy.invuln = 0.25;

  burst(enemy.x + enemy.w / 2, enemy.y + enemy.h / 2, "#ffee66", 8);

  if (enemy.hp <= 0) {
    enemy.dead = true;
    kills++;
    score += 5;
  } else {
    enemy.dir = direction;
  }
}

function update(dt) {
  time += dt;
  toastTime = Math.max(0, toastTime - dt);

  particles = particles.filter(p => {
    p.life -= dt;
    p.vy += 700 * dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    return p.life > 0;
  });

  if (state !== "play") return;

  player.invuln = Math.max(0, player.invuln - dt);
  player.attack = Math.max(0, player.attack - dt);
  player.cooldown = Math.max(0, player.cooldown - dt);
  jumpBuffer = Math.max(0, jumpBuffer - dt);

  const left = keys.has("ArrowLeft") || keys.has("KeyA");
  const right = keys.has("ArrowRight") || keys.has("KeyD");
  const dir = Number(right) - Number(left);

  if (dir) player.face = dir;

  if (jumpBuffer > 0 && (player.onGround || hook)) {
    const wasHooked = !!hook;
    hook = null;
    player.vy = wasHooked ? Math.min(player.vy - 250, -560) : -620;
    player.onGround = false;
    jumpBuffer = 0;
  }

  if (hook) {
    player.vx += dir * 1200 * dt;
    player.vx *= Math.exp(-0.2 * dt);
    player.vx = clamp(player.vx, -700, 700);

    if (keys.has("KeyW")) hook.length = Math.max(50, hook.length - 220 * dt);
    if (keys.has("KeyS")) hook.length = Math.min(HOOK_RANGE, hook.length + 220 * dt);
  } else {
    const accel = player.onGround ? 2400 : 1500;

    if (dir) {
      if (Math.abs(player.vx) < 300 || Math.sign(player.vx) !== dir) {
        player.vx += dir * accel * dt;
      } else {
        player.vx *= Math.exp(-1.2 * dt);
      }

      player.vx = clamp(player.vx, -650, 650);
    } else {
      player.vx *= Math.exp(-(player.onGround ? 14 : 2) * dt);
    }
  }

  player.vy = Math.min(player.vy + GRAVITY * dt, 1100);

  moveBody(player, player.vx * dt, player.vy * dt);

  if (hook) {
    const c = center(player);
    const dx = c.x - hook.x;
    const dy = c.y - hook.y;
    const distance = Math.hypot(dx, dy);

    if (distance > hook.length && distance > 0) {
      const nx = dx / distance;
      const ny = dy / distance;
      const correction = distance - hook.length;
      const steps = Math.max(1, Math.ceil(correction / 8));

      for (let i = 0; i < steps; i++) {
        moveBody(player, -nx * correction / steps, -ny * correction / steps);
      }

      const outward = player.vx * nx + player.vy * ny;

      if (outward > 0) {
        player.vx -= outward * nx;
        player.vy -= outward * ny;
      }

      const actual = Math.hypot(center(player).x - hook.x, center(player).y - hook.y);
      hook.length = Math.max(hook.length, actual);
    }
  }

  player.x = clamp(player.x, 0, WORLD_W - player.w);

  if (player.y > WORLD_H + 100) {
    respawn();
    return;
  }

  if (player.attack > 0) {
    const hitbox = {
      x: player.face > 0 ? player.x + player.w - 5 : player.x - 60,
      y: player.y - 8,
      w: 65,
      h: player.h + 16
    };

    for (const e of enemies) {
      if (!e.dead && e.lastSwing !== swingId && overlap(hitbox, e)) {
        e.lastSwing = swingId;
        damageEnemy(e, player.face);
      }
    }
  }

  const pc = center(player);

  for (const coin of coins) {
    if (!coin.taken && Math.abs(pc.x - coin.x) < 24 && Math.abs(pc.y - coin.y) < 34) {
      coin.taken = true;
      score += 10;
      burst(coin.x, coin.y, "#ffdd33", 8);
    }
  }

  for (const e of enemies) {
    if (e.dead) continue;

    e.invuln = Math.max(0, e.invuln - dt);

    if (e.onGround) {
      const lookX = e.dir > 0 ? e.x + e.w + 8 : e.x - 8;
      const footY = e.y + e.h;

      const hasFloor = platforms.some(p =>
        lookX >= p.x &&
        lookX <= p.x + p.w &&
        Math.abs(p.y - footY) < 8
      );

      if (!hasFloor) e.dir *= -1;
    }

    e.vx = e.dir * e.speed;
    e.vy = Math.min(e.vy + GRAVITY * dt, 1000);

    const hit = moveBody(e, e.vx * dt, e.vy * dt);

    if (hit.hitX) e.dir *= -1;

    if (e.y > WORLD_H + 100) {
      e.dead = true;
      continue;
    }

    if (state === "play" && overlap(player, e)) {
      const feet = player.y + player.h;

      if (player.vy > 100 && feet - e.y < 26) {
        damageEnemy(e, player.face);
        player.y = e.y - player.h;
        player.vy = -420;
        player.onGround = false;
        hook = null;
      } else {
        hurt(center(e).x);
      }
    }
  }

  if (overlap(player, goal)) {
    state = "win";
    burst(goal.x + goal.w / 2, goal.y + 20, "#ffdd55", 50);
  }

  const targetX = clamp(player.x + player.w / 2 - W * 0.4, 0, WORLD_W - W);
  const targetY = clamp(player.y + player.h / 2 - H * 0.55, 0, WORLD_H - H);

  camera.x += (targetX - camera.x) * Math.min(1, dt * 8);
  camera.y += (targetY - camera.y) * Math.min(1, dt * 8);
}

function draw() {
  ctx.clearRect(0, 0, W, H);

  const sky = ctx.createLinearGradient(0, 0, 0, H);
  sky.addColorStop(0, "#68b7ff");
  sky.addColorStop(1, "#dff3ff");
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, H);

  ctx.save();
  ctx.translate(-Math.round(camera.x), -Math.round(camera.y));

  for (const p of platforms) {
    ctx.fillStyle = "#6b4b2a";
    ctx.fillRect(p.x, p.y, p.w, p.h);
    ctx.fillStyle = "#47b04b";
    ctx.fillRect(p.x, p.y, p.w, 8);
  }

  ctx.fillStyle = "#8b5a2b";
  ctx.fillRect(goal.x + 20, goal.y, 10, goal.h);

  ctx.fillStyle = "#ffd700";
  ctx.fillRect(goal.x + 30, goal.y, 42, 30);

  ctx.fillStyle = "#7a5b1e";
  ctx.font = "16px monospace";
  ctx.textAlign = "center";
  ctx.fillText("END", goal.x + 50, goal.y + 20);

  for (const coin of coins) {
    if (coin.taken) continue;

    const y = coin.y + Math.sin(time * 4 + coin.x * 0.05) * 3;

    ctx.fillStyle = "#ffcc22";
    ctx.beginPath();
    ctx.arc(coin.x, y, 8, 0, Math.PI * 2);
    ctx.fill();
  }

  for (const e of enemies) {
    if (e.dead) continue;

    ctx.fillStyle = e.hp > 1 ? "#7d8899" : "#bb66ff";
    ctx.fillRect(e.x, e.y, e.w, e.h);

    ctx.fillStyle = "#fff";
    ctx.fillRect(e.x + 6, e.y + 8, 6, 6);
    ctx.fillRect(e.x + 20, e.y + 8, 6, 6);

    ctx.fillStyle = "#111";
    ctx.fillRect(e.x + (e.dir > 0 ? 10 : 6), e.y + 10, 2, 3);
    ctx.fillRect(e.x + (e.dir > 0 ? 24 : 20), e.y + 10, 2, 3);
  }

  const pc = center(player);

  if (hook) {
    ctx.strokeStyle = "#f2f2f2";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(pc.x, pc.y);
    ctx.lineTo(hook.x, hook.y);
    ctx.stroke();

    ctx.fillStyle = "#fff";
    ctx.fillRect(hook.x - 3, hook.y - 3, 6, 6);
  } else if (state === "play") {
    const target = hookTarget();

    if (target) {
      ctx.strokeStyle = "rgba(255,255,255,0.5)";
      ctx.setLineDash([6, 10]);
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(pc.x, pc.y);
      ctx.lineTo(target.x, target.y);
      ctx.stroke();
      ctx.setLineDash([]);
    }
  }

  if (player.invuln > 0 && Math.floor(time * 16) % 2) {
    ctx.globalAlpha = 0.45;
  }

  ctx.fillStyle = "#2266ff";
  ctx.fillRect(player.x, player.y, player.w, player.h);

  ctx.fillStyle = "#ffcc99";
  ctx.fillRect(player.x + 4, player.y + 4, player.w - 8, 12);

  ctx.fillStyle = "#111";
  ctx.fillRect(player.face > 0 ? player.x + player.w - 10 : player.x + 6, player.y + 8, 3, 4);

  ctx.globalAlpha = 1;

  if (player.attack > 0) {
    ctx.fillStyle = "#ffee88";
    const x = player.face > 0 ? player.x + player.w : player.x - 55;
    ctx.fillRect(x, player.y + 10, 55, 10);
  }

  for (const p of particles) {
    ctx.globalAlpha = clamp(p.life / 0.5, 0, 1);
    ctx.fillStyle = p.color;
    ctx.fillRect(p.x, p.y, 3, 3);
  }

  ctx.globalAlpha = 1;

  ctx.restore();

  if (state !== "title") {
    ctx.fillStyle = "rgba(0,0,0,0.55)";
    ctx.fillRect(10, 10, 280, 58);

    ctx.fillStyle = "#fff";
    ctx.font = "16px monospace";
    ctx.textAlign = "left";

    ctx.fillText(`Score ${score}  Kills ${kills}  Deaths ${deaths}`, 20, 32);
    ctx.fillText("HP " + "♥".repeat(player.hp) + "♡".repeat(Math.max(0, 5 - player.hp)), 20, 56);
  }

  if (toastTime > 0 && state === "play") {
    ctx.font = "16px monospace";
    const w = ctx.measureText(toast).width + 30;

    ctx.fillStyle = "rgba(0,0,0,0.6)";
    ctx.fillRect((W - w) / 2, H - 52, w, 32);

    ctx.fillStyle = "#fff";
    ctx.textAlign = "center";
    ctx.fillText(toast, W / 2, H - 30);
  }

  if (state === "title" || state === "win") {
    ctx.fillStyle = "rgba(0,0,0,0.65)";
    ctx.fillRect(0, 0, W, H);

    ctx.fillStyle = "#fff";
    ctx.textAlign = "center";

    if (state === "title") {
      ctx.font = "36px monospace";
      ctx.fillText("HOOK PLATFORMER", W / 2, 200);

      ctx.font = "18px monospace";
      ctx.fillText("Move with A/D, jump with Space, attack with J/left click.", W / 2, 250);
      ctx.fillText("Aim with mouse and press E/right click to hook. Press Enter to start.", W / 2, 285);
    } else {
      ctx.font = "40px monospace";
      ctx.fillText("LEVEL COMPLETE", W / 2, 210);

      ctx.font = "20px monospace";
      ctx.fillText(`Score ${score}   Kills ${kills}   Deaths ${deaths}`, W / 2, 260);
      ctx.fillText("Press R or Enter to play again.", W / 2, 300);
    }
  }
}

canvas.addEventListener("mousemove", e => {
  const r = canvas.getBoundingClientRect();
  mouse.x = (e.clientX - r.left) * W / r.width;
  mouse.y = (e.clientY - r.top) * H / r.height;
});

canvas.addEventListener("mousedown", e => {
  e.preventDefault();

  if (state !== "play") {
    if (e.button === 0) newGame();
    return;
  }

  if (e.button === 0) attack();
  if (e.button === 2) toggleHook();
});

canvas.addEventListener("contextmenu", e => e.preventDefault());

window.addEventListener("keydown", e => {
  const controlled = [
    "Space",
    "ArrowLeft",
    "ArrowRight",
    "ArrowUp",
    "ArrowDown",
    "KeyA",
    "KeyD",
    "KeyW",
    "KeyS",
    "KeyE",
    "KeyJ",
    "KeyR",
    "Enter"
  ];

  if (controlled.includes(e.code)) e.preventDefault();

  keys.add(e.code);

  if (e.repeat) return;

  if (e.code === "KeyR") {
    newGame();
    return;
  }

  if (state !== "play" && (e.code === "Enter" || e.code === "Space")) {
    newGame();
    return;
  }

  if (state !== "play") return;

  if (e.code === "Space" || e.code === "ArrowUp") jumpBuffer = 0.14;
  if (e.code === "KeyJ") attack();
  if (e.code === "KeyE") toggleHook();
});

window.addEventListener("keyup", e => {
  keys.delete(e.code);

  if ((e.code === "Space" || e.code === "ArrowUp") && state === "play" && !hook && player.vy < -240) {
    player.vy = -240;
  }
});

window.addEventListener("blur", () => {
  keys.clear();
  jumpBuffer = 0;
});

initTitle();

let last = performance.now();
let accumulator = 0;

function frame(now) {
  const delta = Math.min((now - last) / 1000, 0.05);
  last = now;
  accumulator += delta;

  while (accumulator >= STEP) {
    update(STEP);
    accumulator -= STEP;
  }

  draw();
  requestAnimationFrame(frame);
}

requestAnimationFrame(frame);
</script>
</body>
</html>
```

Evaluation:

My baseline answer is a self-contained HTML/JavaScript game with no external assets. It includes side-scrolling movement, jumping, attacking, a raycast grappling hook with rope constraint and reeling, patrolling enemies, loot, health, camera scrolling, and a finish goal. That is the standard I used when judging the two assistants.

Assistant A:

Helpful and relevant:
- Assistant A provides a runnable Python/Pygame program.
- It includes most requested elements: left/right movement, jumping, attack, a hook-like ability, platforms, enemies, loot, camera scrolling, and an end condition.

Issues and corrections:
1. Incorrect control description:
   - The docstring says “Press A to attack,” but the code uses `pygame.K_j`.
   - Correction: either change the code to `if event.key == pygame.K_a:` or update the documentation to say `J`.

2. Hook is not really an attach/pull mechanic:
   - The code raycasts to a platform, then immediately teleports the player to the hit point.
   - The prompt asks for a hook to attach to surfaces. A better implementation would keep the hook attached and apply a rope constraint or pull force over time, as Assistant B does and as my answer does.

3. Collision resolution is fragile:
   - The player collision code checks vertical landing with `self.rect.bottom - plat.rect.top < 20`, then falls back to horizontal resolution.
   - This can fail for ceilings, side collisions, fast falls, or jumping through platforms from below.
   - Correction: use separate-axis collision resolution: move horizontally, resolve horizontal overlaps, then move vertically, resolve vertical overlaps.

4. Enemy placement is slightly wrong:
   - Enemy height is 30. For a platform at `y=450`, an enemy standing on it should have `y=420`, but the code uses `y=410`.
   - For a platform at `y=400`, the enemy should have `y=370`, but the code uses `y=360`.
   - This makes enemies float slightly.

5. Enemies do not affect the player:
   - The user asked for enemies, but there is no damage, knockback, stomping, or death from touching enemies.
   - The player can only attack enemies; enemies themselves are harmless.

6. Level design is minimal:
   - The ground is mostly continuous, the end condition is simply `player.rect.x > 1100`, and the game exits immediately.
   - It technically satisfies the prompt, but it feels more like a prototype than a complete level.

Conciseness:
- The code is relatively short and easy to read.
- However, it sacrifices important platformer robustness and game feel.

Overall:
- Assistant A’s answer is a useful starting point, but it has several mechanical inaccuracies and does not fully deliver a satisfying hook mechanic or enemy threat.

Assistant B:

Helpful and relevant:
- Assistant B provides a complete, self-contained browser game in a single HTML file.
- It includes all requested mechanics: move left/right, jump, attack, hook attachment to surfaces, platforms, enemies, loot, and a level endpoint.
- It goes further with health, checkpoints, stomp mechanics, enemy types, particles, camera smoothing, pause/restart, HUD, and win screen.

Accuracy and correctness:
- The core architecture is strong:
  - Axis-separated collision resolution.
  - Raycast hook targeting.
  - Rope length constraint with reeling using `W` and `S`.
  - Swing momentum and hook release jump.
  - Enemy patrol with floor detection.
  - Attack hitboxes with swing IDs to prevent multi-hit from one attack.
  - Loot collection and goal detection.

Issues and corrections:
1. `ctx.roundRect` compatibility:
   - Assistant B uses `ctx.roundRect` inside `roundedBox`.
   - This is supported in modern browsers, but may fail in older browsers.
   - Correction:
     ```js
     function roundedBox(x, y, w, h, radius, color) {
       ctx.fillStyle = color;
       ctx.beginPath();
       if (ctx.roundRect) {
         ctx.roundRect(x, y, w, h, radius);
       } else {
         ctx.rect(x, y, w, h);
       }
       ctx.fill();
     }
     ```

2. Hook preview performance:
   - `drawRope` calls `getHookTarget()` every frame when the hook is inactive.
   - This is acceptable for a small game, but it could be optimized by caching the target only when the mouse/player/camera changes.

3. Minor initialization clarity:
   - Enemy objects do not explicitly initialize `lastSwing`, though the code works because `undefined !== player.swingId`.
   - For clarity and maintainability, it would be better to initialize `lastSwing: 0`.

4. Desktop-focused controls:
   - The game uses right-click for hook and keyboard controls.
   - This is fine for the prompt, but touch controls would improve accessibility.

