</main>
<script>
"use strict";
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");
const W = 960, H = 540;
const WORLD_W = 3600, WORLD_H = 720;
const GRAVITY = 2000;
const HOOK_RANGE = 430;

const keys = new Set();
const mouse = { x: W / 2, y: H / 2 };
const camera = { x: 0, y: 0 };
let state = "playing";
let platforms = [], coins = [], enemies = [], particles = [];
let player, rope = null;
let score = 0, kills = 0, time = 0, message = "", messageTime = 0, jumpPressed = false;
const goal = { x: 3440, y: 460, w: 40, h: 180 };

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const rand = (a, b) => a + Math.random() * (b - a);
const overlap = (a, b) => a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
const center = o => ({ x: o.x + o.w / 2, y: o.y + o.h / 2 });
function say(text, t = 3) { message = text; messageTime = t; }

function addCoin(x, y) { coins.push({ x, y, taken: false, phase: Math.random() * Math.PI * 2 }); }
function addEnemy(x, topY, hp = 1) {
  enemies.push({
    x, y: topY - 30, w: 30, h: 30,
    vx: 0, vy: 0, dir: 1, speed: 70,
    hp, maxHp: hp, dead: false, invuln: 0,
    grounded: false, lastSwing: 0
  });
}

function buildLevel() {
  platforms = [
    { x: 0, y: 640, w: 700, h: 80 },
    { x: 820, y: 640, w: 500, h: 80 },
    { x: 1420, y: 640, w: 700, h: 80 },
    { x: 2220, y: 640, w: 400, h: 80 },
    { x: 2740, y: 640, w: 860, h: 80 },
    { x: 260, y: 520, w: 120, h: 20 },
    { x: 460, y: 430, w: 120, h: 20 },
    { x: 720, y: 360, w: 140, h: 20 },
    { x: 980, y: 480, w: 130, h: 20 },
    { x: 1200, y: 380, w: 140, h: 20 },
    { x: 1500, y: 520, w: 160, h: 20 },
    { x: 1750, y: 420, w: 150, h: 20 },
    { x: 2000, y: 320, w: 150, h: 20 },
    { x: 2300, y: 520, w: 140, h: 20 },
    { x: 2550, y: 420, w: 150, h: 20 },
    { x: 2850, y: 520, w: 160, h: 20 },
    { x: 3100, y: 400, w: 150, h: 20 },
    { x: 3320, y: 540, w: 120, h: 20 }
  ];

  coins = [];
  enemies = [];

  for (let i = 0; i < 5; i++) addCoin(160 + i * 40, 590);
  for (let i = 0; i < 4; i++) addCoin(880 + i * 40, 590);
  for (let i = 0; i < 5; i++) addCoin(1480 + i * 40, 590);
  for (let i = 0; i < 4; i++) addCoin(2280 + i * 40, 590);
  for (let i = 0; i < 6; i++) addCoin(2800 + i * 40, 590);

  [
    [300, 480], [500, 390], [770, 320], [1030, 440], [1250, 340],
    [1560, 480], [1810, 380], [2060, 280], [2350, 480], [2610, 380],
    [2910, 480], [3160, 360], [3370, 500]
  ].forEach(([x, y]) => addCoin(x, y));

  addEnemy(350, 640);
  addEnemy(600, 640);
  addEnemy(950, 640);
  addEnemy(1600, 640);
  addEnemy(1900, 640);
  addEnemy(2400, 640);
  addEnemy(2900, 640);
  addEnemy(3200, 640, 2);
  addEnemy(740, 360);
  addEnemy(1220, 380);
  addEnemy(2020, 320, 2);
  addEnemy(3120, 400);
