function resetGame() {
  buildLevel();
  player = {
    x: 60, y: 560, w: 26, h: 38,
    vx: 0, vy: 0, face: 1, grounded: false,
    hp: 5, invuln: 0, attack: 0, cooldown: 0, swing: 0,
    spawnX: 60, spawnY: 560
  };
  rope = null;
  score = 0;
  kills = 0;
  state = "playing";
  camera.x = 0;
  camera.y = WORLD_H - H;
  jumpPressed = false;
  say("Reach the golden flag!");
}

function burst(x, y, color, count = 10) {
  for (let i = 0; i < count; i++) {
    particles.push({
      x, y,
      vx: rand(-140, 140),
      vy: rand(-220, 40),
      life: rand(0.2, 0.55),
      color
    });
  }
}

function moveBody(body, dx, dy) {
  let hitX = false, hitY = false;

  body.x += dx;
  for (const p of platforms) {
    if (!overlap(body, p)) continue;
    if (dx > 0) body.x = p.x - body.w;
    else if (dx < 0) body.x = p.x + p.w;
    else continue;
    body.vx = 0;
    hitX = true;
  }

  body.y += dy;
  body.grounded = false;
  for (const p of platforms) {
    if (!overlap(body, p)) continue;
    if (dy > 0) {
      body.y = p.y - body.h;
      body.grounded = true;
    } else if (dy < 0) {
      body.y = p.y + p.h;
    } else continue;
    body.vy = 0;
    hitY = true;
  }

  return { hitX, hitY };
}

function pointInPlatforms(x, y) {
  return platforms.some(p => x >= p.x && x <= p.x + p.w && y >= p.y && y <= p.y + p.h);
}

function castHook(tx, ty) {
  const c = center(player);
  let dx = tx - c.x, dy = ty - c.y;
  const len = Math.hypot(dx, dy);
  if (len < 1) return null;
  dx /= len;
  dy /= len;

  for (let d = 8; d <= HOOK_RANGE; d += 3) {
    const x = c.x + dx * d;
    const y = c.y + dy * d;
    if (pointInPlatforms(x, y)) return { x, y, distance: d };
  }
  return null;
}

function toggleHook() {
  if (state !== "playing") return;
  if (rope) {
    rope = null;
    say("Hook released", 1.5);
    return;
  }

  const target = castHook(mouse.x + camera.x, mouse.y + camera.y);
  if (!target) {
    say("No surface in hook range", 2);
    return;
  }

  rope = { x: target.x, y: target.y, length: Math.max(45, target.distance) };
  burst(target.x, target.y, "#ffffff", 8);
  say("Hooked! W/S reel, Space launch", 2);
}

function attack() {
  if (state !== "playing" || player.cooldown > 0) return;
  player.attack = 0.16;
  player.cooldown = 0.28;
  player.swing++;
}

function hurt(sourceX) {
  if (player.invuln > 0 || state !== "playing") return;
  player.hp--;
  player.invuln = 1.2;
  rope = null;
  const c = center(player);
  player.vx = c.x < sourceX ? -300 : 300;
  player.vy = -350;
  burst(c.x, c.y, "#ff5555", 14);
  if (player.hp <= 0) respawn();
}

function respawn() {
  player.hp = 5;
  player.x = player.spawnX;
  player.y = player.spawnY;
  player.vx = player.vy = 0;
  player.invuln = 1.5;
  rope = null;
  say("Respawned");
}

function damageEnemy(e, dir) {
  if (e.dead || e.invuln > 0) return;
  e.hp--;
  e.invuln = 0.25;
  const c = center(e);
  burst(c.x, c.y, "#ffcc00", 8);
  if (e.hp <= 0) {
    e.dead = true;
    kills++;
    score += 5;
    addCoin(c.x, c.y - 15);
  } else {
    e.dir = dir;
  }
}

function updatePlayer(dt) {
  player.invuln = Math.max(0, player.invuln - dt);
  player.attack = Math.max(0, player.attack - dt);
  player.cooldown = Math.max(0, player.cooldown - dt);

  const left = keys.has("ArrowLeft") || keys.has("KeyA");
  const right = keys.has("ArrowRight") || keys.has("KeyD");
  const dir = Number(right) - Number(left);
  if (dir) player.face = dir;

  if (jumpPressed) {
    if (rope) {
      rope = null;
      player.vy = Math.min(player.vy - 250, -620);
    } else if (player.grounded) {
      player.vy = -680;
    }
    player.grounded = false;
    jumpPressed = false;
  }

  if (rope) {
    player.vx += dir * 1300 * dt;
    player.vx *= Math.exp(-0.2 * dt);
    player.vx = clamp(player.vx, -700, 700);

    if (keys.has("KeyW")) rope.length -= 230 * dt;
    if (keys.has("KeyS")) rope.length += 230 * dt;
    rope.length = clamp(rope.length, 45, HOOK_RANGE);
  } else {
    const accel = player.grounded ? 2600 : 1600;
    if (dir) {
      player.vx += dir * accel * dt;
      player.vx = clamp(player.vx, -300, 300);
    } else {
      player.vx *= Math.exp((player.grounded ? -14 : -2) * dt);
    }
  }

  player.vy = Math.min(player.vy + GRAVITY * dt, 1200);
  moveBody(player, player.vx * dt, player.vy * dt);

  if (rope) {
    const c = center(player);
    const dx = c.x - rope.x;
    const dy = c.y - rope.y;
    const dist = Math.hypot(dx, dy);

    if (dist > rope.length && dist > 0) {
      const nx = dx / dist;
      const ny = dy / dist;
      const correction = dist - rope.length;
      const steps = Math.max(1, Math.ceil(correction / 8));

      for (let i = 0; i < steps; i++) {
        moveBody(player, -nx * correction / steps, -ny * correction / steps);
      }

      const outward = player.vx * nx + player.vy * ny;
      if (outward > 0) {
        player.vx -= outward * nx;
        player.vy -= outward * ny;
      }

      const actual = Math.hypot(center(player).x - rope.x, center(player).y - rope.y);
      rope.length = Math.max(rope.length, actual);
    }
  }

  player.x = clamp(player.x, 0, WORLD_W - player.w);
  if (player.y > WORLD_H + 100) {
    respawn();
    return;
  }

  if (player.attack > 0) {
    const hitbox = {
      x: player.face > 0 ? player.x + player.w : player.x - 55,
      y: player.y - 5,
      w: 55,
      h: player.h + 10
    };

    for (const e of enemies) {
      if (!e.dead && e.lastSwing !== player.swing && overlap(hitbox, e)) {
        e.lastSwing = player.swing;
        damageEnemy(e, player.face);
      }
    }
  }

  const pc = center(player);
  for (const coin of coins) {
    if (!coin.taken && Math.abs(pc.x - coin.x) < 24 && Math.abs(pc.y - coin.y) < 34) {
      coin.taken = true;
      score++;
      burst(coin.x, coin.y, "#ffd700", 8);
    }
  }

  if (overlap(player, goal)) {
    state = "won";
    burst(goal.x + goal.w / 2, goal.y + 40, "#7fff00", 40);
  }
}

function updateEnemies(dt) {
  for (const e of enemies) {
    if (e.dead) continue;
    e.invuln = Math.max(0, e.invuln - dt);

    if (e.grounded) {
      const footX = e.dir > 0 ? e.x + e.w + 3 : e.x - 3;
      const footY = e.y + e.h + 4;
      const hasFloor = platforms.some(p =>
        footX >= p.x && footX <= p.x + p.w &&
        footY >= p.y && footY <= p.y + p.h
      );
      if (!hasFloor) e.dir *= -1;
    }

    e.vx = e.dir * e.speed;
    e.vy = Math.min(e.vy + GRAVITY * dt, 1000);
    const hit = moveBody(e, e.vx * dt, e.vy * dt);
    if (hit.hitX) e.dir *= -1;

    if (e.y > WORLD_H + 100) {
      e.dead = true;
      continue;
    }

    if (state === "playing" && overlap(player, e)) {
      const feet = player.y + player.h;
      if (player.vy > 100 && feet - e.y < 22) {
        damageEnemy(e, player.face);
        player.vy = -450;
        player.grounded = false;
        rope = null;
      } else {
        hurt(center(e).x);
      }
    }
  }
}

function updateParticles(dt) {
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.life -= dt;
    if (p.life <= 0) {
      particles.splice(i, 1);
      continue;
    }
    p.vy += 800 * dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
  }
}

function update(dt) {
  time += dt;
  messageTime = Math.max(0, messageTime - dt);
  updateParticles(dt);

  if (state !== "playing") return;

  updatePlayer(dt);
  updateEnemies(dt);

  const targetX = clamp(player.x + player.w / 2 - W * 0.4, 0, WORLD_W - W);
  const targetY = clamp(player.y + player.h / 2 - H * 0.55, 0, WORLD_H - H);
  camera.x += (targetX - camera.x) * Math.min(1, dt * 8);
  camera.y += (targetY - camera.y) * Math.min(1, dt * 8);
}

function drawText(text, x, y, size = 20, color = "#fff", align = "left") {
  ctx.font = `bold ${size}px sans-serif`;
  ctx.textAlign = align;
  ctx.textBaseline = "middle";
  ctx.fillStyle = color;
  ctx.fillText(text, x, y);
}

function render() {
  const sky = ctx.createLinearGradient(0, 0, 0, H);
  sky.addColorStop(0, "#7ec8ff");
  sky.addColorStop(1, "#dff6ff");
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, H);

  ctx.save();
  ctx.translate(-Math.round(camera.x), -Math.round(camera.y));

  for (const p of platforms) {
    ctx.fillStyle = "#6b4f2a";
    ctx.fillRect(p.x, p.y, p.w, p.h);
    ctx.fillStyle = "#4caf50";
    ctx.fillRect(p.x, p.y, p.w, 6);
  }

  ctx.fillStyle = "#8b5a2b";
  ctx.fillRect(goal.x + 16, goal.y, 8, goal.h);
  ctx.fillStyle = "#ffd700";
  ctx.beginPath();
  ctx.moveTo(goal.x + 24, goal.y);
  ctx.lineTo(goal.x + 70, goal.y + 18);
  ctx.lineTo(goal.x + 24, goal.y + 36);
  ctx.closePath();
  ctx.fill();

  for (const coin of coins) {
    if (coin.taken) continue;
    const y = coin.y + Math.sin(time * 5 + coin.phase) * 4;
    ctx.fillStyle = "#d4a017";
    ctx.beginPath();
    ctx.arc(coin.x, y, 9, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#ffd700";
    ctx.beginPath();
    ctx.arc(coin.x, y, 6, 0, Math.PI * 2);
    ctx.fill();
  }

  for (const e of enemies) {
    if (e.dead) continue;
    ctx.save();
    if (e.invuln > 0) ctx.globalAlpha = 0.6;
    ctx.fillStyle = e.maxHp > 1 ? "#7777cc" : "#cc4444";
    ctx.fillRect(e.x, e.y, e.w, e.h);
    ctx.fillStyle = "#fff";
    ctx.fillRect(e.x + 6, e.y + 8, 6, 6);
    ctx.fillRect(e.x + 18, e.y + 8, 6, 6);
    ctx.fillStyle = "#000";
    ctx.fillRect(e.x + (e.dir > 0 ? 10 : 6), e.y + 10, 3, 3);
    ctx.fillRect(e.x + (e.dir > 0 ? 22 : 18), e.y + 10, 3, 3);
    ctx.restore();
  }

  if (rope) {
    const pc = center(player);
    ctx.strokeStyle = "#553322";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(pc.x, pc.y);
    ctx.lineTo(rope.x, rope.y);
    ctx.stroke();
    ctx.fillStyle = "#ddd";
    ctx.beginPath();
    ctx.arc(rope.x, rope.y, 5, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.save();
  const pc = center(player);
  ctx.translate(pc.x, pc.y);
  ctx.scale(player.face, 1);
  if (player.invuln > 0 && Math.floor(time * 18) % 2) ctx.globalAlpha = 0.35;

  ctx.fillStyle = "#2277ff";
  ctx.fillRect(-player.w / 2, -player.h / 2, player.w, player.h);
  ctx.fillStyle = "#ffd1a0";
  ctx.fillRect(-8, -player.h / 2 - 12, 18, 14);
  ctx.fillStyle = "#222";
  ctx.fillRect(4, -player.h / 2 - 8, 3, 4);
  ctx.fillStyle = "#cc2222";
  ctx.fillRect(-10, -player.h / 2 - 16, 22, 6);

  if (player.attack > 0) {
    ctx.fillStyle = "#dddddd";
    ctx.fillRect(player.w / 2, -8, 38, 6);
    ctx.strokeStyle = "#ffffff88";
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(0, 0, 46, -0.9, 0.9);
    ctx.stroke();
  }
  ctx.restore();

  for (const p of particles) {
    ctx.globalAlpha = clamp(p.life / 0.55, 0, 1);
    ctx.fillStyle = p.color;
    ctx.fillRect(p.x, p.y, 4, 4);
  }
  ctx.globalAlpha = 1;
  ctx.restore();

  drawText("❤".repeat(player.hp) + "♡".repeat(5 - player.hp), 16, 24, 22, "#ff6b81");
  drawText(`Score: ${score}   Kills: ${kills}`, 16, 52, 18, "#111");

  if (messageTime > 0) {
    drawText(message, W / 2, H - 28, 18, "#111", "center");
  }

  if (state === "won") {
    ctx.fillStyle = "rgba(0,0,0,0.55)";
    ctx.fillRect(0, 0, W, H);
    drawText("LEVEL COMPLETE!", W / 2, H / 2 - 30, 42, "#ffd700", "center");
    drawText(`Score: ${score}   Kills: ${kills}`, W / 2, H / 2 + 20, 24, "#fff", "center");
    drawText("Press R to play again", W / 2, H / 2 + 60, 20, "#ccc", "center");
  }
}

function updateMouse(e) {
  const r = canvas.getBoundingClientRect();
  mouse.x = (e.clientX - r.left) * (W / r.width);
  mouse.y = (e.clientY - r.top) * (H / r.height);
}

canvas.addEventListener("mousemove", updateMouse);
canvas.addEventListener("mousedown", e => {
  updateMouse(e);
  if (e.button === 0) attack();
  if (e.button === 2) toggleHook();
});
canvas.addEventListener("contextmenu", e => e.preventDefault());

window.addEventListener("keydown", e => {
  const controls = [
    "Space", "ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown",
    "KeyA", "KeyD", "KeyW", "KeyS", "KeyJ", "KeyE", "KeyR"
  ];
  if (controls.includes(e.code)) e.preventDefault();
  keys.add(e.code);
  if (e.repeat) return;

  if (e.code === "KeyR") resetGame();
  if (state !== "playing") return;

  if (e.code === "Space") jumpPressed = true;
  if (e.code === "KeyJ") attack();
  if (e.code === "KeyE") toggleHook();
});

window.addEventListener("keyup", e => keys.delete(e.code));

resetGame();

let last = performance.now();
function frame(now) {
  const dt = Math.min((now - last) / 1000, 0.03);
  last = now;
  update(dt);
  render();
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
</script>
</body>
</html>
```

## Evaluation of Assistant A and Assistant B

### Assistant A

Assistant A provides a complete, self-contained HTML/JavaScript game that closely matches the requested mechanics:

- Move left/right.
- Jump.
- Attack.
- Use a hook to attach to surfaces.
- Platforms, enemies, loot, checkpoints, and a final flag.
- HUD, pause/restart, particles, camera scrolling, and polished visuals.

The hook implementation is especially strong: it uses raycasting to attach to platforms, has rope length control, swing/release behavior, and collision-aware correction. Enemy behavior includes patrolling, damage, stomping, and loot drops. The level has a clear goal and win state.

There are no major functional errors in Assistant A’s answer. The only notable caveat is that it uses `ctx.roundRect`, which is supported in modern browsers but may require a fallback/polyfill in older browsers. This is a minor compatibility issue, not a fundamental correctness problem.

Compared with my reference implementation, Assistant A’s answer is more polished and feature-complete while satisfying the same core requirements.

### Assistant B

Assistant B provides a Pygame example, but it has several significant issues relative to the prompt:

1. **The hook does not really attach or swing.**  
   The code raycasts to a platform and then immediately teleports the player to the hook point:
   ```python
   player.rect.center = (int(attach_point.x), int(attach_point.y - player.height/2))
   ```
   This is not a sustained hook mechanic. A proper implementation should keep the hook attached and constrain or pull the player over time.

2. **Enemies do not damage the player.**  
   Enemies patrol and can be killed by attacking, but there is no player health, no enemy contact damage, and no death state except falling off the world. This makes the enemies feel decorative rather than game obstacles.

3. **Attack direction is fragile.**  
   The attack hitbox direction is based on `self.vx >= 0`. If the player is standing still, the attack always goes right. A facing direction variable should be stored separately from current velocity.

4. **Documentation inconsistency.**  
   The docstring says “Press A to attack,” but the code uses `pygame.K_j`. Either the comment or the key binding should be corrected.

5. **Enemy placement and patrol are inaccurate.**  
   Enemies are placed slightly above platforms and do not use gravity or edge detection. For example:
   ```python
