    \prod_{t=1}^{T}
    \pi_\theta(y_t\mid x,y_{<t}),
    \qquad
    \log \pi_\theta(y\mid x)
    =
    \sum_{t=1}^{T}
    \log \pi_\theta(y_t\mid x,y_{<t}).
\end{equation}

RLHF is usually trained in three stages.

\subsection{1. Supervised Fine-Tuning}

Given a supervised dataset
$\mathcal{D}_{\mathrm{SFT}}=\{(x^{(i)},y^{(i)})\}_{i=1}^{N_{\mathrm{SFT}}}$,
the SFT objective minimizes the negative log-likelihood of the target completion tokens:
\begin{equation}
    \mathcal{L}_{\mathrm{SFT}}(\theta)
    =
    -\frac{1}{N_{\mathrm{SFT}}}
    \sum_{i=1}^{N_{\mathrm{SFT}}}
    \log \pi_\theta(y^{(i)}\mid x^{(i)})
    =
    -\frac{1}{N_{\mathrm{SFT}}}
    \sum_{i=1}^{N_{\mathrm{SFT}}}
    \sum_{t=1}^{T_i}
    \log \pi_\theta\!\left(
        y_t^{(i)}
        \mid
        x^{(i)},y_{<t}^{(i)}
    \right).
\end{equation}
The resulting model is denoted $\pi_{\mathrm{SFT}}$.

\subsection{2. Preference Modeling and Reward Learning}

For each prompt $x$, sample candidate responses, often from $\pi_{\mathrm{SFT}}$, and ask humans to rank or choose preferred responses. A preference dataset is
\begin{equation}
    \mathcal{D}_{\mathrm{pref}}
    =
    \left\{
        (x^{(i)},y_w^{(i)},y_l^{(i)})
    \right\}_{i=1}^{N},
\end{equation}
where $y_w$ is the preferred, or winning, response and $y_l$ is the dispreferred, or losing, response.

A common preference model is the Bradley--Terry model:
\begin{equation}
    p^*(y_w \succ y_l \mid x)
    =
    \sigma\!\left(
        \frac{r^*(x,y_w)-r^*(x,y_l)}{\tau}
    \right),
\end{equation}
where $\sigma(z)=1/(1+e^{-z})$ and $\tau>0$ is an optional temperature. Usually $\tau=1$, since reward scale can absorb it.

We learn a parametric reward model $r_\phi(x,y)$ by maximum likelihood. The reward-model loss is
\begin{equation}
    \mathcal{L}_{\mathrm{RM}}(\phi)
    =
    -\mathbb{E}_{(x,y_w,y_l)\sim\mathcal{D}_{\mathrm{pref}}}
    \left[
        \log
        \sigma\!\left(
            \frac{
                r_\phi(x,y_w)-r_\phi(x,y_l)
            }{\tau}
        \right)
    \right].
\end{equation}
Equivalently, using $-\log\sigma(z)=\log(1+e^{-z})$,
\begin{equation}
    \mathcal{L}_{\mathrm{RM}}(\phi)
    =
    \mathbb{E}_{(x,y_w,y_l)\sim\mathcal{D}_{\mathrm{pref}}}
    \left[
        \log\left(
            1+
            \exp\left[
                -\frac{
                    r_\phi(x,y_w)-r_\phi(x,y_l)
                }{\tau}
            \right]
        \right)
    \right].
\end{equation}
The empirical version is
\begin{equation}
    \mathcal{L}_{\mathrm{RM}}(\phi)
    =
    \frac{1}{N}
    \sum_{i=1}^{N}
    \log\left(
        1+
        \exp\left[
            -\frac{
                r_\phi(x^{(i)},y_w^{(i)})
                -
                r_\phi(x^{(i)},y_l^{(i)})
            }{\tau}
        \right]
    \right).
\end{equation}

Because pairwise Bradley--Terry probabilities depend only on reward differences, the absolute offset of $r_\phi$ is not identifiable. Centering rewards, e.g. enforcing
\begin{equation}
    \mathbb{E}_{x,y\sim\mathcal{D}}[r_\phi(x,y)]=0,
\end{equation}
fixes an offset convention but does not by itself reduce variance. Scaling the reward changes the effective strength of the later KL regularization.

\subsection{3. KL-Regularized Reinforcement Learning}

Let $\pi_{\mathrm{ref}}$ be a frozen reference policy, usually $\pi_{\mathrm{SFT}}$. The RLHF objective maximizes expected learned reward while penalizing divergence from the reference policy:
\begin{equation}
    J_{\mathrm{RLHF}}(\theta)
    =
    \mathbb{E}_{x\sim\mu}
    \left[
        \mathbb{E}_{y\sim\pi_\theta(\cdot\mid x)}
        \left[
            r_\phi(x,y)
        \right]
        -
        \beta
        D_{\mathrm{KL}}
        \left(
            \pi_\theta(\cdot\mid x)
            \,\Vert\,
            \pi_{\mathrm{ref}}(\cdot\mid x)
        \right)
    \right],
\end{equation}
where $\mu(x)$ is the prompt distribution and $\beta>0$ controls regularization strength.

The KL divergence is
\begin{equation}
    D_{\mathrm{KL}}
    \left(
        \pi_\theta(\cdot\mid x)
        \,\Vert\,
        \pi_{\mathrm{ref}}(\cdot\mid x)
    \right)
    =
    \sum_y
    \pi_\theta(y\mid x)
    \log
    \frac{
        \pi_\theta(y\mid x)
    }{
        \pi_{\mathrm{ref}}(y\mid x)
    }.
\end{equation}
For sampled completions, a single-sample estimator is
\begin{equation}
    \widehat{D}_{\mathrm{KL}}
    =
    \log \pi_\theta(y\mid x)
    -
    \log \pi_{\mathrm{ref}}(y\mid x).
\end{equation}

Thus, the minimization loss corresponding to $-J_{\mathrm{RLHF}}$ is
\begin{equation}
    \boxed{
    \mathcal{L}_{\mathrm{RLHF}}(\theta)
    =
    \mathbb{E}_{x\sim\mu,\;y\sim\pi_\theta(\cdot\mid x)}
    \left[
        \beta
        \log
        \frac{
            \pi_\theta(y\mid x)
        }{
            \pi_{\mathrm{ref}}(y\mid x)
        }
        -
        r_\phi(x,y)
    \right].
    }
\end{equation}

Expanding the sequence log-probabilities into tokens gives
\begin{equation}
    \mathcal{L}_{\mathrm{RLHF}}(\theta)
    =
    \mathbb{E}_{x,y\sim\pi_\theta}
    \left[
        \beta
        \sum_{t=1}^{T}
        \log
        \frac{
            \pi_\theta(y_t\mid x,y_{<t})
        }{
            \pi_{\mathrm{ref}}(y_t\mid x,y_{<t})
        }
        -
        r_\phi(x,y)
    \right].
\end{equation}

The optimal unconstrained policy for a fixed reward model and fixed $\beta$ is
\begin{equation}
    \pi^*(y\mid x)
    =
    \frac{
        \pi_{\mathrm{ref}}(y\mid x)
        \exp\left(
            r_\phi(x,y)/\beta
        \right)
    }{
        Z(x)
    },
\end{equation}
where
\begin{equation}
    Z(x)
    =
    \sum_y
    \pi_{\mathrm{ref}}(y\mid x)
    \exp\left(
        r_\phi(x,y)/\beta
    \right).
\end{equation}

The policy-gradient form is
\begin{equation}
    \nabla_\theta J_{\mathrm{RLHF}}(\theta)
    =
    \mathbb{E}_{x\sim\mu,\;y\sim\pi_\theta}
    \left[
        \left(
            r_\phi(x,y)
            -
            \beta
            \log
            \frac{
                \pi_\theta(y\mid x)
            }{
                \pi_{\mathrm{ref}}(y\mid x)
            }
            -
            b(x)
        \right)
        \nabla_\theta
        \log \pi_\theta(y\mid x)
    \right],
\end{equation}
where $b(x)$ is an optional baseline that does not change the expectation but can reduce variance.

\subsection{PPO Formulation}

In practice, RLHF is often optimized with PPO. Let $\pi_{\mathrm{old}}$ be the policy that generated the current rollout batch. Define the token-level state and action as
\begin{equation}
    s_t=(x,y_{<t}),
    \qquad
    a_t=y_t.
\end{equation}

A common shaped reward used for rollouts is
\begin{equation}
    \widetilde{r}_t^{\mathrm{old}}
    =
    \mathbf{1}\{t=T\}
    r_\phi(x,y)
    -
    \beta
    \log
    \frac{
        \pi_{\mathrm{old}}(a_t\mid s_t)
    }{
        \pi_{\mathrm{ref}}(a_t\mid s_t)
    }.
\end{equation}
Summing over tokens gives
\begin{equation}
    \sum_{t=1}^{T}
    \widetilde{r}_t^{\mathrm{old}}
    =
    r_\phi(x,y)
    -
    \beta
    \log
    \frac{
        \pi_{\mathrm{old}}(y\mid x)
    }{
        \pi_{\mathrm{ref}}(y\mid x)
    }.
\end{equation}

Let $V_\psi(s_t)$ be a value function. Using generalized advantage estimation,
\begin{equation}
    \delta_t
    =
    \widetilde{r}_t^{\mathrm{old}}
    +
    \gamma V_{\mathrm{old}}(s_{t+1})
    -
    V_{\mathrm{old}}(s_t),
\end{equation}
\begin{equation}
    \widehat{A}_t
    =
    \sum_{l=0}^{T-t}
    (\gamma\lambda)^l
    \delta_{t+l},
\end{equation}
\begin{equation}
    \widehat{R}_t
    =
    \widehat{A}_t
    +
    V_{\mathrm{old}}(s_t).
\end{equation}

The PPO importance ratio is
\begin{equation}
    \rho_t(\theta)
    =
    \frac{
        \pi_\theta(a_t\mid s_t)
    }{
        \pi_{\mathrm{old}}(a_t\mid s_t)
    }.
\end{equation}

The clipped PPO policy loss is
\begin{equation}
    \mathcal{L}_{\mathrm{policy}}^{\mathrm{PPO}}(\theta)
    =
    -\widehat{\mathbb{E}}_t
    \left[
        \min\left(
            \rho_t(\theta)\widehat{A}_t,
            \operatorname{clip}
            \left(
                \rho_t(\theta),
                1-\epsilon,
                1+\epsilon
            \right)
            \widehat{A}_t
        \right)
    \right].
\end{equation}

The value-function loss is
\begin{equation}
    \mathcal{L}_{V}(\psi)
    =
    \frac{1}{2}
    \widehat{\mathbb{E}}_t
    \left[
        \left(
            V_\psi(s_t)
            -
            \widehat{R}_t
        \right)^2
    \right].
\end{equation}

An optional entropy bonus can be included using
\begin{equation}
    \mathcal{H}
    \left(
        \pi_\theta(\cdot\mid s_t)
    \right)
    =
    -
    \sum_{a\in\mathcal{V}}
    \pi_\theta(a\mid s_t)
    \log
    \pi_\theta(a\mid s_t).
\end{equation}

The full PPO training loss can be written as
\begin{equation}
    \boxed{
    \begin{aligned}
        \mathcal{L}_{\mathrm{PPO}}(\theta,\psi)
        ={}&
        -\widehat{\mathbb{E}}_t
        \left[
            \min\left(
                \rho_t(\theta)\widehat{A}_t,
                \operatorname{clip}
                \left(
                    \rho_t(\theta),
                    1-\epsilon,
                    1+\epsilon
                \right)
                \widehat{A}_t
            \right)
        \right]
        \\
        &+
        \frac{c_V}{2}
        \widehat{\mathbb{E}}_t
        \left[
            \left(
                V_\psi(s_t)
                -
                \widehat{R}_t
            \right)^2
        \right]
        -
        c_H
        \widehat{\mathbb{E}}_t
        \left[
            \mathcal{H}
            \left(
                \pi_\theta(\cdot\mid s_t)
            \right)
        \right].
    \end{aligned}
    }
\end{equation}

Here $c_V\ge 0$ weights the value loss and $c_H\ge 0$ weights the entropy bonus. If the KL penalty is already incorporated through shaped rewards, it should not be added again as a separate identical penalty.
```

