```latex
\section{RLHF: Theory and Loss Functions}\label{section:rlhf}

Let $x$ denote a prompt and let $y=(y_1,\ldots,y_T)$ denote a completion.
An autoregressive language-model policy factorizes as
\begin{equation}
    \pi_\theta(y\mid x)
    =
    \prod_{t=1}^{T}
    \pi_\theta(y_t\mid x,y_{<t}),
    \qquad
    \log \pi_\theta(y\mid x)
    =
    \sum_{t=1}^{T}
    \log \pi_\theta(y_t\mid x,y_{<t}).
    \label{eq:autoregressive-policy}
\end{equation}
We write $\pi_{\mathrm{ref}}$ for a frozen reference policy, usually the supervised fine-tuned model, and $r_\phi(x,y)$ for a learned scalar reward model.

\subsection{Supervised Fine-Tuning}

Given a supervised dataset
\[
    \mathcal{D}_{\mathrm{SFT}}
    =
    \{(x^{(i)},y^{(i)})\}_{i=1}^{N_{\mathrm{SFT}}},
\]
the supervised fine-tuning loss is the negative log-likelihood of the target completions:
\begin{equation}
    \mathcal{L}_{\mathrm{SFT}}(\theta)
    =
    -\frac{1}{N_{\mathrm{SFT}}}
    \sum_{i=1}^{N_{\mathrm{SFT}}}
    \log \pi_\theta(y^{(i)}\mid x^{(i)})
    =
    -\frac{1}{N_{\mathrm{SFT}}}
    \sum_{i=1}^{N_{\mathrm{SFT}}}
    \sum_{t=1}^{T_i}
    \log \pi_\theta
    \bigl(
        y_t^{(i)}
        \mid
        x^{(i)},y_{<t}^{(i)}
    \bigr).
    \label{eq:sft-loss}
\end{equation}
Usually, only completion tokens are included in the loss, not prompt tokens.

\subsection{Reward Modeling from Human Preferences}

For a prompt $x$, sample completions from a policy, often $\pi_{\mathrm{SFT}}$.
Human labelers compare two completions and indicate a preference.
Let $y_w$ denote the preferred, or winning, completion and $y_l$ the dispreferred, or losing, completion.
A dataset of preferences is
\begin{equation}
    \mathcal{D}_{\mathrm{pref}}
    =
    \left\{
        (x^{(i)},y_w^{(i)},y_l^{(i)})
    \right\}_{i=1}^{N}.
\end{equation}

A common model of preferences is the Bradley--Terry model:
\begin{equation}
    p^*(y_w \succ y_l \mid x)
    =
    \frac{
        \exp\bigl(r^*(x,y_w)\bigr)
    }{
        \exp\bigl(r^*(x,y_w)\bigr)
        +
        \exp\bigl(r^*(x,y_l)\bigr)
    }
    =
    \sigma\bigl(
        r^*(x,y_w)-r^*(x,y_l)
    \bigr),
    \label{eq:bradley-terry}
\end{equation}
where
\begin{equation}
    \sigma(z)
    =
    \frac{1}{1+\exp(-z)}.
\end{equation}
More generally, one may introduce a temperature $\tau>0$:
\begin{equation}
    p^*(y_w \succ y_l \mid x)
    =
    \sigma\left(
        \frac{r^*(x,y_w)-r^*(x,y_l)}{\tau}
    \right).
\end{equation}

Parameterizing the latent reward by $r_\phi(x,y)$, the reward model is trained by maximum likelihood.
The negative log-likelihood loss is
\begin{equation}
    \mathcal{L}_{\mathrm{RM}}(\phi)
    =
    -\mathbb{E}_{(x,y_w,y_l)\sim\mathcal{D}_{\mathrm{pref}}}
    \left[
        \log
        \sigma\left(
            r_\phi(x,y_w)-r_\phi(x,y_l)
        \right)
    \right].
    \label{eq:reward-model-loss}
\end{equation}
Equivalently, for a finite dataset,
\begin{equation}
    \mathcal{L}_{\mathrm{RM}}(\phi)
    =
    \frac{1}{N}
    \sum_{i=1}^{N}
    \log\left(
        1+
        \exp\left[
            -\left(
                r_\phi(x^{(i)},y_w^{(i)})
                -
                r_\phi(x^{(i)},y_l^{(i)})
            \right)
        \right]
    \right).
    \label{eq:reward-model-loss-sum}
\end{equation}
With a temperature $\tau$, replace the reward difference by
\[
    \frac{r_\phi(x,y_w)-r_\phi(x,y_l)}{\tau}.
\]

A typical reward model is a language model backbone with a scalar head:
\begin{equation}
    r_\phi(x,y)
    =
    w^\top h_\psi(x,y)+b,
    \qquad
    \phi=(\psi,w,b),
\end{equation}
where $h_\psi(x,y)$ is a pooled or final-token hidden representation.

Because the Bradley--Terry likelihood depends only on reward differences,
\[
    r_\phi(x,y)
    \quad\text{and}\quad
    r_\phi(x,y)+c(x)
\]
induce the same preference probabilities.
Thus, additive reward offsets are not identifiable from pairwise comparisons.
Centering rewards can fix a convention, but centering alone does not reduce variance; scaling or baselining affects the effective scale of the reward and therefore interacts with the KL coefficient $\beta$.

\subsection{KL-Regularized Reinforcement Learning}

After training the reward model, the policy $\pi_\theta$ is optimized to produce completions with high reward while remaining close to a reference policy $\pi_{\mathrm{ref}}$.
The standard RLHF objective is
\begin{equation}
    J_{\mathrm{RLHF}}(\theta)
    =
    \mathbb{E}_{x\sim\mu}
    \left[
        \mathbb{E}_{y\sim\pi_\theta(\cdot\mid x)}
        \left[
            r_\phi(x,y)
        \right]
        -
        \beta
        D_{\mathrm{KL}}
        \left(
            \pi_\theta(\cdot\mid x)
            \,\Vert\,
            \pi_{\mathrm{ref}}(\cdot\mid x)
        \right)
    \right],
    \label{eq:rlhf-objective}
\end{equation}
where $\mu(x)$ is the prompt distribution and $\beta>0$ controls the strength of the KL regularization.

The sequence-level KL divergence is
\begin{equation}
    D_{\mathrm{KL}}
    \left(
        \pi_\theta(\cdot\mid x)
        \,\Vert\,
        \pi_{\mathrm{ref}}(\cdot\mid x)
    \right)
    =
    \sum_y
    \pi_\theta(y\mid x)
    \log
    \frac{
        \pi_\theta(y\mid x)
    }{
        \pi_{\mathrm{ref}}(y\mid x)
    }.
    \label{eq:sequence-kl}
\end{equation}
Using the autoregressive factorization,
\begin{equation}
    \log
    \frac{
        \pi_\theta(y\mid x)
    }{
        \pi_{\mathrm{ref}}(y\mid x)
    }
    =
    \sum_{t=1}^{T}
    \log
    \frac{
        \pi_\theta(y_t\mid x,y_{<t})
    }{
        \pi_{\mathrm{ref}}(y_t\mid x,y_{<t})
    }.
\end{equation}

The corresponding minimization loss is
\begin{equation}
    \boxed{
    \mathcal{L}_{\mathrm{RLHF}}(\theta)
    =
    \mathbb{E}_{x\sim\mu,\;y\sim\pi_\theta(\cdot\mid x)}
    \left[
        \beta
        \log
        \frac{
            \pi_\theta(y\mid x)
        }{
            \pi_{\mathrm{ref}}(y\mid x)
        }
        -
        r_\phi(x,y)
    \right].
    }
    \label{eq:rlhf-loss}
\end{equation}

The KL term prevents the policy from moving too far from the reference distribution.
This helps reduce reward hacking, preserves language quality, and maintains diversity.

\subsection{Optimal Policy}

For a fixed prompt $x$, assuming the normalizing constant is finite, the optimal policy for the KL-regularized objective is
\begin{equation}
    \pi^*(y\mid x)
    =
    \frac{
        \pi_{\mathrm{ref}}(y\mid x)
        \exp\left(
            r_\phi(x,y)/\beta
        \right)
    }{
        Z(x)
    },
    \label{eq:optimal-policy}
\end{equation}
where
\begin{equation}
    Z(x)
    =
    \sum_{y}
    \pi_{\mathrm{ref}}(y\mid x)
    \exp\left(
        r_\phi(x,y)/\beta
    \right).
\end{equation}
Thus, RLHF reweights the reference policy exponentially according to the learned reward.
Smaller $\beta$ allows larger deviations from $\pi_{\mathrm{ref}}$, while larger $\beta$ keeps the policy closer to the reference.

\subsection{Policy Gradient Form}

Although token sampling is discrete, the expected objective can be differentiated using the score-function, or REINFORCE, identity.
Ignoring baselines, the gradient of $J_{\mathrm{RLHF}}$ is
\begin{equation}
    \nabla_\theta J_{\mathrm{RLHF}}(\theta)
    =
    \mathbb{E}_{x\sim\mu,\;y\sim\pi_\theta}
    \left[
        \left(
            r_\phi(x,y)
            -
            \beta
            \log
            \frac{
                \pi_\theta(y\mid x)
            }{
                \pi_{\mathrm{ref}}(y\mid x)
            }
        \right)
        \nabla_\theta
        \log \pi_\theta(y\mid x)
    \right].
    \label{eq:policy-gradient}
\end{equation}
A prompt-dependent baseline $b(x)$ may be subtracted to reduce variance:
\begin{equation}
    \nabla_\theta J_{\mathrm{RLHF}}(\theta)
    =
    \mathbb{E}_{x\sim\mu,\;y\sim\pi_\theta}
    \left[
        \left(
            r_\phi(x,y)
            -
            \beta
            \log
            \frac{
                \pi_\theta(y\mid x)
            }{
                \pi_{\mathrm{ref}}(y\mid x)
            }
            -
            b(x)
        \right)
        \nabla_\theta
        \log \pi_\theta(y\mid x)
    \right].
\end{equation}

\subsection{Token-Level Rewards for PPO}

Define the state and action at token position $t$ as
\begin{equation}
    s_t=(x,y_{<t}),
    \qquad
    a_t=y_t.
\end{equation}
A common implementation assigns the scalar reward at the end of the sequence and applies a token-level KL penalty:
\begin{equation}
    \widetilde r_t
    =
    \mathbf{1}\{t=T\}\,r_\phi(x,y)
    -
    \beta
    \log
    \frac{
        \pi_\theta(a_t\mid s_t)
    }{
        \pi_{\mathrm{ref}}(a_t\mid s_t)
    }.
    \label{eq:token-reward}
\end{equation}
Then the total shaped return is
\begin{equation}
    \sum_{t=1}^{T}\widetilde r_t
    =
    r_\phi(x,y)
    -
    \beta
    \log
    \frac{
        \pi_\theta(y\mid x)
    }{
        \pi_{\mathrm{ref}}(y\mid x)
    }.
\end{equation}

In practical PPO implementations, the KL penalty is often computed using the rollout policy $\pi_{\mathrm{old}}$ and held fixed during the PPO update:
\begin{equation}
    \widetilde r_t^{\mathrm{old}}
    =
    \mathbf{1}\{t=T\}\,r_\phi(x,y)
    -
    \beta
    \log
    \frac{
        \pi_{\mathrm{old}}(a_t\mid s_t)
    }{
        \pi_{\mathrm{ref}}(a_t\mid s_t)
    }.
    \label{eq:ppo-rollout-reward}
\end{equation}

\subsection{PPO Loss}

Let $V_\psi(s_t)$ be a value function, or critic, estimating expected future shaped reward.
Using generalized advantage estimation, define
\begin{equation}
    \delta_t
    =
    \widetilde r_t^{\mathrm{old}}
    +
    \gamma V_{\mathrm{old}}(s_{t+1})
    -
    V_{\mathrm{old}}(s_t),
\end{equation}
\begin{equation}
    \widehat A_t
    =
    \sum_{l=0}^{T-t}
    (\gamma\lambda)^l
    \delta_{t+l},
    \label{eq:gae}
\end{equation}
and
\begin{equation}
    \widehat R_t
    =
    \widehat A_t+V_{\mathrm{old}}(s_t).
\end{equation}
Here $\gamma\in[0,1]$ is a discount factor and $\lambda\in[0,1]$ controls the bias--variance trade-off.
For the exact undiscounted sequence objective, $\gamma=1$ is the natural choice.

The PPO importance ratio at token $t$ is
\begin{equation}
    \rho_t(\theta)
    =
    \frac{
        \pi_\theta(a_t\mid s_t)
    }{
        \pi_{\mathrm{old}}(a_t\mid s_t)
    }
    =
    \exp\left(
        \log \pi_\theta(a_t\mid s_t)
        -
        \log \pi_{\mathrm{old}}(a_t\mid s_t)
    \right).
\end{equation}

The clipped PPO policy loss is
\begin{equation}
    \mathcal{L}_{\mathrm{policy}}^{\mathrm{PPO}}(\theta)
    =
    -\widehat{\mathbb{E}}_t
    \left[
        \min\left(
            \rho_t(\theta)\widehat A_t,
            \operatorname{clip}
            \bigl(
                \rho_t(\theta),
                1-\epsilon,
                1+\epsilon
            \bigr)
            \widehat A_t
        \right)
    \right],
    \label{eq:ppo-policy-loss}
\end{equation}
where $\epsilon>0$ is the clipping parameter and $\widehat{\mathbb{E}}_t$ denotes an empirical average over completion tokens.

The value-function loss is
\begin{equation}
    \mathcal{L}_{V}(\psi)
    =
    \frac{1}{2}
    \widehat{\mathbb{E}}_t
    \left[
        \left(
            V_\psi(s_t)-\widehat R_t
        \right)^2
    \right].
    \label{eq:value-loss}
\end{equation}

An optional entropy bonus encourages exploration:
\begin{equation}
    \mathcal{H}(\pi_\theta(\cdot\mid s_t))
    =
    -\sum_{a\in\mathcal{V}}
    \pi_\theta(a\mid s_t)
    \log \pi_\theta(a\mid s_t),
\end{equation}
where $\mathcal{V}$ is the vocabulary.

The full PPO training loss used in RLHF is therefore
\begin{equation}
    \boxed{
    \begin{aligned}
        \mathcal{L}_{\mathrm{PPO}}(\theta,\psi)
        ={}&
        -\widehat{\mathbb{E}}_t
        \left[
            \min\left(
                \rho_t(\theta)\widehat A_t,
                \operatorname{clip}
                \bigl(
                    \rho_t(\theta),
                    1-\epsilon,
                    1+\epsilon
                \bigr)
                \widehat A_t
            \right)
        \right]
        \\
        &+
        \frac{c_V}{2}
        \widehat{\mathbb{E}}_t
        \left[
            \left(
                V_\psi(s_t)-\widehat R_t
            \right)^2
        \right]
        \\
        &-
        c_H
        \widehat{\mathbb{E}}_t
        \left[
            \mathcal{H}(\pi_\theta(\cdot\mid s_t))
        \right].
    \end{aligned}
    }
    \label{eq:full-ppo-loss}
\end{equation}
Here $c_V\ge 0$ weights the value loss and $c_H\ge 0$ weights the entropy bonus.
The KL penalty is already incorporated through the shaped rewards in Eq.~\eqref{eq:ppo-rollout-reward}; it should not be added again as a separate identical penalty unless the implementation explicitly intends an additional regularization term.
```

