% 正向运动学
function [endPos, T] = forward_kinematics(theta)
    global DH_params;

    theta = theta(:);
    numJoints = size(DH_params, 1);

    if numel(theta) ~= numJoints
        error('关节角数量必须与DH参数行数一致。');
    end

    T = eye(4);

    for i = 1:numJoints
        T = T * dh_matrix(DH_params(i, :), theta(i));
    end

    endPos = T(1:3, 4);
end

% 标准 DH 矩阵
function T = dh_matrix(params, theta)
    a = params(1);
    alpha = deg2rad(params(2));
    d = params(3);

    ct = cos(theta);
    st = sin(theta);
    ca = cos(alpha);
    sa = sin(alpha);

    T = [
        ct, -st * ca,  st * sa, a * ct;
        st,  ct * ca, -ct * sa, a * st;
        0,        sa,       ca,      d;
        0,         0,        0,      1
    ];
end

% 可视化 Pareto 候选解
function visualize_results(fval, runIdx)
    if isempty(fval)
        return;
    end

    figure('Name', sprintf('Pareto Front - Run %d', runIdx), ...
        'NumberTitle', 'off');

    scatter(fval(:, 1), fval(:, 2), 30, 'filled');

    xlabel('End Effector Error (mm)');
    ylabel('Energy Index');
    title(sprintf('Pareto Front - Run %d', runIdx));

    grid on;
end

% 显示每次运行中的代表性解
function disp_results(x, fval)
    if isempty(x) || isempty(fval)
        return;
    end

    [minError, minErrorIdx] = min(fval(:, 1));
    [~, maxEnergyIdx] = max(fval(:, 2));

    print_solution('最高能耗点', ...
        x(maxEnergyIdx, :), fval(maxEnergyIdx, :));

    print_solution('最低误差点', ...
        x(minErrorIdx, :), fval(minErrorIdx, :));

    % 均衡点：误差不超过最低误差的 1.1 倍，然后选择其中能量指标最低者
    balancedIdxList = find(fval(:, 1) <= 1.1 * minError);

    if ~isempty(balancedIdxList)
        [~, localIdx] = min(fval(balancedIdxList, 2));
        balancedIdx = balancedIdxList(localIdx);

        print_solution('均衡点', ...
            x(balancedIdx, :), fval(balancedIdx, :));
    else
        disp('未找到均衡点。');
    end
end

% 统一打印函数，避免索引混用
function print_solution(label, theta, fval)
    fprintf('\n%s - 关节角度（度）:\n', label);

    disp(array2table(rad2deg(theta(:).'), ...
        'VariableNames', ...
        {'Joint1', 'Joint2', 'Joint3', 'Joint4', 'Joint5', 'Joint6'}));

    fprintf('%s - 目标函数值:\n', label);

    disp(array2table(fval(:).', ...
        'VariableNames', ...
        {'EndEffectorError_mm', 'EnergyIndex'}));
end
