        for (int i = 0; i < n; i++) {
            cin >> a[i];
            mn = min(mn, a[i]);
            mx = max(mx, a[i]);
        }

        int len = (n - 1) % k + 1;
        int need = len / 2 + 1;

        vector<int> dp(len + 1);

        auto possible = [&](int x) -> bool {
            const int NEG = -1000000000;
            fill(dp.begin(), dp.end(), NEG);
            dp[0] = 0;

            for (int start = 0; start < n; start += k) {
                for (int j = 1; j <= len; j++) {
                    int good = (a[start + j - 1] >= x);
                    dp[j] = max(dp[j], dp[j - 1] + good);
                }
            }

            return dp[len] >= need;
        };

        int lo = mn, hi = mx;

        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;

            if (possible(mid))
                lo = mid;
            else
                hi = mid - 1;
        }

        cout << lo << '\n';
    }

    return 0;
}
```

